local Text_Mail = readonly({
  Mail_100480_Desc = {
    Text = "守秘者、聞いていますか？郊外のその偏僻なアートギャラリーがもうすぐ営業を停止するそうです、私の誕生日の日に。\nそのギャラリーはアート界の怪物で、半身は未来主義の浅はかな試作品、半身は二世紀前のゴミの残骸。狭いその体の中には、オークションで誰も触れたがらない奇妙なものたち：汚い言葉を言う肖像画、決して止まることなく飛ぶ機械の鳥、見ると吐き気を催す海の彫刻、涙で作られた像、絶えず自動的に書き続ける幽霊の原稿、キスをすると童謡を歌う人間の頭蓋骨…………\nどれほどこのギャラリーを愛しているか、あなたに説明するのは難しい！50年前の今日、それは誰も気に留めない場所にひっそりと誕生した。50年後の今日、それはその場所でひっそりと消えていく。\n私の子供の頃から、今日という日は呪いだと言われてきた、私のように。運命はすでに定められているのかもしれないが、運命が定められていても何だというのか！このギャラリーが創造したのは、かけがえのない世界で、狂ったアイデアがその小さな空間に積み重なり、どれほど美しい光景であったことか！生まれたその日から、彼はその展示品を使って創作を続けていた。彼の終焉の日に、彼の親友と旧友も最後の別れを告げるだろう。\n守秘者、あなたはリンクの中で私の目に映る世界を見たと思います、あなたも私と一緒にこの奇妙なギャラリーを見に行くことを楽しみにしているでしょう、そうでしょう？\n\nピクマン"
  },
  Mail_100480_Name = {
    Text = "誰も気にしない展示館"
