  Mail_100480_Sender = {
    Text = "ピックマン"
  },
  Mail_116602_Desc = {
    Text = "敬愛なる守秘者：\n「極昼の終夜」イベントは終了しました。残りの「拝謁の礼」、「懺悔奉納」、「忠誠奉納」をそれぞれ「薔薇金券」× 40 と交換しますので、守秘者の方はお忘れなくご確認ください。"
