  Mail_116602_Name = {
    Text = "献礼回収"
  },
  Mail_116602_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_117308_Desc = {
    Text = "尊敬なる守秘者：\n        『忘却前夜』へのご支援とご理解、誠にありがとうございます。ミサゴ大学でのゲーム体験をより良くするために、以下の体験調査アンケートへのご協力をお願い申し上げます。ご協力いただいたお礼として、「シルバーコア」× 200を用意いたしました。アンケートを完了すれば受け取れます。アンケートの締切は11月10日9:00ですので、ぜひお早めにご記入ください。\n        <SurveyLink:[クリックして記入する]>\n        皆様のご意見を真摯に受け止めます。皆様のフィードバックは、ミサゴ大学をより良くするために必ず役立ちます！\n        ——銀の鍵が前路を導きますように。"
  },
  Mail_117308_Name = {
