  Mail_117308_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_117309_Desc = {
    Text = "尊敬なる守秘者：\n        『忘却前夜』へのご支援とご評価、誠にありがとうございます。ミサゴ大学でのゲーム体験をより良くするために、以下の体験調査アンケートにご協力いただけますようお願い申し上げます。ご協力いただいた感謝の気持ちとして、「シルバーコア」× 200を報酬としてご用意しております。アンケートの締切は3月30日9:00ですので、忘れずにご記入ください。\n        <SurveyLink:[クリックして記入]>\n        私たちはすべての守秘者のご意見を真摯に受け止め、皆様のフィードバックがミサゴ大学をますます良くすることを確信しております！\n        ——銀の鍵が前路を導きますように。"
