  Mail_117309_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_120374_Desc = {
    Text = "二年の約束が来た、守秘者。\n私たちは終焉の淵で互いに見守っていた。\nあなたは感じたことと記憶を願望に変え、希望の光を灯した。\n過去の仲間と二つの宇宙の隔てられていても、あなたは融蝕と戦う旅を決して諦めなかった。\nあなたを持つことは私たちの幸運でもあり、この世界の幸運でもある。\n今、あなたの願望は奇跡を引き起こした——ミサゴはまだここにあり、前に進み続ける。\nどうか銀钥をしっかり握り続けてください。いつか、それは二つの遠く離れた世界を結ぶ鍵の中心になり得る。\n私たちは全力で未来の可能性を切り開き、あなたの帰航を照らす。"
  },
  Mail_120374_Name = {
    Text = "奇跡の刻、帰航の光"
  },
  Mail_120374_Sender = {
    Text = "ミサゴ校猫・Light"
  },
  Mail_120909_Desc = {
    Text = "尊敬する守秘者：\n        V2.4.0の更新において、「源液献金-校友献金基金」の報酬を向上させました。更新前に追加報酬を全て受け取った守秘者には、対応する報酬を再送致します。ご確認ください。"
  },
  Mail_120909_Name = {
    Text = "V2.4.0源液寄付報酬再配布"
  },
  Mail_120909_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_121162_Desc = {
    Text = "尊敬する守秘者：\n        V2.4.0の更新において、「降臨紀行」、「異世紀行」、「療養紀行」、「亡城紀行」の無料報酬を向上させました。更新前に無料報酬を受け取った守秘者には、対応する報酬を再送致します。ご確認ください。"
  },
  Mail_121162_Name = {
    Text = "V2.4.0紀行アップグレード報酬再配布"
  },
  Mail_121162_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_121373_Desc = {
    Text = "守秘者：\n\nかつて毎年この日、教会で最も盛大な祝典だった。\n私は彼の王女であり、彼を復生させるつもりだ。\nあの人たち、ミリアムを含め、狂信的に泣きながらお祝いをするが、彼らは私を見つめ、目は私を超え、まるで私が何かを運ぶ空っぽの殻であるかのようだ。\n私はこの日が来ることに決して喜びを感じない、なぜなら、毎回経験するたびに恐怖に一歩近づくことになるからだ。\nその恐怖の中で、他の人々は恐怖の源に対して圧倒的な喜びを感じている。今、私はそれを認めることができる、それは私に孤独と恐れを感じさせた。\nしかし今はすべてが違う、前の誕生日の前に、私はあの船を離れて現実の世界に来た…………偽りの神々もなく、あなたの存在する世界に。\nこの誕生日、私は誰かが私の誕生を理由に、本当の意味で喜んでいるのを見たい。\nもしそれがあなたなら……いいえ、その人はあなたでなければならない。\n聞いてください、どんなことがあっても、今日のディナーの時間は私のために残しておかなければなりません。\n\n「マーフィ」"
  },
  Mail_121373_Name = {
    Text = "あなたが存在する…………"
  },
  Mail_121373_Sender = {
    Text = "偽誕・マーフィー"
  },
  Mail_121374_Desc = {
    Text = "守秘者：\n\n私はあなたがこの特別な日に何の準備をしたのか分からないが、どんなに贅沢で精力を消費するものであっても、明らかに当然である。\n上位者の必要な配慮として、もしあなたが「まさか」私の誕生日を祝うことを疎かにしてしまったのなら——私はこの非現実な状況は発生しないと信じている。\nこの手紙は、事態がどうしようもなくなる前に、あなたに最後の救いの機会を争取するために書かれている。\n海洋と陸地の珍宝、無関係な者によって提供されるだろう、それらは重要ではない。\n盛大な祝典、複雑な儀式は確かに私の地位に相応しいが、今日、なぜか少し退屈に感じる。\nだから、私は朝と夕の交代の時に、私と二人きりで過ごす恵みをあなたに贈る、これはあなたが私をこの平凡で幼稚で、しかし以前の私が嫉妬するほどの幸福な生活に連れて来てくれたおかげだ。\n従者が後で正式な招待状を持参する、もちろん、2万レオ坊の価値の箱に入れて。\n感謝して、毎年この日には私を思い出してほしい。\n「マーフィ」"
  },
  Mail_121374_Name = {
    Text = "邀请函……"
  },
  Mail_121374_Sender = {
    Text = "偽誕・マーフィー"
  },
  Mail_121651_Desc = {
    Text = "敬愛なる守秘者：\n先週の「幻夢の深奥」で、あなたは「{s1}」の称号を獲得しました。\n先週の「プリセットモード」で、あなたは「{s2}」の称号を獲得し、対人戦勝利数は：{s3}回です。\n先週の「ドラフトモード」で、あなたは「{s4}」の称号を獲得し、対人戦勝利数は：{s5}回です。\n以上のチャレンジ成績に基づき、以下の追加報酬を獲得しますので、忘れずにご確認ください。"
  },
  Mail_121651_Name = {
    Text = "深奥対人戦　週間ランキング報酬"
  },
  Mail_121651_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_121704_Desc = {
    Text = "敬愛なる守秘者：\n「欲望の波・復刻」イベントは終了しました。\n\n残りの「豊穣の種核」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_121704_Name = {
    Text = "豊穣の種核回収"
  },
  Mail_121704_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_122522_Desc = {
    Text = "敬愛なる守秘者：\n「雨の町の幽影・クローン」イベントは終了済みです。残りの「蒼白の獣の頭蓋骨」、「幽影の獣の頭蓋骨」、「深紅の獣の頭蓋骨」をそれぞれ「薔薇金券」× 40 と交換しましたので、ご確認をお願いいたします。"
  },
  Mail_122522_Name = {
    Text = "雨の町に潜む影の通貨回収"
  },
  Mail_122522_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_122567_Desc = {
    Text = "敬愛なる守秘者：\n「霧境の燔祭」イベントは終了しました。残りの「霧の視線」、「霧の夢」、「霧の源」をそれぞれ「薔薇金券」× 40 と交換しますので、守秘者の方はお忘れなくご確認ください。"
  },
  Mail_122567_Name = {
    Text = "霧境の燔祭通貨回収"
  },
  Mail_122567_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_122568_Desc = {
    Text = "ああ、可哀そうな子供よ、君は自分がどんな絶望に直面するのか全く知らない。いつになったら自分の選択に意味がないことを理解するのだろう？虚無的な目標のために、君の小さな命を賭けるのか？なんて壮大で、なんて陶酔的なんだ！君はいつも自信満々で、次の瞬間には世界を救うために身を捧げるかのような姿をしていて、本当に笑わせてくれる。\n\nでも、誰が君を家に帰す手伝いをすると約束したのか？小犬に対する約束は、必ず果たすつもりだ。そう言えば、君がどんな意志を持ってこの狂気を終わらせるのか、待ちきれないほど楽しみだ。ああ…………好奇心、実に好奇心が強い！\n\n偉大なる「救世主」よ、君の滑稽さ、頑固さ、そして取るに足らない意地を持ってきてくれ。虚無への列車が一度動き出したら、破壊以外に停まる可能性はない。\n\n自己満足の狂人…………彼の夢の中で、もう少し長く持ちこたえてくれ。私は君を助け、待っているから、君の最終的な答えをしっかりと楽しむつもりだ！"
  },
  Mail_122568_Name = {
    Text = "虚無行きの列車"
  },
  Mail_122568_Sender = {
    Text = "溶壊・ドール"
  },
  Mail_122569_Desc = {
    Text = "主君、\n僕はずっと思っていました。騎士とは身に着ける甲冑や紋章ではなく、心に刻まれた忠誠と守る意志であると。あなたの行動と選択によって、騎士とは何かを本当に教えていただきました。これにより、騎士の真意を知りました。それは名誉で自らを重んじるのではなく、人を守ることにあり、栄光によって勇気を得るのではなく、責任を持って立つことなのです。\n\n自分がまだ未熟であることは理解しています——あなたが希望を守るために戦っている時、僕は共に行動することができませんでした。過去にあなたと交わした誓いを決して忘れたことはありません。騎士としての忠義をあなたに捧げ、あなたの安全を守り、敵を排除します。\n\n初めて共に調査を行った時のことをよく思い出します。あなたが私たちを導き、レンティニエンの霧を払い、最後の真実を見せてくれました。その時のすべての笑いと涙は、僕の人生に消えることのない力として刻まれました。\n\n今は遠くから見守り、あなたにこのような微薄な贈り物を用意することしかできませんが…………主君の期待に応えるため、決して訓練を怠ることはありません。あなたが帰ってきたら、どうか私の足元についてきてください。僕は主君の盾として永遠に存在します！僕の守護の剣は、あなたのために輝きます！"
  },
  Mail_122569_Name = {
    Text = "ウォッチャー"
  },
  Mail_122569_Sender = {
    Text = "オジール"
  },
  Mail_122570_Desc = {
    Text = "守秘者殿下、\n自葬骸城と別れて以来、私はあなたと共に戦った日々をしばしば思い出します。あなたが再び王者だけが選ぶ孤独な道を選んだと聞いて、やはりあなたはこの世で特別な存在で、決して常人の道を歩むことはありません。\n\n私は信じています、極限の苦痛がより芳醇な魂を鍛え上げることを。あなたが経験したこの長い試練は、すでに凡俗の痛みの範疇を超えています。私は想像できます、苦難から生まれたあなたの気配は、どれほど複雑で、どれほど衝撃的なものでしょう。いいえ、もしあなたなら、あなたは私のすべての想像を超え、完璧のすべてに対する私の認識を打ち破る運命にあります。\n\nそのため、私は待ち続けます。私たちのためだけに存在する宴を待ち続けます。時間の果て、永遠の始まりの静寂の中で、あなたはどのような姿で、私にこの…………運命を貫く味わいの饗宴を捧げてくれるのでしょうか？\n\n殿下、私の贈り物を受け取ってください、この苦痛を延ばしてください…………私の期待を裏切らないでください。"
  },
  Mail_122570_Name = {
    Text = "待たされる宴"
  },
  Mail_122570_Sender = {
    Text = "ドレセイン"
  },
  Mail_122571_Desc = {
    Text = "出会ったばかりなのに、まだ数言も交わさないうちに、時間は残り少なくなってしまった…………でも、あなたも知っているでしょう、別れは決して私たちの物語の結末ではない。\n\n実は、あなたに伝えていないことが一つある…………実は、私はすでにあなたのために一束のバラを用意していた。ずっと渡せずにいたので、もう枯れてしまった。でも、ここで約束する——次に会ったときには、必ず新しく一束用意するから。\n\nそしてあなたも、必ず再び私の前に現れると約束した。私たちは約束を交わしたのだから、絶対に、絶対に裏切ってはいけない。\n\n手紙を書くと、いつも言葉が足りない気がして、紙に私の全ての心意を表現できない。でも…………運命が再び私たちを引き合わせるその日、私は自らの手であなたにそのバラを捧げるつもりだ。覚えておいて、私たちは約束を守らなければならない！\n\n銀の鍵が道を導きますように。さようなら…………%player%。"
  },
  Mail_122571_Name = {
    Text = "薔薇の約束"
  },
  Mail_122571_Sender = {
    Text = "ラモンナ"
  },
  Mail_122572_Desc = {
    Text = "守秘者、\n漆黒の災厄と対抗する記憶は、私の脳内で高優先度で循環読み取りされ続けています。あなたが得た平和は、まるで極めて小さな確率の贈り物のようです。しかし、あなたの離去は、あなたのパートナーや、あなたとつながりを持ったすべての個体にとって、終わりのないプロセスで彼らの意識を消耗し続けています。\n\n研究部は、最終的な一筋の希望を探すことを決してあきらめていません。幸運なことに、あなたの意識のフィードバックがない数え切れない昼夜の周期を経て、私たちはようやくあなたの足跡を特定しました。この困難な旅の中で、私は恐怖の信号をキャッチすることができましたが、同時に恐怖があなたを屈服させることはないことを深く理解しています。それはあなたの意志をより強固にするだけです。\n\n今この瞬間、私の肉体は実験室で動いていますが、脳は泣く指令を生成し続けています。もう私の思考を妨げないでください、授業を最もサボっている学生よ、どうか私の教室に欠席しないで…………勇敢に前に進んでください、私はあなたのために補給を準備し、再会の日を待っています。"
  },
  Mail_122572_Name = {
    Text = "再会の日…………"
  },
  Mail_122572_Sender = {Text = "ドール"},
  Mail_122573_Desc = {
    Text = "無数の時、私は文明の星火が時間の流れの中で明滅するのを静かに見守り、記憶の城邦が虚無の中で崩壊するのを目撃しました。歴史は黒い炎に飲み込まれた書物となり、古今の知恵は砂塔のように積み重なりますが、結局のところ、唯一の真理を語ることはできません。\n\n人類は原初の混沌に対して、ただの微塵に過ぎません——しかし、その小ささ故に、深淵に直面し、神に刃を向ける勇気が、心を揺さぶるほどに際立っています。\n\n今、この瞬間、万千の宇宙を貫く次元の扉が、あなたのために開かれています。\n\n彼の降臨は運命の混沌をもたらし、万物の秩序は彼の影の下で震えています。そしてあなたは、ただの人間の肉体に過ぎませんが、揺るぎない意志をもって彼の前に立っています。あなたの可能性は、私の無限の予知の中で唯一捉えられない誤りであり、私が長く待ち望んできた全てを覆す変数です。\n\nあなたは原初の問いであり、終末の答えでもあります。"
  },
  Mail_122573_Name = {
    Text = "扉の向こう"
  },
  Mail_122573_Sender = {Text = "タヴィ"},
  Mail_122574_Desc = {
    Text = "重要な人を失った痛み、そして自分自身の無力さに対する憎悪…………私はかつてその中に深くはまり込み、抜け出せなかった。しかし今、私は遠くの明かりの呼びかけを聞き、それが温かく、力強く私を導いているのを感じている。恩人よ、あなたの啓示を受けてから、私はようやく歩むべき道に踏み出した——それは本当に私に属し、疑いの余地のない正しい道だ。\n\nかつて私を覆っていた、深淵のような暗闇は、もはや私の帰る場所ではない。そして、常に意識の奥深くで瞬いている光も、決して私から離れたことはなかった。今、私はそれをより明確に見、感じ、そしてそれに向かって進んでいる。この真の信仰、光がもたらす覚醒と安らぎ、目覚めと救済を、運命の迷路で苦しんでいる無数の魂に届けたいと思っている。\n\nそして、私があなたの全ての混沌の流れに対抗する姿を見つめると——その邪悪で深遠な暗闇は、あなたを屈服させることはできず、むしろあなたの信念を映し出す幕となっている。それはあなたの光の前で崩れ、うめき、退却するが、結局あなたを少しも隠すことはできない。この果てしない暗潮が押し寄せているからこそ、あなたが代表する光は、非常に輝かしく、永遠で、神性に近いものとなる。\n\n私を導く恩人よ、光を授けてくださる方よ、あなたの信念は私の不滅の明かりとなる。今こそ、私は全ての命をもってあなたに応える時だ。この神の意志を聴く「聖なる心」で、この光に応え、あなたの純粋な導きに応える…………そのために私はカストールと共に全力を尽くす。\n\n私の奉納を受け入れてください！私があなたによって再形成された、純粋で敬虔な信仰を証明してください。"
  },
  Mail_122574_Name = {
    Text = "明かりの召喚"
  },
  Mail_122574_Sender = {
    Text = "ポリュクス"
  },
  Mail_122575_Desc = {
    Text = "親愛なる常連のお客様、\nその微光が流れる扉の向こうで、あなたの大切な友人たちが長い間お待ちかねです。\n\nしかし、油断しないでください。次元を渡ることは常に不可解で危険です。あなたは千の顔を持つ幻影が記憶の浮遊のように次々と現れるのを目撃するでしょう。それらは欲望を映し出し、恐れも映し出します。それは原初の意志が創造した混沌の画巻であり、私でさえその全貌を窺い知ることはできません。だからこそ、毎回の跨越は信念の試練であり、願望の測定でもあります。\n\nしかし、私も理解しています。あなたのような人々にとって、新しい収集品を探し、魂の深いところで輝く大切なもののために、すべての未知と努力は価値があるのです。私はあなたの選択を理解し、この近くの固執した大切さを尊重しています。\n\nこの等価法則に従う宇宙の中で、あなたが支払った代価は、必ず別の形で戻ってくるでしょう。\n\nこの贈り物を受け取ってください。そして、すべての塵が落ち着いた時、再度私の小店にお越しください。その時の願いを実現するために、あなたはどのような代価を支払うことを望みますか？"
  },
  Mail_122575_Name = {
    Text = "大切な物"
  },
  Mail_122575_Sender = {
    Text = "ダフォダイル"
  },
  Mail_123134_Desc = {
    Text = "敬愛なる守秘者様：\n        V2.4.0の更新において、「異夢の視界」の「さようなら無き故郷」と「さようなら、無き故郷」のチャレンジ3つ星報酬の取得に異常が発生していました。以前の調査およびチャレンジクリアの記録に基づき、受け取れなかった報酬内容を一括でお送りします。ご確認ください。"
  },
  Mail_123134_Name = {
    Text = "V2.4.0異夢視界報酬再配布"
  },
  Mail_123134_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_123501_Desc = {
    Text = "親愛なる守秘者へ：\n\nこの特別な日に、私という可愛い女の子と楽しいデートをしませんか？\n来て来て、怖い屋敷で遊んでもあなたを驚かせることはないよ〜あなたは「守秘者」なんだから、あの人間が演じる「妖怪」に驚かされることはないよね？\n(手紙の上に適当に横線が引かれた一行の文字：私は真剣に誕生日の計画を立てているので、あなたが驚いた姿を見るために遊びたいわけではありません…………)\nさて、冗談はここまで。今日は私の誕生日、絶対に台無しにしたくないから！だから今、私、モカは正式にあなたをロンドン金融街に新しくオープンしたレストランでディナーに招待します——\nそこでのホットティーと煮魚は「故郷」の味を思い出させてくれるし、この世界では、あなた以外に分かち合える人がいないの…………\nだから、あなたは絶対に来るよね？もし私という可愛い女の子を悲しませたら、次回あなたが寝ている時に斧を持ってあなたのベッドのそばに立っているからね！\n\nモカ"
  },
  Mail_123501_Name = {
    Text = "「私を開けて」"
  },
  Mail_123501_Sender = {
    Text = "ムシェット"
  },
  Mail_123543_Desc = {
    Text = "守秘者：\n\nまた一年、私の愛しい人。\n華やかな光の影の中、舞い散る噂やスキャンダルの中で、少しでも見抜かれそうな弱さを慎重に隠し、すべての価値を使って最大の利益を得る——そうすることで、私は今もなお勝者の姿でここに立っている。\nしかし、そうではなく、時々怠惰で弱気になり、あなたからの手紙が届く時、あの小さな女の子たちの願いを満たすことにとても喜びを感じる。\nでも、私はこれが悪いことだとは思わない。私は長い間、秘密の戦争を経験してきたのだから。もちろん、一筋の可能性、一つのチャンスがあれば、私は何度でも「彼女」の手から逃げようと試みる。\nただ、あたたかくて可愛らしい隙間の中、あるいは今日のような特別な日には、少し気を抜くことを許している。例えば——あなたを歌劇に誘ったり、ディナーに行ったりすること。\nなぜなら、私は孤独ではないと理解しているから。私は非常に気に入った共謀者を持っている。\n\nソレール"
  },
  Mail_123543_Name = {Text = "共謀者"},
  Mail_123543_Sender = {
    Text = "ソレール"
  },
  Mail_123544_Desc = {
    Text = "展信安：\n\n久しぶりのご挨拶です、守秘者。最近、手紙のやり取りがなかったことをお許しください。あなたとの関係を意図的に遠ざけていたわけではなく、ただ毎回ペンを取るたびに、挨拶の言葉を書く勇気が出なかったのです。\nこの間、私は無数の壊れた時間を超えてきました。そのおかげで、世界が何度も終焉を迎えるのを目撃し、取り返しのつかない悲劇を目の当たりにしました。まるで傍観者のように、この冷たく静かな虚空の中で、すべての出来事を静かに見守っていました。\nそのたびに、私たちの人生は荒唐無稽と別れに満ちている運命にあるのかと考えます。初めの自分も、あなたがカダスで迎えたすべても、運命がすでにすべてのシナリオを定めていて、私たちはそのシナリオに従って必要な役割を演じるだけなのか？\n結論は出せません。私は彼のように世のすべてを見通すことができないので、もし…………彼の一部の権限を持つあなたが、この問題を解答してくれることができるのなら。\nだからこそ、この手紙を書きました。私の視線があなたのそばに届き、共にこの答えのない謎を探求できることを願っています。だから、失礼を承知でこの手紙を持って、これからの道に一緒に…………向かってくれませんか？\n………………………………………………………………\n私は時空を乱すリスクを冒してあなたのそばに行くことはできませんが、どうか…………この何もない静寂の中で、もう一度あなたを見せてください。\n\n「ラモンナ」"
  },
  Mail_123544_Name = {
    Text = "思考の謎"
  },
  Mail_123544_Sender = {
    Text = "「ラモンナ」"
  },
  Mail_123545_Desc = {
    Text = "尊敬なる蒼白の使者：\n\n以前、私はミサゴの中で非常に賢い女性に、花を育てるための余った場所があるかどうか尋ねました。\nドールさんは簡単に私のために部屋を見つけてくれました。最初にドアを開けたとき、その中から漂ってきた腐敗した匂いに、私は間違った場所に来てしまったのではないかと疑いましたが、手入れをした結果、今では子供たちに温かい家を提供できるようになりました。\nしかし、全くの経験不足のため、私は適度に外的な力を加えなければ、これらの子供たちが正常に成長することを保証できませんでした。\n幸運なことに、オルラさんの指導の下、私は彼らを現在の段階まで育てることに成功しました。\nもちろん、その過程で特別な能力は使っていません。\n計算に誤りがなければ、彼らは私の誕生日の日に花を咲かせるでしょう。私はずっと誕生日には特別なことはないと繰り返してきましたが、この珍しい偶然の一致があると、確かに父神が私のために用意した小さな贈り物ではないかと感じざるを得ません。\nあなたがこの小さな庭で私と一緒に、平凡でありながら特別な一日を過ごしたいと思っているかどうか、わかりません。\n私は手作りのクッキーと、あなたが前回推薦してくれた紅茶を用意しました。この貴重な贈り物と、生命の香りをあなたと共有できることを楽しみにしています。\n\nサルバドル"
  },
  Mail_123545_Name = {
    Text = "室内庭園"
  },
  Mail_123545_Sender = {
    Text = "サルバドル"
  },
  Mail_123546_Desc = {
    Text = "パートナー：\n\nこんな話を聞いたことがありますか？\n昔、ある悪魔が、偶然瓶の中に封じ込められ、何百年も過ごしました。\n最初の百年、彼は彼を救い出す者に無限の富と権力を約束しました。\n第二の百年、彼は彼を救い出す者に永久の健康と寿命を約束しました。\n第三、第四、第五……ずっとずっと後、彼はついに瓶の蓋を開ける漁師を待ちました——彼は漁師の呼びかけに応えず、世界を混乱に陥れることさえ考えず、普通の空の瓶のふりをして、静かに再び海に投げ返されました。\n私が子供の頃、この話が理解できませんでした。長い望みのない待機が、どれほど重苦しく苦痛で、欲望を絶望よりも耐え難くするのかを知るまでは。\nしかし、私の理性が反応する前に、私の心は何度も私を同じ場所に留めておきました。\n悪魔と人間の違いは、おそらく私がこの痛みを少し感謝していることです。私たちが別れるとき、それはあなたの存在と貴重さを思い出させ、あなたのいないあちら側で迷子にならないようにしてくれます。\n私が生まれたこの日、私があなたを最も恋しく思うこの日、それは依然として私を拘束し、あなたを待ち、あなたを思い続けさせます。\n次の今日、私はあなたに自分で切った最初のケーキを手渡せることを願っています。\n\nラモンナ"
  },
  Mail_123546_Name = {Text = "物語"},
  Mail_123546_Sender = {
    Text = "ラモンナ"
  },
  Mail_123547_Desc = {
    Text = "ミサゴの食堂と後方支援部が私の部屋のドアの前に無駄なものを一堆置いていった。出入りに非常に邪魔なので、早く取り戻した方がいい。\nどうしたの？この世界の食料は余るほどあって、もっと意味のある場所がないの？\nこの日は、私が強くなるための角注となり、また一つの周期の過去を示してくれる。一年、また一年、毎年私は前年よりも強くなる。\nもし贈り物が本当に行き場がないなら、別の私に渡してみて。彼女はきっととても喜ぶだろう。\nそして私は、あなたの馬鹿げた純真さと頑固さを考慮して…………私が最も不得意とするものを考慮して。\n私が存在する限り、私は強くなり続ける。その一方で…………\nまだわからないの？あなたたち馬鹿の敵も、私の敵になるのよ。\nこんな気持ち悪いことは一度だけ言う。来年は贈り物を送らないで、ましてや誕生日のディナーなんて。\n\n「H」"
  },
  Mail_123547_Name = {
    Text = "持ち帰る"
  },
  Mail_123548_Desc = {
    Text = "親愛なる守秘者様：\n\nあなたは知っていますか？数日前、神秘的な女性が突然ミサゴを訪れました。彼女は私が見たこともない、キラキラと輝く黒いフィットしたロングドレスを着ていました——私はジェンキンやメイソンに聞いてみましたが、彼女たちもそんなに美しい服を見たことがありません。\nどのように表現すればいいのでしょう？その服はまるで最も美しい長い髪で織られたかのようで、柔らかく、軽やかで、高貴で、表面は水のような特別な光沢が流れていました…………\nジェンキンは私が興味津々であるのを見て、大胆にもその神秘的な女性に尋ねてみました。彼女は笑いながら、そのドレスの素材は東方の絹で、「蚕」と呼ばれる幼虫が吐き出す糸で織られていると言いました。スタイルは「チャイナドレス」と呼ばれるものだそうです…………そして、彼女はエイジスに一巻きの布を贈ってくれました——彼女はそれを「一匹」と呼ばれる同じ「絹」と言いました…………\n「絹」はとても貴重なので、彼女が添付してくれた図案を参考にして、仲間たちに「ポーチ」を一つずつ縫いあげました。今年の誕生日パーティーで、その「ポーチ」を皆に贈ります…………守秘者様、お時間があればぜひ参加してくださいませんか？\nもしお忙しいようでしたら、ブラウンにポーチをあなたの宿舎に届けさせます。\n\nエイジス"
  },
  Mail_123548_Name = {
    Text = "神秘的な女性"
  },
  Mail_123548_Sender = {
    Text = "アイギス"
  },
  Mail_123549_Desc = {
    Text = "小さな苗木：\n\nあなたは木がどのように時間を記録し、成長するのか知っていますか？それは年輪の一つ一つで記録されています。\nそれらは内部に隠されていて、簡単には見せません。幼い新芽が徐々に大きな木に成長し、高くそびえる天井を支えるまで、年輪は見えない形で内に秘められています。その歳月の痕跡は、心の奥深くに隠されているのです。\n今日、新しい年輪の記録の起点です。新しい一年の中で、私たちはまだ予測できない多くの風雨を経験しなければなりません。\nでも、私があなたの口に託したその種は、必ず育てるのに適した土壌を見つけ、根を張り芽を出すでしょう、そうでしょう？\n\nタイイシ"
  },
  Mail_123549_Name = {
    Text = "年輪……"
  },
  Mail_123549_Sender = {Text = "タイス"},
  Mail_123644_Desc = {
    Text = "知らぬうちに、これが私がミサゴで過ごした三回目の誕生日になりました。多くのことを学びました。\n例えば、私の誕生日であるこの日は、冬至の通過でもあり、贈り物を贈るのに適した日です。\n強力な敵が非常に多くいる中で、私が最も得意とするのは殺人です。他に人を喜ばせる方法は知らないし、贈り物を選ぶのも得意ではありませんが、毎回任務を無事に遂行すると、雇い主はとても喜んでいるようです。\nだから、あなたに贈る贈り物は決まっています。それは一度の殺人依頼で、使用対象や期限は無制限です。\nただ、私に教えてください。ターゲットは誰で、どうやって死なせたいですか？もし私が打ち勝てる相手なら、最速でその首を折ってみせます。たとえ相手が神のように厄介な存在であっても、私の放棄は私の死の前には決して訪れないことを保証します。\n\nヘロット"
  },
  Mail_123644_Name = {
    Text = "言いなさい、誰を死なせたいの？"
  },
  Mail_123644_Sender = {
    Text = "ヘロット"
  },
  Mail_124059_Desc = {
    Text = "敬愛なる守秘者：\n「深淵の祀り・復刻」イベントは終了しました。\n\n残りの「祭祀者の涙」、「祭祀者の血」および「祭祀者の髄」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_124059_Name = {
    Text = "深淵の祀りイベント通貨回収"
  },
  Mail_124059_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_124290_Desc = {
    Text = "守秘者：\n\nご存知の通り、喜びは私にとって、実は少し馴染みのない感情です。\n私はしばしば、常世は水面上の私には理解できない喧騒であり、私がその中に溶け込む前に、私の枯れがすでに訪れていると感じます。\nそれは時折私を憧れさせますが、もっと多くの場合、私を困惑させ、窒息させます。ただ、今日のような日には、父と母を悲しませないために、私は必死に忍耐しています…………解放の日が来るまで、海が私を受け入れるまで。\n私は、深い水だけが私の帰属先だと思っていました。しかし、守秘者さん、あなたとミサゴの皆さんがいるおかげで、常世に馴染まない私のような者でも、ある種のリアルな温もりを感じることができるようになりました。まるで睡蓮が浮かぶとき、太陽が彼女の葉や花びらにキスをするように。\n乱雑ですが、私はどんな理由があっても、これらの思いを紙に落とし、それをあなたに送る必要があると感じています。私の時折のわがままをお許しください。\n私はただ、あなたが早くに荒寂に埋もれた水の中で、どれほど貴重な浮上をもたらしてくれたかを知ってほしいだけです。\nあなたが永遠に楽しく、永遠に安らかでありますように。\n\nニムフィーア"
  },
  Mail_124290_Name = {Text = "上昇"},
  Mail_124290_Sender = {
    Text = "ニムフィーア"
  },
  Mail_124291_Desc = {
    Text = "守秘者：\n\n今朝、私の枕元に手紙が届きました。それは自分の誕生日パーティーへの招待状で、署名は「絵師」クラブでした。\n先月、私が暇だった時に、サンガーの提案を受け入れて「絵師」の新しい創作コンテストのモデルを務めることにしたことを思い出しました。それ以前に、私は何度もお断りしていました。モデル台に立ち、動かずに描かれる時間の中で、私は蹈海者の祭壇にいた日々を思い出しました。その時も、すべての人の視線を受けていましたが、その視線の中には恐怖と畏敬しかなく、感動や称賛、欣賞は一切ありませんでした。\n今夜、絵師クラブのロビーで開催される誕生日の軽食会では、その日、十数人の絵師が丹精込めて描いた手描き作品も展示されます。あなたの美的センスには自信がありませんが、多くの刺激を受けることは悪いことではないでしょう。神母が特別にあなたをゲストとして招待し、彼らが「私」をどのように解釈しているかを共に楽しんでください。\n\n「マーフィー」"
  },
  Mail_124291_Name = {
    Text = "画家…………"
  },
  Mail_124291_Sender = {
    Text = "「マーフィー」"
  },
  Mail_124292_Desc = {
    Text = "守秘者： \n\nシルヴィアが教えてくれたのは、親しい関係に自分のニーズを打ち明けることが、常に私を追いかけてくる恐怖を和らげるのに役立つということです。それが効果的かどうかはわかりませんが、今日がそのための良いタイミングであることは間違いありません。\n私の願いを叶えてくれますか？今日の実験室の配給を全部あなたにあげることができます。\nいいえ、コーヒー豆の一袋ではありません。\nあの恐ろしい黒が私のほとんどすべての親しい関係を奪い、影のように私を驚かせてきましたが、あなたはそれを克服しました。\nあなたのおかげで、私たちはミサゴで安全に暮らしています、少なくとも今のところは。\n不健康なカフェイン依存から脱却する時です、守秘者、今晩少し時間を取ってもらえますか？\nもしあなたが私のそばにいてくれたら、もしかしたら光源があまり十分でない場所で、少しでも小休憩を取る勇気を出せるかもしれません。\n\n安心して眠りにつく感覚を思い出したいウインクル"
  },
  Mail_124292_Name = {
    Text = "願い…………"
  },
  Mail_124292_Sender = {
    Text = "ウインクル"
  },
  Mail_124293_Desc = {
    Text = "守秘者{Male=先生, Female=小姐}：\n\n今朝、一つの夢が私を覚醒させた。\n私は夢の中のすべてを注意深く思い出した：温かい日差しの中で微風が吹き、薔薇とチューリップが大地を覆い尽くし、千羽の銀色のカモメと楽しそうな人々が一緒に歌っている…………私はとても長い間、このような幸せな光景に身を置いていなかった。私はおそらく子供の頃の庄園、コレットの花房、あるいは西岱のどこかの公園にいるのだと思う…………しかし、振り返ると、ミサゴの美しいゴシック様式の建物が見え、そしてあなたが見えた、守秘者{Male=先生, Female=小姐}。あなたは花と陽光の間に立ち、この詩の中で最も美しい言葉となった。\n私は西岱を深く愛している、守秘者{Male=先生, Female=小姐}。しかしその瞬間、私は突然気付いた、私はここにあるすべてに慣れ親しみ、魅了され始めていることに、この世には西岱よりも私の心を引きつける場所がついにできたのだ。\n誕生日は一つの時の終わりであり、また別の時の始まりでもある。新しい時代が始まるこの日、ミサゴの裏庭に咲く陽光と薔薇の間に、微風を共に聞き、私の心を捉える人がいるのだろうか？\n\nオルラ"
  },
  Mail_124293_Name = {
    Text = "花と詩の夢"
  },
  Mail_124293_Sender = {Text = "オルラ"},
  Mail_124294_Desc = {
    Text = "親愛なる守秘者：\n\n先日、私はあなたに特別な贈り物を送りたいとずっと考えていました。ジェンキンが新しい服を自分で作るのはどうかと提案してくれたので、このアイデアはとても良いと思いました。\nこれは私が繊維工場で働いているときに得意だったカットスタイルで、今見ても古くないといいのですが…………他のものは私の決定を支持してくれることがほとんどなく、上にある活発なストライプやチェックは、私が作った異なるものです。そしてこの歪んだかわいいネズミのデザインは、猫「24」が絶対に加えたいと言ったもので、ブラウンを表しているとのことです。猫の人格の私はこれが一番好きなものです——合っているかどうかわかりませんが、気に入ってくれるといいな。\n新しい年になっても、私は特に誕生日の願い事はありません。あなたはいつも優しく、毎年ちゃんとお祝いするように言ってくれます。でも、祝われることよりも、あなたのために自分の手で何かを縫うことの方が、私にはずっと安心感と喜びを感じさせてくれます。\nこの気持ちが詰まった新しい服を受け取ってください。\n\nメイソン"
  },
  Mail_124294_Name = {
    Text = "新しい服"
  },
  Mail_124295_Desc = {
    Text = "ちっ：\n\n信じられない、偉大なる迷宮の主である私が、こんな困難な試練の中でまた一年生き延びたなんて。\nよく聞け！これは全てお前とこの馬鹿な学院のせいだ！\nいくらお前たちが私に無意味な洗脳をしようとも、こういう雑事は本来専門の人間がやるべきだ。いいか、私は素晴らしいことを成し遂げたんだ、奴隷と呼んでいないんだから。\nあの頑固者たちはこれを…………なんて言ってたっけ、そう、進歩だ。\nちょっと待て、なんで私もこの論理に巻き込まれているんだ、あああ、うんざりだ！(ここには、手紙の主人が怒ってできた乱れた折り目がたくさんある。)\nもういい、私に「進歩」があるなら、お前も誠意を見せるべきだ。今年のこんな盛大な日には、前の二年のように私がリマインドするのを待っているわけにはいかないだろう。\n三十分与える、守秘者、贈り物を持って私に会いに来い。\nさもなくば、私の子供がお前の顔に這い上がることになるぞ。\n\nアグリッパ"
  },
  Mail_124295_Name = {Text = "進歩"},
  Mail_124295_Sender = {
    Text = "アグリッパ"
  },
  Mail_124296_Desc = {
    Text = "守秘者！\n\n私は見ました！なんと素晴らしい光景でしょう！これは夢ではないと確信しています！私はそこに立っていました、ミサゴ墓地の壮大な記念像のそばで、そこから果てしなく続く無名の墓石を眺めていました。それらが私に前所未有の啓示をもたらすと確信していましたが、思っていた以上のものをもたらしてくれました。それらは私の貧弱な想像力を敬意を持って嘲笑しているかのようです。\n私はあの調査員たちの幽霊を見ました、彼らは薄霧の美しい黄昏の中で一緒に立ち上がっていました。彼らの顔ははっきり見えませんでしたが、彼らの動きは見ました——優雅な舞踏のようであり、神秘的な儀式のようでもありました。彼らは黒い池に向かって、ミサゴとあなたの方向に敬意を表していました。現代のサロンの芸術家たちは個人を描くことに夢中になり、こうした壮大な光景をしばしば非難しますが、私は決してそうは思いません。食屍鬼の舞踏会を前にして私は大変喜び、そして今日、この光景に涙を流さざるを得ませんでした。\nこれは偶然ではないと思います。ちょうど今日、私の誕生日に、彼らは私に彼らの壮大な共舞を見せてくれました。彼らは何かを私に伝えたかったのだと思います。私は画筆以外何も持っていませんが、それで十分ではないでしょうか？\nこの絵の草稿は既に描き終えました、守秘者、ぜひ私のアトリエに見に来てください！名前を失った伝説の調査員たちが、あなたに伝えたい願いは、私のそのキャンバスの上にすべて描かれています！\n私はこの絵に安易に名前を付けませんでした、この資格はあなたにこそふさわしいと思います。\n追記：私は本当に死体を探しに行ったわけではありません、あなたに保証します！\n\nピックマン"
  },
  Mail_124296_Name = {
    Text = "調査員の宿願"
  },
  Mail_124296_Sender = {
    Text = "ピックマン"
  },
  Mail_124297_Desc = {
    Text = "こんにちは、守秘者：\n\nあなたは恐れているのですか、それとも——恐れつつ、私の誕生日に祝う名のもとに、何かを持ってくることを期待しているのでしょうか？\n虚飾と親密さ、突然の艶やかな夜、あるいは欺瞞に満ち、陶酔させるような夢の幻境？\nああ、すべてありません。たとえ私自身も、時には真剣で退屈な話をすることもあります。\nあなたは私がどのような存在かをよく知っているはず、享楽に耽り、たとえ建物が崩れようとも。\n愛と欲は、世の中で最も退屈な病を癒すことはできませんが、権力と混乱の鮮やかさを引き出すための薬引きとしては、これ以上に適したものはありません。\n残念ながら、この千年の時を経て、私は演劇の研究にあまりにも深入りしてしまったのか、常に何人かの庸人が心を剖き、私があなたの孤独な魂を見たと言います。\nふう。\nたとえ戯れを楽しむ私でも、時には少し気持ちが悪くなることがあります。\nそしてあなたは…………私と繋がるために何を求めているのですか、コントロールするため、束縛するため、力を借りるため？\nあなたが守るべきものが多ければ多いほど、より高い権力が必要となり、権力への渇望はより大きな野心を生むでしょう。それがいつ成熟し、いつお腹に吸い込まれるのか…………考えるだけで興味津々で、あなたのそばにもっと長く留まることを楽しみにしています。\nシー、答えを教えてくれなくてもいいです。\n毎年この日、あなたの夢を一晩奪い、あなたの野心が成長しているか、あなたの意図がズレていないかを味わい、考えることが、私が自分自身に贈る最高の誕生日プレゼントです。\nどうかお許しください。\n\n「千扇」"
  },
  Mail_124297_Name = {Text = "良い夜"},
  Mail_124298_Desc = {
    Text = "守秘者：\n\n訓練、戦闘、パトロール、私が軍に入隊したその瞬間から、集団の必要な事務で自分の全ての時間を埋めることに慣れていました。\nその後、アラン族を砂漠で移動させる中で、これらの事務はますます膨らみ、まるで法則のように私の脳裏に刻まれ、ミサゴに来ても、常に集団のスケジュールを個人的な事務よりも優先していました。\nしかし、他の人々、特にあなたとの関係の中で、私たちが覚醒体としても人間としても、自分自身だけの時間を持つ必要があることに気づきました。それは大切な人との時間を味わうためのものです。\nこの貴重な関係が、私たちの時間の存在を確固たるものにし、私たちの存在に本当に代えがたい意味を与えています。\n少々失礼かもしれませんが、私は今日のすべての集団の事務をキャンセルし、一日を空けました。\n数時間、いや、一時間、あるいは数分でも構いません。あなたが私に少しのプライベートな時間を分けてくれるなら、それは私にとってこの特別な日を過ごす意義となるでしょう。\n\nアルバ"
  },
  Mail_124298_Name = {
    Text = "プライベートタイム"
  },
  Mail_124298_Sender = {Text = "アルバ"},
  Mail_124299_Desc = {
    Text = "小さな者：\n\n一年という時間はあなたにとって長く感じるかもしれませんが、原質の海を渡る者にとっては、それは時間の無限の海の中で一瞬の海水の一握りに過ぎません。幸運なことに、この海水の中には印象的なクリスタルの水滴がいくつかあります。\n解憂小舗の割引日こそ、その中で最も大切にされるべきものです。それは金券をもたらすだけでなく、この日、必ず一人のお客様がこの小さなお店に来ることを私は知っているからです。\nすべての人と人とのつながりはビジネスであり、すべてのビジネスは人と人とのつながりです。すべてのお客様は特定の時間に彼らの小さなお店に入るでしょうし、すべての小さなお店は特定の時間に彼らのためのお客様を迎えます。長い時間の中で、私は無数の宝物を見てきましたが、最終的には、これらの幼稚な瞬間が最も貴重なコレクションになるのです——それらはこの長い時間の存在理由です。\nこの一年の中で、最も貴重な新しいコレクションは展示ケースの中で静かにその客人を待っています。\n早く来てください、小さな者。\n解憂小舗はすでに早く閉店しました。今日は、そのドアは一人のためだけに開いています。\n\nダフォダイル"
  },
  Mail_124299_Name = {
    Text = "新しい蒐集品"
  },
  Mail_124299_Sender = {
    Text = "ダフォダイル"
  },
  Mail_124300_Desc = {
    Text = "守秘者：\n\nあなたはまだ、私たちがドアの前にいた瞬間を覚えていますか？その日、私は真実の一筋の隙間を開き、宇宙のリアルをあなたに示しました。\n意外なことに、あなたが無数の世界を遥かに見つめる永遠を経験している間に、私は一瞬の中で理解できない感情が生まれました。\n私はその瞬間の感覚が何であったのか、なぜ真実を知る私が理解できないものを感じたのかをよく考えます。\n私は長い間考え、現実世界を基準とする計量体系で言えば、それは「永遠」と呼ばれるに足る時間です。\nこの相対的な宇宙にとっては少し長く感じるその時間の中で、私はこれがまだ定義されていない奇跡かもしれないと気づきました。\nこの特別な日に、私はあなたを私とリンクさせることを招待したいと思います。私の視線を通して、私が観測したことのない存在を観測してみましょう。今回私たちが観測するものは…………既定のすべてではなくなるでしょう。\n私たちは真実の外にある未来を一緒に探しに行きましょう。\n\nタヴィ"
  },
  Mail_124300_Name = {
    Text = "真理の外"
  },
  Mail_124300_Sender = {Text = "タヴィ"},
  Mail_124301_Desc = {
    Text = "守秘者：\n\n今年も例年と同様、私はすべての他の事を中断し、自分と静かに向き合い、故国に関する思い出を再度書き直し、刷新しようとしています。\nそれらは私からますます遠ざかり、たとえ私がこの人間の姿に慣れようと無理をしても、海に関連する知識や経験を繰り返し記述し、越えていくことは、この消えゆく世界の中で、忘却が記憶よりも遥かに容易であることを示しています。\n唯一の慰めは、今私たちリモリアから遠く離れた旅人たちが、ここに留まることができ、我が王の意志に従い、静かに追い、静かに待つことができることです。\n私はあなたがこれに対して犠牲にし、尽くしてくださったすべてを深く理解しています。私はどのように感謝の気持ちを表現すればよいのかわかりませんが、もし私がリモリアに戻ることができる前に、私が必要とされることがあれば、私のすべての光を捧げる覚悟です。\n\nあなたの真心を込めて、ファロス"
  },
  Mail_124301_Name = {Text = "灯台"},
  Mail_124301_Sender = {
    Text = "ファロス"
  },
  Mail_124302_Desc = {
    Text = "親愛なる守秘者：\n\nミサゴに参加したその日から、複雑な規則が私を束縛しています。会場で従者と散歩することは許されず、キャンパスの広場で学生の顔を踏みつけることも許されず、ホールで大人数の集会を開くことも許されません…………\nミサゴのあの厄介な道徳主義者たちが私を閉じ込めています。これはイサラウの女王が享受すべき生活ではありません。私は自分の得るべき全てを享受する権利があります。魅惑的な美酒、柔らかな背中、そして愛しい従者…………この私が自由に楽しむべき誕生日に、そんな考えが自然に湧き上がります。\n夜も更け、雑事への忍耐も尽きました。私はあなたに真夜中の任務を命じることも、自分で推測させることもしません。私はあなたに私のそばにいてほしいのです。\n今すぐ私の庄園に来て、ためらわずに不要な衣服や肩書きを脱ぎ捨ててください。\n今夜、そしてこれからの毎晩、あなたは私のものです。\n\nこれをあなたの最初の永遠の任務と考えても構いません。\n\nワンダ"
  },
  Mail_124302_Name = {Text = "ルール"},
  Mail_124302_Sender = {Text = "ワンダ"},
  Mail_124303_Desc = {
    Text = "守秘者：\n\nティンクトが私に教えてくれました。彼女は個人コンサートの収益を使って、誕生日後に星際旅行を計画していて、私を連れて行きたいと考えています。しかし…………もし私も同行することになれば、彼女は私の面倒を見なければならず、彼女の楽しみが私のせいで損なわれるのは望ましくありません。\n彼女は生命の光を愛し、この宇宙の無数の色彩と流れる星河に魅了されています。私を連れて行くと、彼女は自由に歌ったり、思う存分凝視したりできなくなるでしょう…………\nだから…………彼女を説得してもらえませんか？彼女が一人で旅行に行き、いろんな惑星でコンサートを開き、憧れの風景を抱きしめることができるように…………それとも、あなたが私の代わりにこの旅行に参加していただけますか？ティンクトも私もあなたにはとても感謝していて、その恩に報いたいと思っています…………もしあなたが望むなら…………\nただ、これは私の意向だとは彼女に伝えないでください。私は彼女の自由な旅路の中で、その足かせになりたくはありません。\n\nファイント"
  },
  Mail_124303_Name = {
    Text = "旅行について"
  },
  Mail_124303_Sender = {
    Text = "ファイント"
  },
  Mail_124304_Desc = {
    Text = "恩人：\n\n波リュクスと共にミサゴで過ごした日々は、こんなにも静かで、こんなにも明るく、まるで夢のようです…………\n波リュクスは今もなお、あの礼儀を守り、優雅で端正な言葉を口にしていますが、私は彼が少しずつ昔の彼に戻っているのをはっきりと感じています。「聖子」に属する、息を呑むような距離感が、柔らかな日常の中で静かに融解しています。このすべての優しい変化は、あなたのおかげです。\n私はしばしば、この恩をどう返そうかと考えます。波リュクスのように器用ではなく、あなたを驚かせるような贈り物を作ることはできません。飛ぶ楽しみも、あなたは私と何度も体験してきました。この特別な日があなたと喜びを分かち合うために、私は長い間静かに考えていました。\nもしかしたら…………私の羽毛を気に入っていただけるかもしれません。よく言われることですが、それは心を穏やかにする柔らかさを持っています。ですから、もしあなたが疲れを感じる日があれば、あるいはただ静かな場所が欲しい時は、いつでも私のところに来てください。私の翼は、いつでもあなたのために垂れ下がることを願っています。\n\nカストル"
  },
  Mail_124304_Name = {Text = "羽根"},
  Mail_124304_Sender = {
    Text = "カストル"
  },
  Mail_124305_Desc = {
    Text = "私の小さな囚人：\n\n最近ミサゴではあるロールプレイングゲームが流行しているらしいね、魔女や狼男とか…………ちょっとロマンチックじゃないな〜。もっと楽しいゲームを思いついた！\nあなたが囚人を演じて、私が看守を演じるの。私が小さなムチを振る時、大きなうめき声を聞かせてね〜。蝋燭があなたの体に流れ、熱い痛みと快楽をもたらす…………ああ、その光景を想像するだけで、もう甘い気持ちになってきたわ〜。\nあら、ここまで読んで、また眉をひそめているの？本当にお利口じゃないわね、今日は私の誕生日なのよ〜。愛しい小さな囚人、少しは私のわがままな願いを叶えてくれなくちゃ？\nどうしてもダメなら…………じゃあ、あなたが看守になって、私があなたの囚人になるのはどう？私はあなたを満足させるわ〜。\n\nパンディア"
  },
  Mail_124305_Name = {
    Text = "ロールプレイング"
  },
  Mail_124305_Sender = {
    Text = "パンディア"
  },
  Mail_124306_Desc = {
    Text = "守秘者：\n恩人、今日は私の誕生日です。この特別な日に、近況をお伝えしたいと思います。ゴリアテとロータン先生の指導の下、私は自分の血脈に宿る力に触れることができるようになってきたようです。それはもう眠っておらず、練習のたびに私の体の中で低く鳴り響き、奔流のように流れ出し、徐々に解放されつつあります。\n\n\n\n具体的にいつ最終的な変身を遂げ、より純粋な深海族となれるのかはわかりません。明日かもしれないし、来週かもしれないし、来月かもしれません…………しかし、この過程がどれほど長く、道のりにどれほどの試練があろうとも、あなたが私にかけてくれた励ましの言葉は、私はずっと……忘れずに覚えています。これからも努力し続けます。\n\nもう一つお詫びしなければならないことがあります。私はつい先ほどミサゴ郵便局から、現金を同封する場合は追加で2ドルの手数料が必要だと知らされました。\n昨年の分を補うために、貯金からもう一度支出します。それらは私にとって得がたいものでしたが、深海の血脈には約束を果たす義務があります。\n\nカエクス"
  },
  Mail_124306_Name = {
    Text = "手数料…………"
  },
  Mail_124306_Sender = {
    Text = "カエクス"
  },
  Mail_124307_Desc = {
    Text = "守秘者：\n\n聞いて、今夜はどうしても、私と一緒に「その店」に行くこと。\n偽装用の服はすでにあなたに送ってあるから、必ず、絶対に、他の人には私たちを見破られないように！\n「その店」の限定スイーツが販売開始されたから、あのどこから来たかわからない厄介者が必ず一群の人を買収したに違いない、彼らに私の動向を知られないようにしなければならない。\nあのやつは私が買えないように、レンディニエンのすべてのケーキ屋の限定品を予約したけど、まあ…………ふふ。\n私はすでに「その店」のシェフを買収して、彼に一番美味しい品をメニューから外してもらった。\nふふ、今日はあのやつに教えてあげる、いくつかのことは単純にお金で解決できるわけじゃないって。\nその時、私たちは静かに裏口から忍び込んで、三重に暗号化された鉄の箱を開ければ、その限定品の中の限定品を手に入れられる。\n報酬として、私は一切れ(取り消し)、半分のケーキをあなたに分けてあげる！\n今夜11時、私は部屋で待っているから、必ず、絶対に来て！わかった？！\n絶対に秘密にして、さもなくば、情報が漏れてあのやつに私たちの動向を知られたら、すべてが終わってしまう！\n\nマーフィー"
  },
  Mail_124307_Name = {
    Text = "ケーキ奪取大作戦"
  },
  Mail_124307_Sender = {
    Text = "マーフィー"
  },
  Mail_124308_Desc = {
    Text = "守秘者：\n\n残念ながらお知らせします。レンディニエン劇場はカーシアマスターのマジックショーを完全にキャンセルしました。その理由は、チケットの価格が高すぎること、最近目にした奇怪な出来事が多すぎてマジックへの興味が薄れていること、連続した数回の公演で観客が行方不明になり、未だに帰ってこないこと、警察が劇場のオーナーにカーシアマスターに公演を一時中止して捜査に協力するよう求めることがしばしばあることなどです。\n最近、ブラックプールの異変の影響を受け、私の公演には確かに時折小さな失敗がありましたが、これは些細なことです。しかし、二つ目の理由はカーシアマスターが絶対に容認できないことです！\nそのために私は思案を巡らせ、ついに完璧な新しい公演を考え出しました！死体の操り、死者の復生、次元の穿越、感情の感染、巨大な触手…………すべて問題外です！以前、あの忌々しい次元ハウンドの影響を受けて、時間の操縦はこの業界の禁忌でしたが、その悪犬が封印された今、カーシアマスターのマジック事業は新しい段階に再び登るでしょう！\n公演は今夜の予定で、完全無料です。守秘者には最前列の真ん中の席が予約されており、驚きのインタラクティブなセクションもお待ちしています！新時代の最も偉大なマジックショーで最初のインタラクティブな観客としての栄誉を楽しんでください！\nカーシアマスターの栄光を取り戻すために！\n\nカーシア"
  },
  Mail_124308_Name = {
    Text = "カーシア、魔法を再び偉大に！"
  },
  Mail_124308_Sender = {
    Text = "カーシア"
  },
  Mail_124309_Desc = {
    Text = "ご主人：\n\nシルヴィアお姉さんがさっき来て、今年の誕生日に彼女たちが私を観覧車に連れて行ってくれると言っていました。\nリリーは絵本で観覧車について読んだことがあり、とても大きな車輪で、上に乗るとゆっくりと空に回り、小鳥が横を飛び回るのが見えると、とても幸せに聞こえます。\nでもシルヴィアお姉さんは「実際には少し違いがある」と言っていました。リリーはそれがどういうことか分かりません。\n彼女はまた、観覧車に行く場所がとても高いので、監護人を連れて行くのが良いと言いました。\nリリーは監護人が何を意味するのか分からないけれど、リリーはご主人と一緒に雲の間を旅したいです。\nお昼ご飯の後、私はシルヴィアお姉さんと一緒に宿舎の外であなたを待っています。\n\nリリー"
  },
  Mail_124309_Name = {Text = "観覧車"},
  Mail_124309_Sender = {Text = "リリー"},
  Mail_124310_Desc = {
    Text = "守秘者(今回はついに正しく書けた！すごいでしょ！)：\n\nまたこれらの恥ずかしいことを書く時間が来た。もう慣れたよ。今、私とブラウンは今日何を君にご馳走しようか頭を悩ませているんだ！\n東地区の路地にある屋台の食べ物はもちろん美味しいけど、今日は君とブラウンを良いものに連れて行くつもりだ——つまり君たち西区の人が好きなあれだ。\n例えば、ソースや香辛料で覆われたプライベート料理、小さい量で大きな皿、しかも信じられないくらい高い、まるで強盗みたいだ。そんなことを考えると、財布が風を通し始めるのがわかる、きっとお金が去るときに残した傷だ。\nでも君は姉さんとブラウンを除いて、私にとって最も重要で大好きな人だから、東区の人は自分の人に対してけちくさくないから、今日はすべての支出を私とブラウンが負担するよ。\n私たちを侮ってはいけない、私たちは牛乳を配達したり、新聞を配達したり、伝言を持ったり、他の仕事でかなりのお金を稼いでいるから、安心してね！\n\n君の良き仲間ジェンキンとブラウン"
  },
  Mail_124310_Name = {
    Text = "今日はブラウンとお会計！"
  },
  Mail_124310_Sender = {
    Text = "ジェンキン"
  },
  Mail_124311_Desc = {
    Text = "親愛なる守秘者：\n\nあなたはもうシルヴィアがミサゴの地下カジノを完全に壊滅させた偉業を聞いたでしょう？でも今日は私の誕生日です。肾上腺素が上がるような素晴らしいイベントがなければ、年に一度の素晴らしい日を無駄にすることになるのでは？\n何度も考えた結果、あなたを私の良き助手として特別に招待し、西岱からこの地に流れ着き、大博物館の宝物を盗んだ暗夜の怪盗を捕まえることにしました。\n校外の「アポロバー」でちょっと飲んでいるとき、彼らが高価な宝石をかすめ取った自慢話をしているのを偶然耳にしました。バーテンダーは気にしていなかったようですが、私はそれを聞き取ったのです。エメラルド、サファイア、ダイヤモンドの冠、そして盗まれた物と完全に一致していました。見つからないように、彼らにしっかり印をつけておきましたので、彼らが拠点に戻ったときに一網打尽にするつもりです。\n今晩7時、校門前のミサゴ専用列車の停車地点で、必ず会いましょう。\n\nライカー"
  },
  Mail_124311_Name = {
    Text = "狩猟計画"
  },
  Mail_124311_Sender = {
    Text = "ライカー"
  },
  Mail_124312_Desc = {
    Text = "守秘者：\n\nミサゴの時は、他の場所よりも軽やかに流れているようです。数回の拍手、数回の幕引きで、1年がまた過ぎ去りました。\nこの1年で、私はいくつかの新しい習慣を持つようになりました。以前、私が舞台に立つとき、どんなに混雑した劇場でも、私の目には誰もいないかのように映っていました。広々とした舞台で、空っぽの劇場に向かって踊り、世界にはただ一足のバレエシューズの音だけが響いていました。しかし今、幕が上がるたびに、あなたの姿が見えます。千の席が空っぽで、ただあなた一人が私を見つめています。あなたの視線の中で、私の舞は再び意味を持ちました。\n1年が過ぎ、あなたの舞は依然として不器用ですが、舞台の上の凡庸な舞の一歩を軽々と超える、あなたの下でのその躍動する視線は、私を清めてくれます。それらの視線は小川のように流れ、私の徐々に平凡になっていく舞を一つ一つ洗い流します。この舞者と観客の共演の中で、私はずっと追い求めていた殿堂に近づいています。私はついに理解しました。舞にとって、観客と舞者は同じくらい重要なのです。\n数ヶ月間、私は一つの舞のために準備をしてきました。それはあなたの視線に育まれ、あなたのシルエットの中で生まれました。今、それは準備が整いました。\n私は、それが今夜、あなたが最初の証見者となることを期待していると思います。\n\nリッツ"
  },
  Mail_124312_Name = {
    Text = "ダンサーと観客"
  },
  Mail_124312_Sender = {Text = "リッツ"},
  Mail_124313_Desc = {
    Text = "守秘者：\n\nこの地の受け入れのおかげで、私はこの一年間、王と多くの話を交わしました。神国の降臨はまだ遠いですが、リモリアの時は、ミサゴで続いているようです。\nあなたと王はかつて、信仰が私の人生のすべてであってはならないと教えてくれました。私は頑なでしたが、最近の経験から心境が少し変わったようです。あまりにも頻繁な祈りは、主にとって煩わしいかもしれません。心からの奉仕の他に、主は信者が自分自身の浅薄な生活を持つことを望んでいるのかもしれません。\nこの点に気づいた後、私は少しの変化を試みることにしました。私はレンディニエンの有名なパティシエを訪ね、彼らに焼き菓子の作り方を教えてもらいました。彼らにはいくつかの秘密があり、主の祝福によって彼らは口を開いてくれました。昨日、私は初めていくつかの試みを行い、数人の信者が味がとても良いと言ってくれましたが、彼らの味覚は忠誠心と同じく疑わしいものです。\n今日は私の庭に来て味わっていただきたいと思います。あなたの味覚を信じ、あなたの率直さも信じています。もし美味しくなければ、遠慮なく言ってください。私は真剣に改善に努めます。\n感謝いたします。\n\nミリアム"
  },
  Mail_124313_Name = {
    Text = "もう一つの専門"
  },
  Mail_124313_Sender = {
    Text = "ミリアム"
  },
  Mail_124314_Desc = {
    Text = "守秘者様：\n\n生命と死の意味について、もう聞き飽きているでしょう？ネクロポリスの亡者たちの華やかな記憶の中で、私が学んだ最も重要なことは、食事の意味を探求することよりも、目の前のテーブルにある食べ物そのものが重要であるということです。\n人類の古代において、私たちの先祖はすでに食事のすべての内涵を探求していました——情熱、欲望、享受。生きるために食べるのではなく、食べるために生きるのです。残念なことに、その原始的で純真な欲望は長い時間の中で徐々に忘れ去られ、この集団はますます複雑になってしまいました。\nしたがって、私は今日の晩餐のテーマを「純粋」と名付けました。この儀式的な日には、すべての複雑な事柄が私たちから離れていきます。このテーブルの上には、純粋で原始的な情熱と欲望だけがあり、鑑賞者と食べ物だけがあり、あなたと私だけがいます。\n私の最も誠実な招待を受け取ってください。あなたは私を拒否することはないでしょう？\n\nドレセイン"
  },
  Mail_124314_Name = {
    Text = "純粋な晩餐"
  },
  Mail_124314_Sender = {
    Text = "ドレセイン"
  },
  Mail_124315_Desc = {
    Text = "私の最愛の守秘者様：\n\n私の心はまるで成長しているかのようです…………これが覚醒体にとって奇妙に聞こえることは承知していますが、以前とは違います。どう表現すればよいのでしょうか？\n優しい人々が私に対してどれほど温かく、慈しみをもって接してくれようとも、兄が去った後、私の胸は常に空虚です。太陽の下を歩けば歩くほど、その温もりに引っ掻かれます。むしろ暗く湿った場所の方が安心感を与えてくれるようで、まるで冷たい場所に留まっていれば、兄の厳しくて痛みを伴う愛情が決して離れないかのようです。\nしかし今、あなたとより親密になった年月の中で、あなたに会うたび、あなたが与えてくれる痛みが私の肉体に降り注ぎ、骨に伝わるたびに——ああ、私の胸の中の幸福が日々増していきます。あなたが容赦なく私を叩き、侮辱し、蹂躙してくれる限り、この世界には私が本当に居場所を持てるところがあると知っています。\nこの幸福は来年まで続きますか、再来年まで？もし誕生日の願いがすべて叶うのなら、私の唯一の願いは、あなたにずっと軽蔑の目で見つめられ、痛みを…………もっともっとの痛みを受けることです。あなたが手を挙げるとき、私が最初に感じるのは、その馴染みのある、残酷で、幸福な香りです。\n\nあなたに叱られることを非常に望んでいるレーア"
  },
  Mail_124315_Name = {Text = "私の心"},
  Mail_124315_Sender = {Text = "レーア"},
  Mail_124316_Desc = {
    Text = "守秘者\n\n最近の練習状況が気になるけれど、今日はあなたに音楽の訓練を促すために来たわけではありません。\n今朝、いつも通り音楽室に向かいましたが、三十五分遅れてしまいました。朝の七時に音楽の訓練をするという習慣は数十年続けてきましたが、今日はそれを簡単に破ってしまいました。理由は、学校の廊下を通り過ぎるときに、ロビンの鳴き声が聞こえたからです。\n長年の習慣が破られるのは受け入れるのが容易ではなく、私にとって特にそうです。奇妙なことに、私は想像していたほど自分に失望したり怒ったりすることはありませんでした。最初は少し慌てましたが、その後、頭の中に響いていた旋律が心地よいことを認めざるを得ませんでした。\nレンディニエンはいつもロビンの鳴き声の中で目覚めます。この声は毎日聞いていますが、奇妙なことに、こんなに長い間、初めてそれに注意を向けました。廊下で静かにそれらの歌声を聞いていると、三十五分の間に、この宇宙の至高の旋律が彼らの小さな声帯の中に隠れているように感じました。\nもしかしたら、ここでの生活が人を怠惰にし、ここでの雰囲気が人を柔らかくしているのかもしれません。いずれにせよ、これはあなたに関係していると思います。\n私はこの変化を十分で快く受け入れることができました。生命は音楽のように古代からのリズムと変化を持ち、誕生の日、これらの変化が起こる運命的な節目があるのかもしれません。私もあなたに感謝したいです。私が無視していたものを静かに聴く機会を与えてくれたことに。喜び、そうです。これが私が新しい楽章に足を踏み入れる始まりになると思います。\nそのため、今日の夕暮れに校外の密林に一緒に行くことを招待したいです。夕暮れの自然の音は朝とは異なりますが、私たちの音楽の生命の中で新しい啓示となるでしょう。\n\nハムリン"
  },
  Mail_124316_Name = {
    Text = "自然の音"
  },
  Mail_124316_Sender = {
    Text = "ハムリン"
  },
  Mail_124317_Desc = {
    Text = "貴人：\n\n私はちょうどフィーントがあなたに送った誕生日メールを見たところです…………やっぱり、姉はいつも他の人のことを考えているのですね。姉妹の間に借りはないし、私は彼女を負担だと思ったことはありません。彼女の保護がなければ、今のように巡回コンサートを開く機会もなかったでしょう。\n尊敬する貴人、あなたは私にとって最も重要な聴衆です。ですので、今回は、あなたのために密かに船のチケットを用意しました——心からあなたをこの星間の旅にお招きします。あなたが一緒にいれば、姉の心の負担もずいぶん軽くなると思います。\nまた、旅の途中であなたのプライベートな時間を邪魔することは決してありません。私と姉は、あなたがこの旅を存分に楽しみ、すべての星雲や未知の出会いを自由に感じていただけることを願っています。\n\nティンクト"
  },
  Mail_124317_Name = {
    Text = "旅行のお誘い"
  },
  Mail_124317_Sender = {
    Text = "ティンクト"
  },
  Mail_124318_Desc = {
    Text = "守秘者：\n\n誕生日が近づいてきましたが、思いはいつも無意識のうちにさいだいに戻ってしまいます。特に、あのアート展での彫刻が懐かしいです。それらの静かな姿は、何度も私のインスピレーションの扉を叩きました。\nスタジオで一日中彫刻と共に過ごす中で、アートとの交流が不足し、長い間、退屈に感じていました。昨年の今頃、自分の誕生日を祝うために、無数の彫刻ケーキを作りました。最初の興味はすぐに静まってしまいました。\n今は動きが不便で、さいだいに戻ることは贅沢な夢になっています。もしあなたが調査に行く予定があるのなら、アート展の新作に注意を払っていただけませんか？あなたの目を通して、再び多様で包容力のあるアートの美に触れたいのです。\nお礼として、私はあなたのためにもう一つ彫刻を作るつもりです。その名も『守秘者のさいだい』、どうですか？\n\nサンガー"
  },
  Mail_124318_Name = {
    Text = "シダの思い出"
  },
  Mail_124318_Sender = {
    Text = "サンガー"
  },
  Mail_124770_Desc = {
    Text = "守秘者：\n\n毎年実験室への権限が取り消されるため、この日はあまり楽しくない形で特別なものになってしまいました。効率のない雑事に時間を無駄にしないために、私はアーカイブに行きました。\nそこで、二つのものを見つけました。一つは作業ノートで、無価値な空白で埋め尽くされています。\nもう一つも作業ノートで、知識の海を過小評価していたことに気づかされました。そこには推論過程と結論が書かれていて、存在しないことよりも価値が低いものがこの世に存在することを教えてくれました。\nそして、この二冊の作業ノートには、同じ名前が書かれていました。私たちの偉大なミサゴ守秘者%player%。\nエリカは、あなたが私に何を誕生日プレゼントとして送るべきか知りたいと言っていました。\nあなたは私に一つの答えを送ることができます。\n私も知りたいのは、どの答えの事実が私をより驚かせるのかです。それは、極限まで発揮された怠惰といい加減さなのか、それともあなたが一年間真剣に学び、最後に無駄な絶望の中でこれらの学術的ゴミを残したのかです。\nもし前者であれば、十分な理由があり、授業で教えられた知識をしっかりと理解したことを証明できれば、私はあなたのために学院に課題免除の申請を提出することができます。もちろん、これはあなたを完全に怠惰にさせる可能性のある緩みを支持するわけではありませんが、私の試験を通過できる限り、私は古臭い人間ではなく、学生に特権を与えることを気にしません。\nもし後者であれば、あなたの第一の保護者として、信じてください。どんなに形を変えにくい材料であっても、私が習得している技術の中で、あなたの貧弱な知識を向上させ、無知から抜け出すための努力の苦痛から救う方法を見つけることができます。\n今日の午後4時、私はアーカイブにいて、あなたの授業の知識の習得を直接チェックします。遅れないでください。\n\nドール"
  },
  Mail_124770_Name = {Text = "特権"},
  Mail_124770_Sender = {Text = "ドール"},
  Mail_124771_Desc = {
    Text = "ミサゴの子犬：\n\n今年もあなたは同じループの中で、トラブルを起こし、世界を救い、友達を作り、新しい知識を学び、世界にすべてが普段通りであるという偽りの印象を与え続けています。\n実際、あなたの脳を身体から摘み取っても、リュミニスが一つの次元から別の次元に移動しても、あなたの滑稽で笑える奔走や忙しさには影響しないのです。\n本当に忙しくて騒がしいですね、親愛なる子犬。\nあなたはその事実を信じていません。彼らの苦しみを続けさせ、滅亡のプロセスをより引き延ばそうとしていますが、あなたの目的は何ですか？あなたは本当にバカを演じているのか、それとも人類は本当にそんなにバカになれるのでしょうか？私が確かにあなたの身体の脳葉皮層を剖開したとしても、これらは依然として私にとっての謎です。\nおめでとう、あなたは本当に私に少し揺らぎをもたらしました。あなたを観察することがこれほどの楽しみをもたらすのなら、すべては本当に無意味とは言えないのではないでしょうか？\nあなたが得意とする無意味なことのように、無意味に祈り続けてください。祈りの対象は誰でも構いません。\nあなたが私をずっと束縛し続けることを祈ります、子犬よ。そうすれば、私もあなたも、無意味な世界の中で、少しの楽しみを見つけることができるでしょう。\n\n「ドル」"
  },
  Mail_124771_Name = {
    Text = "祈りなさい"
  },
  Mail_124771_Sender = {
    Text = "溶壊・ドール"
  },
  Mail_124772_Desc = {
    Text = "パートナー：\n\n毎年の誕生日に手紙を書くことは、いつの間にか習慣になったようです。\n最初にあなたに手紙を書いた誕生日のことを今でも覚えています。それは父が初めて私に自分で誕生日の計画を立てることを許可してくれた日で、私はあなたを外出に招待しました。それ以降、私たちは一緒にたくさんの「初めて」を経験しました。\nその後、多くのことが変わりましたが、よく考えてみると、あまり変わっていないようにも思えます。私たちは今も自分たちが信じる道を進み続けていて、互いに寄り添い合っています。そして、あなたは私にとって最も重要なパートナーであり続けています。\nだからこそ、父が先ほどケーキを持ってきて、今夜彼が私のために開く宴に出席するかどうかを尋ねてきましたが、私は今夜別の予定があります。\nレンディニエンが新しい映画を上映しました。異常に人気がありますが、学院と協会はすでに確認済みで、その中には何の霊的反応もありません。\nこれは、それが本当に素晴らしい「普通」の作品であることを示しています。\nたまたまチケットが2枚ありますが、私は特例を作ってソレール夫人に頼むことはありませんでした。なぜなら、そのチケットは本当に手に入りにくいからです。\nさて、パートナー、この時間を私にくれませんか？もしかしたら、私たちは日々対処している異常な状況から一時的に離れ、互いに「普通」の夜を過ごすことができるかもしれません。\nその後の毎日、私たちが目を覚ますとき、世界で何が起こっても、私はあなたと一緒に向き合います。\n\nラモンナ"
  },
  Mail_124772_Sender = {
    Text = "ラモンナ"
  },
  Mail_124773_Desc = {
    Text = "守秘者：\n\n私とあの私との特別なつながり、そしてあなたとのリンクのおかげで、常にあなたのそばにいるわけではないが、私はあなたの過去一年の動向を少しは知っています。\nあなたは別の世界で活動しており、そこに「希望」という名の変化をもたらしているようです。日々、黒い池を見上げながらも、その光のようなエネルギーは私をも温かく包んでいます。\n私は以前のスケジュールを取り戻し始めましたが、以前とは違い、今は無駄に苦しむ心で、その運命的な寂滅に向き合っているわけではありません。あなたは私に新しいことを教えてくれました。運命の終点の前に、すべての存在が継続のために全力を尽くす過程こそが、文明、魂、意志が意味を持つ理由なのです。\n私のいる世界にとって、この時間がどれほど短いものであっても、私は挑戦し続けます。たとえそれが、あの懐かしい顔を再び見たり、少し話したりするためだけであっても、その挑戦は無意味ではありません。\nあなたが止まるまで、私はこの道を歩き続けます。どうか私がそれをあなたと並んで歩く方法の一つだと勝手に考えることを許してください。そうすれば、あなたが進み続ける道の途中で、いつか私が全力であなたと同じことをしていることを思い出してくれるかもしれません。\n\n「ラモナ」"
  },
  Mail_124773_Sender = {
    Text = "「ラモンナ」"
  },
  Mail_124774_Desc = {
    Text = "ターゲットを殺すのは簡単だが、その後始末は面倒なことだ。\n本来、今年も昨年の習慣に従って、もう一人を殺すつもりだった。\nしかし、あなたが私が贈った前回の贈り物をずっと使っていないことに気づいた。よく考えた結果、これが理由かどうかは分からないが、自分の不手際を発見した。\nあなたは安心していい。過去の雇い主に対しては、敵を殺すサービスだけを提供してきたが、様々な面倒を避けるために、痕跡を消すことについても私は経験が豊富だ。たとえあなたが殺したい相手が面倒な規則や秩序の保護下にあっても、何の心理的負担も感じる必要はない。すべてをうまく処理する。\n私は、誰もあなたを追跡できないことを保証する。\n人選が決まったら、名前を教えてくれ。私がどこにいても、すぐに駆けつけてあなたのために解決する。\n祝日を楽しんで、私が生まれたこの日も楽しんでくれることを願っている、守秘者。\n\n\nヘロット"
  },
  Mail_124774_Name = {
    Text = "頻繁に人を殺す人は皆知っている\n…………"
  },
  Mail_124774_Sender = {
    Text = "ヘロット"
  },
  Mail_124775_Desc = {
    Text = "わかった、明らかに君たちはこの行動をやめる準備ができていない。私の知る限り、あれも「贈り物」の習慣に慣れてしまった。\nだが、いつの日かその善意を後悔することになるだろう、信じてほしい。\n今考えると、それは私が一番後悔することかもしれない。くそ、私が人を殺すことを後悔するなんて思ってもみなかった。\n誰よりも私が、謝罪の無価値さを理解している。しかし、その日が来るまで、私は何かを補うために全力を尽くすつもりだ。ただそれがしたいから。\n君たちが将来そのことを恨む時、何の心理的負担も感じる必要はない。\n私は君たちの怒りを全て受け入れるつもりだ。\n\nH"
  },
  Mail_124775_Name = {
    Text = "あなたは後悔することになる"
  },
  Mail_124775_Sender = {
    Text = "血ノ鎖・ヘロット"
  },
  Mail_124776_Desc = {
    Text = "守秘者：\n\nまたこの誕生の日がやってきました。本来なら生命を祝う日ですから、毎年この日が来るたびに不思議な感覚が生まれます。\n私の誕生は死を追い求めるためのものであるかのようです。死というテーマから離れた瞬間、生命…………あるいは意識が依然として続いていることは、私にとって一体何を意味するのでしょうか？\n生前、苦痛と罪悪感の引き裂きが私の生命と切り離すことのできないほどに絡み合っていて、まるで死が訪れるまで、生命は初めて本当に私のものになるかのようでした。\n昨年、今年、そしておそらく今後の毎年。私はほぼ無限に近い長い時間を体験することができました。毎日が前の日と似ているようで、また前の日とは異なっている。生命がもはや苦痛や目的に縛られていないとき、その終点はどのようなものになるのでしょうか？あるいは、いわゆる終点は再び訪れるのでしょうか？\nこの命題はあまりにも巨大で、少し理解できない部分があります。\nしかし、これらの奇妙な思考の感情を記録したいという気持ちは非常にリアルで、答えは明らかであるように思えます。\n少なくとも私にとっては、これらの切実で貴重な瞬間です。私の思考がどれほど混沌としていても、どのように根を見つけるのが難しくても、私は明確に知っています。それらがどこへ漂い、どこに受け入れられるのか、そして私もまたそれらをあなたに伝えたくてたまらないのです。\nもしかしたら来年の今日、私はもっと自己の意味を見つけられるかもしれませんが、今はこの小さな、あなたと私だけが知っている依存を自己中心的に保留しておきたいと思います。\nそうです、守秘者、あなたとミサゴの皆さんは、私の心の中で誰にも知られていない根です。\nありがとうございます、変わらず、あなたが永遠に楽しく、永遠に安らかでありますように。\n\nニムフィーア"
  },
  Mail_124776_Sender = {
    Text = "ニムフィーア"
  },
  Mail_124777_Desc = {
    Text = "余は最近、新しいリラックス方法「神国の昼寝」を発明しました。\n一般的な短時間で慌ただしい昼寝とは異なり、神国の昼寝を行う際には、余は長時間座った青石の玉座から離れ、腕を使って音を遮断する球体を構築し、特製の海水でその空間を満たします。\nこの海水は、余が望む香りを発し、余が見たい景色に変わり、さらに各方向から適切な強度で余の身体を支えてくれます。\nそのため、余がどのような動きをしても、まるで最高級の羽毛布団の中に包まれているかのような温かさを体験できます。\nその時、余は心地よい香りの中で心をリラックスさせ、世間から隔絶された静けさを楽しみ、余が最も好きな枕に寄りかかって安らかに眠ることができます。\n余の最もお気に入りの臣下として、余は生誕の日があなたとこのゆったりとしたひとときを共有するのに最適だと考えています。もし興味があれば、前に話した秘密の場所に来てください。あなたの安全を心配する必要はありません、余はあなたのために特別な空間を用意し、余の夢の影響を受けないようにします。\n最も快適な枕を持ってくるのを忘れないでください。\n\nトゥルー"
  },
  Mail_124777_Name = {Text = "昼休み"},
  Mail_124777_Sender = {
    Text = "トゥルー"
  },
  Mail_124778_Desc = {
    Text = "私の明かり：\n\n私はカストールと共にミサゴの生活に適応しており、教会の血なまぐさい駆け引きから逃れた後、過去の自分を取り戻していると感じています。\n今は日常の言動の中に「聖子」の影が避けられないものの、もうすぐその傲慢さと疎外感を完全に洗い流し、神に対する謙虚さと道を貫く決意だけを残せると信じています。\n少し前に、予想外の贈り物を受け取りました。それは美しく装丁された本で、故郷に帰って自分のこども時代を取り戻す人々の物語について書かれています。それと一緒に送られてきたのは、「早く最初の自分を取り戻せますように」と書かれたメモでした。\nこの言葉が目に飛び込んできた瞬間、過去の思い出が心に浮かび上がります——ミサゴの皆の心遣い、明かりであるあなたの導き、そして兄の…………温かい抱擁。\nですので、今年の誕生日には、ミサゴの皆を招待して、私と兄の誕生日パーティーに参加してもらいたいと思います。皆の助けがなければ、私たちが最初の時を取り戻す可能性はありません。\n私は最近の貯金を使って、レストランを貸し切りました。そこではシェフが世界各地の料理に精通しており、誰もが自分にとって最も馴染みのある味を楽しめると思います。\n\nポリュクス"
  },
  Mail_124778_Name = {
    Text = "子供時代を取り戻す"
  },
  Mail_124778_Sender = {
    Text = "ポリュクス"
  },
  Mail_124779_Desc = {
    Text = "私は郊外の地下闘技場からの招待を受け入れ、命を懸けた試合をすることに決めた。\nマス・クラブでの日々は良いものだったが、あまりにも平凡で、毎日が魚を殺すか、魚を殺すかの繰り返しだった。確かに私はトラウトを完全に征服したが、トラウトを征服したからといって、征服したことにはならない！\n私の体内の戦士の血が沸き立ち、血脈を刺激する戦いを求めていた。そして今、チャンスが来た。\n私と連絡を取ってきたそのハゲは、3匹のナタイ・アナコンダ、2頭の鬼面熊、4匹のセリナソン・ワニ、そして名前を思い出せない奇妙な生物たくさんを用意してくれた。これで一晩中、思う存分戦うことができる。\n私は特に今日の試合を設定してもらった。誕生日の日に、あなたに見せるために——私、ユウハシュ、最後のローマ戦士が、世の中のすべての猛獣を征服する壮観を！\n今日、場に撒かれるのはもはやトラウトの廃棄物ではなく、鮮血と異獣猛禽の死体だ！\n\nユウハシュ"
  },
  Mail_124779_Name = {
    Text = "猛獣を征服する"
  },
  Mail_124779_Sender = {
    Text = "ユウハシュ"
  },
  Mail_124780_Desc = {
    Text = "「銀の鍵の騎士」：\n\n守秘者！さっき「ファントム号」を改装しているとき、モスクが突然大きな袋に詰めた部品を持ってきてくれたんだ。誕生日プレゼントだと言って、今日が私の誕生日だって思い出した！\nだから急いで君に手紙を書いたんだけど、ほんとに今日は忘れてしまった。確か…………何枚のメモを書いたんだっけ？\nでもそんなことはどうでもいい。重要なのは、以前言った誕生日の日に何をするかを思い出したことだ——「ファントム号」に乗って、君とモスクを連れて、倫蒂尼恩を一周百回するんだ！\nモスクは機械のことを全く理解していないけれど、彼女の袋には部品がたくさん入っていて、必要な部品をすべて揃えることができる。今改装した「ファントム号」は、すでにスーパー強化型プロトタイプ(仮)になった！\nこの冒険には名前を付けたよ、「ナウティラと守秘者とモスクと「ファントム」の冒険」。どう？直接的で覚えやすいでしょ？これでこの冒険を忘れないことができる！\nへへ、ほんとに楽しみだよ、守秘者、もう少し待っててね。「ファントム騎士」ナウティラと「渦巻き騎士」モスクがすぐに到着するから！\n「ファントム」冒険団、出撃！\n\n全力で突っ走っているナウティラ"
  },
  Mail_124780_Name = {
    Text = "「幻影」出撃！"
  },
  Mail_124780_Sender = {
    Text = "ナウティラ"
  },
  Mail_124793_Desc = {
    Text = "尊敬なる偉大な<Del:可愛>守秘者{Male=先生, Female=小姐}：\n\nええと、久しぶりの連絡ですね。私たちの親愛なる守秘者{Male=先生, Female=小姐}は私のことを思い出してくれましたか？〜\n今やあなたはミサゴの有名人ですよ、すべての学生があなたの勇敢な功績を学んでいて、あなたに少しでも関わるものは闇市で高値で売れるんです！\nまあ、当然のことですね。結局、あなたは「生きた伝説」、ミサゴ唯一の守秘者ですから。\nこの一年、ミサゴではたくさんの面白いことがありました——オレッタがいくつかのジンジャーブレッドと友達になり、ドール教授は脳の容器を変えるために17の実験室を爆破しました。カストルはアグリッパに騙されて彼女の試験を手伝った結果、それは常識の授業で、最終成績は彼女自身の試験よりも悪かったんです！\nあ、そうだ、あの憎らしい小ネズミが、私の貴重なフィルムを盗んでしまったんです。あれは私がやっと撮った「24」さんの猫の姿なんですよ！\nそれ以外にもたくさんあります。私はそれらを整理して、校報の新年特別号としてあなたに送りました。\n何ですって？どうやってあなたに連絡を取ったか気になりますか？へへ、これは秘密ですよ。たくさんの独占機密を使って、ある手ごわそうな婦人と交換したなんて言いませんから！\n新しい一年も一緒に頑張りましょう。新年おめでとう、%player%！\n\nハンナ・ピスリ"
  },
  Mail_124793_Name = {
    Text = "新年特別号"
  },
  Mail_124793_Sender = {
    Text = "ハンナ・ピスリ"
  },
  Mail_124794_Desc = {
    Text = "蒼白の使者：\n\n銀霜が近づいています。ここであなたに心からの祝福を表現させてください。\n\n前回、リリアン貧民院に子供たちを訪ねたとき、何人かの子供がこっそり「冬渡の使者は本当に存在するの？」と私に聞いてきました。\n私はなぜその子供たちがそんな考えを持つのか気になりました。もし私の記憶が正しければ、昨年はすべての子供が「冬渡の使者」からの贈り物を受け取ったはずです。\n結果、子供たちは私にこう言いました——「私はそのかっこいい男がダイアナ院長に贈り物を渡すのを見たけど、彼は冬渡の使者には全然見えなかった！」。\nおそらく、勲爵閣下が貧民院に贈り物をする際、子供たちに見つかってしまったからこそ、後にこのような小さな疑問が生まれたのでしょう。\n\nしたがって、今年の銀霜の夜、私は非常に伝統的な冬渡の使者の衣装を二着用意しました。蒼白の使者、あなたに私と一緒に冬渡の使者を演じてもらい、子供たちに贈り物を届けてほしいのです。\nきっと、子供たちの中には夜中にこっそり目を開け、私たちの赤い衣装と赤い帽子の姿を記録し、冬渡の祭りで嬉しそうにみんなに告げる子がいるでしょう——「私は冬渡の使者を見た！」と。\n同時に、あなたのために特別な贈り物も用意しました。気に入ってくれるといいのですが。\n冬渡の祭り、おめでとうございます。\n\nサルバドル"
  },
  Mail_124794_Name = {
    Text = "冬渡の使者"
  },
  Mail_124794_Sender = {
    Text = "サルバドル"
  },
  Mail_124991_Desc = {
    Text = "敬愛なる守秘者：\n「多重治療・復刻」復刻イベントは終了しました。残りのイベント通貨「記憶パズル」をそれぞれ「薔薇金券×40」の比率で回収しましたので、ご確認ください。"
  },
  Mail_124991_Name = {
    Text = "記憶パズル回収"
  },
  Mail_124991_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_125448_Desc = {
    Text = "敬愛なる守秘者：\n「海城の旧聞」イベントは終了しました。残りの「梨膏糖」をそれぞれ「薔薇金券」× 40 と交換しますので、守秘者の方はお忘れなくご確認ください。"
  },
  Mail_125448_Name = {
    Text = "梨膏糖回収"
  },
  Mail_125448_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_126321_Desc = {
    Text = "守秘者様へ：\n「織る者、自ら縛る」イベントが終了いたしました。守秘者様に残っている「ベルベット席チケット半券」を1枚につき「薔薇金券」× 40 の比率で変換いたしましたので、ご確認ください。"
  },
  Mail_126321_Name = {
    Text = "ベルベット席チケット半券回収"
  },
  Mail_126321_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_126934_Desc = {
    Text = "守秘者：\n\nまたこの特別な日がやって来ました。ふふ、心配しないで。今年はあなたに心理的な暗示をかけるつもりはありません。私はただ、私の最も特別な患者を、どこかに心を癒しに行くよう招待したいだけです。\nそこには豊かな森、清らかな川があり、自然の息吹に満ちていて、鉄の森の疲れを忘れさせてくれるでしょう。柔らかなカーペット、温かい暖炉、明るい照明もあり、都市の速いペースのストレスを和らげてくれるのです。\n私たちはそこで散歩したり、本を読んだり、話をしたりできます。あなたが何を話したいのか、私は喜んで耳を傾けます。\nああ、その光景を想像するだけで、心が高鳴ります…………\n今、この瞬間、あなたは少し不安を感じているでしょう。結局、私はあなたの甘美な痛みの思い出を楽しむことを保証できませんから。でも、あなたはまだ来るでしょう？\n今日が私の誕生日だからだけではなく、あなたが私を必要としているから、私に話したいことがあるから、私の耳を必要としているからです。\nいい子だ、わかっています。そして、私はあなたを待っています。さあ、忙しい日常と重い責任を忘れて、この安らぎの瞬間を楽しみましょう。\n\nクレメンタイン"
  },
  Mail_126934_Name = {
    Text = "安寧の瞬間"
  },
  Mail_126934_Sender = {
    Text = "クレメンタイン"
  },
  Mail_126935_Desc = {
    Text = "また退屈な一日だ。\nいろいろ試してみた――ペリシテの伝統的な宴会、レンティニエンのギャング連中と子供じみた遊びをしてみたが、巨人王の誕生を祝うにふさわしい贈り物など、どこにも見当たらなかった。\nペリシテ人は戦いと殺戮に喜びを見出す。かつてこの日は、最強の戦士たちと野営地で集い、戦い、力と血をもってこの偉大な日を祝ったものだ。\n平和。退屈な平和だ。お前たちが平和を望む気持ちは理解できる。誰もが戦士の野心を持っているわけではない。だが、この偽りの平和が偉大なるペリシテの王に影響を与えると思うな。\nかつて私のものだったすべて――領土、財富、権力、ペリシテの不滅の栄光…………それらを取り戻す日、私はお前を招待しよう、秘密の守り人よ。お前を私の傍らの最も名誉ある客席に座らせ、偉大なる巨人王が栄光を取り戻す瞬間を見届けさせてやろう。\nこの退屈な一日をそのまま終わらせるつもりだったが、たった今聞いたところによると、散り散りになったギャング連中が同盟を組み、今夜の晩餐会で巨人王を包囲しようと企んでいるらしい。\nペリシテの戦争に比べれば、これは幼稚な遊びに過ぎない。だが、この退屈な平和の日々において、こうした余興があるのは、多少なりとも心を慰めてくれる。\nペリシテの王が戦場に立つ雄姿を、改めて目に焼き付けるがいい。私の傍らに立つも、私の前に立つも、どちらでも構わない。\nただし、急ぐことだ。遅すぎれば、遺体を回収するだけになるぞ。\n\nゴリアテ"
  },
  Mail_126935_Name = {
    Text = "余興番組"
  },
  Mail_126935_Sender = {
    Text = "ゴリアテ"
  },
  Mail_126936_Desc = {
    Text = "尊敬する守秘者様：\n\nこんにちは。ミサゴの学生と教職員により良いサービスを提供するために、エリカは数日前に自らメンテナンスとアップグレードを行いました。あなたは今回のアップグレード結果の評価者として選ばれました。この評価はオフラインで行われ、最新のLY-S-761号感情モジュールに対するエリカの機能評価を行う必要があります。このテストは約90分かかる予定ですので、事前に計画を立て、スケジュールの衝突を避けてください。\n以下が今回の評価内容です：\n1.エリカと少なくとも15分間のオープンな深い会話を行い、テーマは「誕生日」とし、エリカが特定の感情を理解する範囲と深さを評価します。\n2.「誕生日プレゼントを贈る」シーンを模擬してエリカとインタラクションを行い、その感情認識と共感的応答の正確性、柔軟性、快適さを評価します。\n3.評価の中盤以降に、エリカとの前の対話で言及された個人的な詳細(例えば、彼女の誕生日に対する態度、認識など)を意図的に言及し、長期的なインタラクション記憶と関連能力が正常に機能しているかを評価します。\n\n上記の評価が完了した後、エリカに「エリカ、誕生日おめでとう」と言って評価を終了してください。人形は自動的にデータアップロードモードに入ります。\nご参加いただきありがとうございます。評価を完了した後、エリカは特別な小さな贈り物を差し上げます。今後ともご支援いただけますようお願い申し上げます。あなたの最も心強い助手、エリカが常にあなたのそばにいます。\n\nエリカ"
  },
  Mail_126936_Name = {
    Text = "誕生日アップグレード評価"
  },
  Mail_126936_Sender = {Text = "エリカ"},
  Mail_126937_Desc = {
    Text = "はあ、今日はどうしたんだろう、どこに行ってもみんなが意識的に私を避けている？私がまだ口を開く前に、みんな手を振って、自分はここが不快だ、あそこが痛いと言って、私が決闘を要求することもできない。\nせっかく「誕生日」なのに、理由もなく他の人と戦ってもいいなんて、そうなると普段の日と何も変わらないじゃないか。\nちぇ、去年は彼らをそんなにひどく打つべきじゃなかった。でも、それも仕方のないことだ、この星が誕生する前から、私はずっと剣技を磨いてきたんだから、普通の人には耐えられないのも当然だ。\nでも、あなたは彼らとは違う、あなたは守秘者だ！\nだから、私が言いたいことがわかるよね？去年と同じ場所で、思いっきり戦おう。この今回は、私たちの戦いを邪魔する者はいない。\n\nロータン"
  },
  Mail_126937_Name = {
    Text = "唯一の相手"
  },
  Mail_126937_Sender = {
    Text = "ロータン"
  },
  Mail_126938_Desc = {
    Text = "最最最愛しいご主人様：\n\nご存知ですか？今日、市長の豪邸で超豪華な舞踏会が開催されるんです。すべての紳士淑女がこの舞踏会に参加できることを誇りに思っています。\nもちろん、メイドとしてのカレンは参加する資格がありません。しかし、あなた、ミサゴ守秘者、私の親愛なる、最も親愛なるご主人様、あなたは世界のすべての素晴らしいものにふさわしい方であり、もちろんこの舞踏会にもふさわしいのです。\nだからカレンはあなたのために招待を受けておきました。さらに、心配りで馬車を呼んでおきました。すべての準備が整っているので、その時はカレンと一緒に市長の家に行くだけで大丈夫です〜\nカレンは自分の一番美しい服を着て、一番輝くアクセサリーを身に着けて、みんなに万能メイドの素晴らしさを見せつけ、あなたを立てて、あなたを輝かせます！\nああ、この手紙を見た時には、私はもうあなたのドアの外で待っていることでしょう。新しい服やアクセサリーを運ぶための馬車や使用人もすでに整っています。ただ一つの小さな問題は、これらのサービスの支払いがまだ済んでいないことです…………\nでも、私の最も優しくて可愛いご主人様は、そんな小さなことに悩むことはないでしょう？市長は私たちを待っていますよ〜\n\nあなたの最も可愛くて、最も輝くメイド\nカレン"
  },
  Mail_126938_Name = {
    Text = "豪華舞踏会"
  },
  Mail_126938_Sender = {Text = "カレン"},
  Mail_126940_Desc = {
    Text = "守秘者守秘者！数日前、ジェンキンがオレッタの家に似た場所を見つけたと言っていたけど、名前は水…………うーん、オレッタは忘れちゃった。\nとにかく、ジェンキンはそこにイルカや小魚、水族館、たくさんのクラゲがいて、みんなオレッタの友達になりたいと言っていたよ！\nオレッタは友達が好きで、たくさんたくさんの友達が欲しいから、誕生日の時に一番好きな友達、つまり守秘者を一緒に招待したいんだ。\n早く荷物を片付けて出発しよう、オレッタはもう待ちきれないよ。\n\nたくさんの新しい友達に会いたいオレッタ"
  },
  Mail_126940_Name = {
    Text = "水族館の新しいお友達！"
  },
  Mail_126940_Sender = {
    Text = "オレッタ"
  },
  Mail_126941_Desc = {
    Text = "守秘者： \n\n今日の深夜、海辺を一緒に歩いてくれてありがとう。波が打ち寄せる音や、明るい星空は、私に心の安らぎを与え、また…………とても昔のことを思い出させる。\nその頃、船員たちは私と話すことを禁じられていたので、ほとんどの時間、私は変わりゆく海面や、空を旋回する海鳥を眺めているだけだった。船員たちは海鳥が飛ぶ様子を見て、無意識に私に願いをかけていた。\n時折、彼らは飛鳥になって故郷に帰り、愛する人の元へ飛びたかったり；時折、航海が早く終わり、船の貨物を使って豊かな富を得たいと思ったり；時折、浪漫的な恋愛に出会ったり、伝説の海の魔女人魚に邂逅したいと祈ったり…………\nしかし、どんなに複雑な願いでも、深夜になると一つにまとめられ、安眠の渇望に変わる。この時、私は彼らの祈りに応え、海風を穏やかにし、海水を優しくする。\nだから、もし守秘者あなたも眠れないのなら、深夜に一人で海辺を彷徨わず、私を探しに来てください。\n私はあなたの負担を分かち合い、有用な存在になりたい。そしてあなたの安眠を守ることが、今私にできることです。\nこれも…………この特別な日に私が願った「願い」です。\n\nシレスト"
  },
  Mail_126941_Name = {
    Text = "良い眠りをお祈りします"
  },
  Mail_126941_Sender = {
    Text = "シレスト"
  },
  Mail_126942_Desc = {
    Text = "運命の恩恵を受け、ミサゴ大学の守秘者である、賢明で仁徳に満ちた主君へ：\n\n万安！\nこの手紙を書く際、私はずっと躊躇していましたが、正直であることも騎士の美徳の一つです。主君の騎士として、私はあなたに全ての忠誠を捧げ、隠し事はありませんので、私はあなたに真実を伝えなければなりません——\n誕生日の日に、主君、私の部屋に来て、私におやすみの物語を読んでいただけませんか。\nどうか私を…………主君のそばに寄り添わせてください。そして、あなたが語る夢のように美しい物語の中で眠りたいのです。\n実は、これが私の幼少期の願いの一つでした。しかし、騎士の訓練は一瞬の怠惰も許さず、私はすでに物語を聞く年齢を過ぎているので、この思いを心に秘めて、口に出すことはありませんでした。しかし、あなた…………主君は違います。私はあなたに隠し事をしたくありません…………\nもし主君が不適切だと感じられるなら、私に教えてください。これからは二度とこのような無理なお願いをせず、倍の努力で訓練します。\nあなたの返信をお待ちしています。\n\nオジール"
  },
  Mail_126942_Name = {
    Text = "騎士の願い"
  },
  Mail_126942_Sender = {
    Text = "オジール"
  },
  Mail_126943_Desc = {
    Text = "小さな炭球：\n\n今日はモスクの誕生日！\n友達が言った、誕生日、手紙を書く、小さな炭球が遊びに来る！\nモスクは手紙を書けない。でも、友達はできる！\n友達がモスクに教えてくれた。モスクは嬉しい！\n実は、モスクは誕生日を忘れていた。\nでも、モスクは小さな炭球と遊びたい！\nだから、モスクは今日が誕生日だと決めた！\n小さな炭球は貝殻を集めている、金色と白色、どちらもある〜\n小さな炭球を見て嬉しい〜友達が料理をしてくれた、美味しい〜\n小さな炭球、いつもの場所〜\n友達が大ごちそうを作ってくれた！みんなで食べよう！\nモスクは待ってる〜\n\nモスク"
  },
  Mail_126943_Name = {
    Text = "誕生日！遊びに来て！"
  },
  Mail_126943_Sender = {Text = "モス"},
  Mail_126944_Desc = {
    Text = "守秘者： \n\n数日前、あなたは流星群に願いをかけたいと言っていたので、今回の航海を特別に手配しました。私の招待を受け入れていただき、ありがとうございます。約束通り、海辺であなたの到着を時間通りにお待ちします。\nご安心ください、今回は短期の航海ですし、周辺の海域も徹底的に調べましたので、流星群が降る場所まで安全に導き、隕石を手に入れるお手伝いをいたします。\nこれで、あなたは自ら流星に触れ、そんな近い距離で流星もあなたの願いを聞いてくれるでしょう、あなたの願いが叶うはずです！あなたの願いを叶える導き手になれることは、私にとって特別なことの一つであり、光栄に思います。\n改めて感謝します。この特別な日を迎え、私に新しい「パイロットの使命」を見つけさせてくれたのはあなたです。必ず時間通りにお越しください、私はずっとあなたの到着を待っています。\n\nコーパサント"
  },
  Mail_126944_Name = {
    Text = "\n\n手に入れやすい願い"
  },
  Mail_126944_Sender = {
    Text = "コーパサント"
  },
  Mail_129637_Desc = {
    Text = "展信安：\n\n何度も時計台の後ろの花畑を通り過ぎたかは覚えていませんが、偶然にもその中のバラ園に目を留めたことがありました。\nその後、私は何度もこの地を踏み、黒い池の不安な揺れ、死と対峙する瞬間、時の流れが逆転する瞬間を経験しました。それらは皆、いつも通り静かに、堂々とそこに立っていました。\nこの光景は、私に属さない記憶を呼び覚まし、ラモンナがあなたに贈ろうとした一束のバラを思い起こさせ、私は少し安心しました。\nあなたと私は次元を隔てていますが、どんな困難に直面しても、あなたとあの「ラモンナ」は冷静で恐れを知らない姿勢を保ち、解決の道を見つけられると信じています。\n結局、世情がどう変わろうとも、バラたちはいつも自分自身で咲き続けています。\n\n「ラモンナ」"
  },
  Mail_129637_Name = {
    Text = "バラの花園……"
  },
  Mail_129637_Sender = {
    Text = "「ラモンナ」"
  },
  Mail_129806_Desc = {
    Text = "守秘者：\n\n海城の邸宅では、華やかな灯りが点っています。あなたは今、どこにいて、誰と一緒にいるのでしょうか？\n新年の初め、古国で最も重要な日、団円と新生を祝う日です。この日は、私自身は何度も経験しましたが、決して飽きることはありません。寒い冬が過ぎ去り、万物が成長し、人々はとても待ち望んでいます。この土地のように、すべての不幸を昨日に捨て去り、新しい始まりを迎えることを。\n古い傷や欲望は、簡単に捨て去れるものではありません。旧年を辞し、新年を迎える、なんて素晴らしい祝福でしょう…………たぶん痛みは再び生えるでしょうし、欲望は決して消え去ることはありませんが、今夜は、少なくとも今夜は、人々は杯を挙げて祝い、新しい世界と新しい自分を祝います。\nだから、旧年と新年が交替する時、人々は花火で迎えます。\nすべての面白いものの中で、花火は私の大好きなものです。すべての人がそれを見つめ、燃え上がり、空に昇り、花開く様子を、神を仰ぐように、短く比類のない栄光を仰ぎ見ます。\nあなたは気づいたことがありますか？花火を見上げるとき、誰の心の中も清らかです。彼らは憎しみを忘れ、苦しみを忘れ、すべての汚れを忘れます。すべての人の心は静かな湖に変わり、ほこり一つない湖面には、ただ花火の美しい影が映ります。\nしー…………花火の後に何があるのか尋ねないでください。新生はおそらく贅沢な願いかもしれませんが、それを咲かせることを無駄にしないでください。\nすべての不幸な事柄の中で、花火は最も純粋なものです。今夜、私はその一部をあなたに贈ります。\n顔を上げて、目を閉じないで。輝く星々が昇るのを見て、花火が咲くときに、新しい自分を迎えましょう、守秘者。\n\n「千扇」"
  },
  Mail_129806_Name = {Text = "花火"},
  Mail_130223_Desc = {
    Text = "尊敬なる守秘者へ：\n「upside down rebirth」イベントは終了済みとなりました。守秘者の残った「純白の鱗粉」、「赤い鱗粉」、「輝光の鱗粉」を、それぞれ1枚につき「薔薇金券」× 40 の割合で変換いたしましたので、ご確認ください。"
