  Mail_131005_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_131093_Desc = {
    Text = "敬愛なる守秘者：\n「燃える饗宴・復刻」イベントは終了しました。\n\n残りの「原生の脛骨」、「円形菊石」、「螺旋遺跡」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_131093_Name = {
    Text = "燃える饗宴通貨回収"
  },
  Mail_131093_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_131767_Desc = {
    Text = "我@2！@3は@2至高@3混沌@4と破壊@2！高く叫べ@4…………！\n\nああ、あなたが何をしたのか見てごらん！！！あなたは至高の神の禁忌に触れた！これで良い、彼のささやきがあなたのいる世界に響き渡り、黒い災厄があなたの通信器から広がり、あなたの周りのすべてを飲み込む…………\nかわいそうなあなた、あなたの無謀さは本当に私を困らせる。でも、あまり絶望しないで、幸運にもあなたは私に出会った——偉大なる教派の仙女、神明の選ばれし者、至高の神の代行者、宏大な教派の法定継承者、苦しみの救済者、神王の親友！私は善意と愛の神の意志であり、この世の苦しみを見ることができない。私は私の至高無上の力を使って、すべての愚かな小悪党を救う。\nああ、本仙女はあなたの挑発的な目を見た。大丈夫、善神は人々を愛し、世間の愚かさを気にしない。救世主への不信は、すべての信者が通る道だ。これらのご挨拶は、神の代行者からあなたへの恩恵だ。\n今、光明の道があなたに示された：あなたの誠意を持って、@3の@2大聖堂に行き、善意の神にあなたの忠誠を捧げなさい。そうすれば、あなたは夢にまで見た力を得て、この悪夢の呪いから解放される。当然、あなたの財産も一緒に捧げる必要がある。誤解しないで、善意の神は世俗の報酬を気にしないが、彼の信者たちが仕事をするにはお金が必要だ。これらの俗なものを惜しまないで、親愛なる信者よ、一分の価値は一分の金だ。\n善意の神の名を叫び、神の奇跡が降臨する時を待ちなさい！\n\n偉大なる教派の仙女、神明の選ばれし者"
  },
  Mail_131767_Name = {
    Text = "本@2に触れないでください"
  },
  Mail_131767_Sender = {Text = "カラブ"},
  Mail_132339_Desc = {
    Text = "尊敬なる守秘者：\n「神王復活·復刻」イベントは終了しました。守秘者の残りの「疲弊の思念」、「哀愁の思念」、「歓喜の思念」をそれぞれ「薔薇金券」× 40 の割合で変換しますので、守秘者は受け取ることをお忘れなく。"
  },
  Mail_132339_Name = {
    Text = "「神王の復活」通貨回収"
  },
  Mail_132339_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_132458_Desc = {
    Text = "尊敬なる守秘者様：\n        『忘却前夜』へのご支援とご評価、誠にありがとうございます。守秘者がミサゴ大学でより良いゲーム体験を得られるよう、以下の体験調査アンケートにご協力いただけますようお願い申し上げます。ご協力いただいたお礼として、「シルバーコア」× 200を準備しておりますので、アンケートを完了すれば受け取れます。アンケートの締切は8月17日9:00ですので、 timely にご記入ください。\n        <SurveyLink:[こちらをクリックして記入]>\n        私たちはすべての守秘者の意見を真摯に受け止め、皆様のフィードバックがミサゴ大学をますます良くすることを確信しています！\n        ――銀の鍵が前路を導きますように。"
