  Mail_132605_Desc = {
    Text = "チュイチュイチュイ、チュイチュイチュイチュイチュイ！\n（守秘者、エイプリルフールおめでとう！）\nチュイチュイチュイ、チュイチュイ！\n（証明写真、記念に！）\n「雑然とした湿ったオタリアの爪跡」\n「たくさんの蝋印の失敗で残ったぼやけた貝殻の拓本」\n                                                         ――きちんとしたオタリアの爪跡の落款"
