  Mail_133703_Desc = {
    Text = "守秘者各位へ：\n{s1}バージョンは終了いたしました。守秘者の残りの「空幻のコア」は自動的に1個につき「無垢のコア」×1の比率で変換されました。今回変換された「無垢のコア」は× {s2} です。お受け取りをお忘れなく。"
