  Mail_133704_Desc = {
    Text = "守秘者各位へ：\n{s1}バージョンがまもなく終了いたします。守秘者の皆様は残りの「空幻のコア」をお早めにご使用ください。今期の学期課題終了後、残りの「空幻のコア」は1個につき「無垢のコア」×1の比率で変換されます。"
