  },
  Mail_134024_Desc = {
    Text = "守秘者様へ：\n「デイリー試験訓練」が削除されました。守秘者様に残っている「代理証明書」を1枚につき「薔薇金券」× 10000 の比率で変換いたしましたので、ご確認ください。"
  },
  Mail_134024_Name = {
    Text = "代理証明書回収"
  },
  Mail_134024_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_134067_Desc = {
    Text = "守秘者さんへ：\n\n今日、ちょっと特別なことを相談したくて。\n街をぶらぶら歩きたいの。普通にいろんな面白いものを見て、気の向くままにあちこち回って、平凡な一日を過ごしたいなって。\n\nそれで、教務処に聞いてみたの。そしたら、安全上の理由で、あなたが同行する場合のみ外出を許可するって。\nあと、他の人を怖がらせないように、外で何でも口に入れないようにって。失礼しちゃうわ。\nまあ、そういうわけで、お出かけできないかな？みんな一緒にね。\n\n…………なんだか思ったの。タンポポの種って、\nいつか風に乗って、自分の運命の地へ旅立つんだよね。\nそれは明日かもしれないし、ずっとずっと先のことかもしれない。\nそう考えたら、今のうちにみんなと一緒にたくさんのことをするのも、悪くないなって。\n\nとにかく、寮の前で待ってるね。お願い！\n\n沙耶"
  },
  Mail_134067_Name = {
    Text = "お散歩…………"
  },
  Mail_134068_Desc = {
    Text = "秘密の守り手さんへ：\n\n今日は、特別な日だと思うの。でも記憶の輪郭は、やっぱりぼんやりとしていて。\nただ「サヤ」という名前だけが、かろうじて私をこの場所に繋ぎ止めている。\n\nあの感覚は寂しさでもなく、悲しみでもなく、そんな鮮明な感情じゃない。\nもし無理にこの気持ちに名前をつけるなら…………きっと、「空白」かな。\n何もなくて、果てしなく澄み渡って透明で、静寂の時間。\n\nもしいつか、風に乗って飛んでいくタンポポの種が、\nこの世界のあらゆる場所に、ただ白く、静かに降り注いだら…………\nその時、私はようやくこの世界を『特別なもの』だと感じられるかもしれない。\n\nその時、ロンディニウムに漂う灰色の霧も、夕暮れに燃える真紅の茜空も、あなたがいつも学校の広場から見上げていた空も、すべてタンポポに覆われて、純白の色に変わるの。私だけの色に。\n\nだから…………もし、あなたが私に何かをくれるなら。\nそれはプレゼントじゃなくていい、ただ一つの『記憶』でいいの。\n\n私は、タンポポが咲き誇る純白の世界で、\nただ静かに、その瞬間が訪れるのを待っている。\n\nいつかまたミサゴ広場で空を見上げた時、\n視界の端をかすめるあの白い綿毛を、\nかつてあなたと言葉を交わした私の姿と、少しだけ重ねてみてね。\n\nサヤ"
  },
  Mail_134068_Name = {
    Text = "タンポポの約束…………"
  },
  Mail_139809_Desc = {
    Text = "親愛なる守秘者の皆様へ：\n        『忘却前夜』へのご支援とご評価をいただき、誠にありがとうございます。守秘者の皆様にミサゴ大学でより良いゲーム体験をお届けするため、以下の体験アンケートへのご回答をお願いしております。ご協力への感謝として、「銀芯」× 200 を報酬としてご用意しており、アンケート完了後に受け取ることができます。アンケートの締め切りは5月16日9:00となっておりますので、お早めにご回答ください。\n        <SurveyLink:【こちらをクリックして回答する】>\n        すべての守秘者の皆様のご意見を真摯に受け止め、皆様のフィードバックによってミサゴ大学がより良くなっていくことを確信しております！\n        ――銀の鍵が前途を照らさんことを。"
  },
