  },
  Mail_141507_Desc = {
    Text = "守秘者：\n\n誕生の日、あなたにとっては、もしかしたら特別な日かもしれませんね？\n私にとっては、運命の網の中の毎日は同じ重さを持っています。他の物語が、この日を特別な意味を持たせているのです。\n私はこの日に誕生し、この日に予言を理解し、この日に運命を紡ぐ紡錘を得て、この日に複雑な運命の糸を見、糸の先にある悪夢を見ました。\n運命の紡ぎ手にとって、この日は平凡です。舞台の俳優にとって、この日は祝うべき日です。そして、すべてのアイデンティティの中で、私が最も喜びを感じるのは、俳優としての自分です。\n守秘者よ、今日、運命劇場の灯りはすべて消え、ただ一つの舞台が明るく輝いています。あなたは以前、私が経験した運命をもっと見たいと話していました。そして今、この舞台で上演されるのは、私自身の物語です。\n私はそれがどの物語になるのか知りません。私は思い出を舞台に送り出します。彼女はその強烈な瞬間の中で、あなたが最も期待する一幕を選び、今夜の舞台で披露します。\nその物語は私を苦しめるかもしれないし、恥ずかしい思いをさせるかもしれませんが、それは重要ではありませんよね？私は、時には紡錘に自ら編ませ、純粋な観客でいることが楽しいことだと思います。\nこの公演の唯一の入場券は、今あなたの手の中にあります。この手紙を持って来てください、守秘者。今夜、他の誰も知らない物語が、あなたの到来を待っています。\n\nアラクネ"
  },
  Mail_141507_Name = {
    Text = "隠密な物語"
  },
  Mail_141507_Sender = {
    Text = "アラクネ"
  },
  Mail_141833_Desc = {
    Text = "シークレットキーパーの皆様へ：\n「新月と深雪」イベントが終了しました。シークレットキーパーの手元に残っている「赤いリンゴ」・「金のリンゴ」・「飴リンゴ」を、それぞれ1枚につき「薔薇金券」× 40 の割合で変換いたします。お受け取りをお忘れなく。"
  },
  Mail_141833_Name = {
    Text = "リンゴ回収"
  },
  Mail_141833_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_141957_Desc = {
    Text = "敬愛なる守秘者へ：\n        『忘却の前夜』へのご支援とご愛顧に感謝申し上げます。守秘者にミサゴ大学でより良いゲーム体験をしていただくため、以下の体験アンケートへのご記入をお願いいたします。ご協力への感謝として、「シルバーコア」× 200 をご用意しております。アンケート完了後に受け取れます。アンケートの締め切りは2月15日9:00です。お早めにご記入ください。\n        <SurveyLink:【クリックして記入へ】>\n        すべての守秘者のご意見を真摯に受け止め、皆様のフィードバックが必ずやミサゴ大学をより良くしていくと信じております！\n        ――銀の鍵が前路を導きますように。"
