  Mail_141962_Desc = {
    Text = "敬愛なる守秘者へ：\n        『忘却の前夜』へのご支援とご愛顧に感謝申し上げます。守秘者にミサゴ大学でより良いゲーム体験をしていただくため、以下の体験アンケートへのご記入をお願いいたします。ご協力への感謝として、「シルバーコア」× 200 をご用意しております。アンケート完了後に受け取れます。アンケートの締め切りは5月10日9:00です。お早めにご記入ください。\n        <SurveyLink:【クリックして記入へ】>\n        すべての守秘者のご意見を真摯に受け止め、皆様のフィードバックが必ずやミサゴ大学をより良くしていくと信じております！\n        ――銀の鍵が前路を導きますように。"
