  },
  Mail_142101_Desc = {
    Text = "久しぶりだね、%player%：\n\nこの手紙が届く頃、私はきっとヤグロの上空を通過しているはずだ。毎年この月になると、私の巡猟の旅はいつもより遠くへ向かう。\n敵の悲鳴と断末魔の叫びほど、誕生日のBGMにふさわしいものはない。それに、私は十分な牢獄を用意してある。痛みしかもたらさない偽りの神を信奉する愚か者がいる限り、天の果て地の果てまで追いかけて、自分の過ちを思い知らせてやる。\nたまに、魇が雲を抜けて月が見える瞬間、ふと馬鹿げた考えが頭をよぎることがある。\nたとえば、こんな時間がいつか突然、抗いようもなく強制的に終わりを告げるのだろうか、と。かつて生活が何の前触れもなく崩れ落ちたように。\nでもすぐに、自分のことがおかしくなって笑ってしまう。あの道に踏み込んだ日から、私は退路のない旅路に立っている。あなたなら私の言いたいことがわかるはずだ、坊や。この世界で、あなたと私ほど境遇が似ている者はいない。\n私たちはどちらも、選択の余地のない選択をした。良い知らせは、私たちがどちらも自分の選択を楽しんでいるということだ。\n新しい一年、私が贈った猟笛を吹きさえすれば、いつでもあなたのそばに現れる。\nもちろん、特に何もなければ、まずはこの旅をじっくり楽しませてくれ。来月、お土産と新しい見聞を持って帰るよ。\nあなたの幸運を祈る、そして楽しく過ごしてほしい。\n\nあなたの親愛なる「おじさん」"
  },
  Mail_142101_Name = {Text = "見聞"},
  Mail_142101_Sender = {
    Text = "あなたの親愛なる「舅舅」"
  },
  Mail_143935_Desc = {
    Text = "敬愛なる守秘者：\n「一時的なテキスト」イベントは終了しました。現在、守秘者の残りの「一時的なテキスト」、「一時的なテキスト」、「一時的なテキスト」をそれぞれ「薔薇金券」× 40 と交換しますので、守秘者の方はお忘れなくご確認ください。"
  },
  Mail_143935_Name = {
    Text = "一時的なテキスト回収"
  },
  Mail_143935_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_145435_Desc = {
    Text = "親愛なる守秘者へ：\n「リヴァイアサンの遊戯」活動は終了済みです。守秘者の残り「血染めの供物」を1枚につき「薔薇金券」× 40の比率で変換いたしました。受け取りをお忘れなく。"
  },
  Mail_145435_Name = {
    Text = "血染めの供物の回収"
  },
  Mail_145435_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_145468_Desc = {
    Text = "親愛なる守秘者へ：\n「もしすべてが普段通りなら·クローン」活動は終了済みです。守秘者の残り「海辺の特産貝殻」を1枚につき「薔薇金券」× 40の比率で変換いたしました。受け取りをお忘れなく。"
  },
  Mail_145468_Name = {
    Text = "海浜特産貝殻の回収"
  },
  Mail_145468_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_146401_Desc = {
    Text = "暦とは退屈な発明だ。今日を含め、すべての日に何ら違いはない。\nあなたたちの暦によれば、今日は私が生まれた日だという。「生まれた」という言葉は私には正確ではない。私は混沌から引き裂かれた残骸であり、無数の戦いの中で研ぎ澄まされた刃だ。私を鍛えたのは母体ではなく、かつて私と刃を交えたすべての相手だ。そしてあなたは、その中でも特に重要な一人だ。\nあなたたちはこのような日を大切にする。宴会、贈り物、祝辞――私にはそれらは必要ない。\n私が必要なのは、ただ一つの戦いだ。\nこの間、あなたは数多くの信じがたいことをやってのけた。しかし私は知っている。あなたが見せてきたものは、まだあなたの限界にはほど遠い。\n今日の夕暮れ、訓練場へ。武器を持って来い、私はそこで待っている。勝敗を気にする必要はなく、傷を恐れる必要もない。刃が何も保留せずぶつかり合うその瞬間こそが、私が唯一期待する祝いの贈り物だ。@4の欠片が、一体どこまでできるのか、見せてくれ。\nきっとあなたは私を驚かせてくれるだろう、私の「相手」よ。"
  },
  Mail_146401_Name = {
    Text = "唯一の期待"
  },
  Mail_146401_Sender = {
    Text = "蝕滅・ロータン"
  },
  Mail_146873_Desc = {
    Text = "敬愛なる守秘者：\n「一時的なテキスト」イベントは終了しました。現在、守秘者の残りの「一時的なテキスト」、「一時的なテキスト」、「一時的なテキスト」をそれぞれ「薔薇金券」× 40 と交換しますので、守秘者の方はお忘れなくご確認ください。"
  },
