  },
  Mail_146873_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_147081_Desc = {
    Text = "暦とは退屈な発明だ。今日を含め、すべての日に何ら違いはない。\nあなたたちの暦によれば、今日は私が生まれた日だという。「生まれた」という言葉は私には正確ではない。私は混沌から引き裂かれた残骸であり、無数の戦いの中で研ぎ澄まされた刃だ。私を鍛えたのは母体ではなく、かつて私と刃を交えたすべての相手だ。そしてあなたは、その中でも特に重要な一人だ。\nあなたたちはこのような日を大切にする。宴会、贈り物、祝辞――私にはそれらは必要ない。\n私が必要なのは、ただ一つの戦いだ。\nこの間、あなたは数多くの信じがたいことをやってのけた。しかし私は知っている。あなたが見せてきたものは、まだあなたの限界にはほど遠い。\n今日の夕暮れ、訓練場へ。武器を持って来い、私はそこで待っている。勝敗を気にする必要はなく、傷を恐れる必要もない。刃が何も保留せずぶつかり合うその瞬間こそが、私が唯一期待する祝いの贈り物だ。@4の欠片が、一体どこまでできるのか、見せてくれ。\nきっとあなたは私を驚かせてくれるだろう、私の「相手」よ。"
