  },
  Mail_148514_Desc = {
    Text = "シークレットキーパーの皆様へ：\n        Ⅴ1.4.3.5バージョンのアップデートにて、「異夢視界：冒涜」にステージ「新王」を追加しました。一部のシークレットキーパーがこのアップデート内容を把握できず、「異夢視界：冒涜」をすべてクリア済みと誤認してしまいました。\n        これを受け、今回のⅤ2.6.2バージョンのアップデートにて、アップデート前に「新王」以降のステージをクリア済みのシークレットキーパーに対し、「新王」ステージのクリア進捗を補完し、対応する初回クリア報酬も合わせて補填いたします。お受け取りください。"
  },
  Mail_148514_Name = {
    Text = "「冒涜」進捗の補完"
  },
  Mail_148514_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_148515_Desc = {
    Text = "親愛なるシークレットキーパーへ：\n\nじゃじゃーん～意外でしたか？これはこの仙女がミサゴで迎える最初の誕生日なので――\nなんと！セール案内も、礼拝の招待も、終末の予言さえも一切なし～\nでもがっかりしないで、この仙女はもちろん、最も特別な信徒のために、もっと貴重で素晴らしい特典を用意していますよ。\n全知全能の仙女の教母として、当然ながらそういった疑念や警戒心も予見できます。それがこの仙女を少し悲しい気持ちにさせるとしても、教派の恵みを広めるためには、ささやかな犠牲はやむを得ないものです。\nですから、一万歩譲って考えてみて、試してみてください。どうせ何も失うものはないのですから、もし本当だったら？そうでしょう？\nこれは年に一度だけの、何があっても逃してはならない機会ですよ～\n何も供物は必要なく、約束や取引も一切不要。ただ仙女の教母と甘いアフタヌーンティーをご一緒するだけで、氷雪の下に、どれほど真摯な想いが埋められているかを知ることができます。\nこれは魅力的な提案ではないでしょうか？\n備考：お会計に十分な少なくとも10、100、1000レオフアンを必ずご持参ください。多ければ多いほど良いです。\n\nあの私たちが知っているお店で待っています\nカラブ"
  },
  Mail_148515_Name = {
    Text = "☆☆☆超級福利メール☆☆☆"
  },
  Mail_148515_Sender = {Text = "カラブ"},
  Mail_149949_Desc = {
    Text = "このメールはあの世とこの世を千度巡りたるもの、決して削除するなかれ！\n\n七月半、鬼門開き、陰風起こり、幽魂帰る。\n我は磐龍古国扈城■■■、一紙靥なり！\n中元の勅令を奉じ、招魂の符牒を持ち、今宵ここに呪いを降す。この文字を見た者、魂は名簿に記され、名は帳に上りたり。子の刻までに五十人の陽世の者へと転送せざれば、必ずや――\n文書は保存前の一瞬に崩壊し……\nタピオカミルクティーのパールが必ず三粒足りなくなり……\nシルバーコア通信機の電池残量が永遠に1%で止まり、充電しても満たされず……\n\n素直に従えば、呪いは自ずと解け、符は自ずと燃え、悪霊は纏わりつかず、灯もまた長く明るく輝かん。\n転送せよ！！今すぐ！！！"
  },
  Mail_149949_Name = {
    Text = "【中元警告】このメールを削除する者には、必ず……"
  },
  Mail_149949_Sender = {Text = "一紙靥"},
  Mail_149985_Desc = {
    Text = "主君へ：\n\n突然のお手紙、ご無礼をお許しください。ですが、ある想いは、あなたにしか打ち明けられないのです。\n昨夜、久しぶりに夢を見ました。夢の中で、私はかつての我が家へと戻っていました。すべてが懐かしく、父の優しく大らかな手のひら、女中が掃除をしながら口ずさんでいた田舎の歌、そして私だけの白い小さな馬……とうの昔に記憶の泥沼へと置き去りにしてしまったと思っていたのに、夢の中で再び目にしても、やはりあの温もりは変わりませんでした。\n目が覚めると、窓の外ではミサゴの師生たちがおしゃべりをしながら通り過ぎていき、なんと穏やかで美しい光景でしょう。一瞬、その情景が夢の中と何ら変わらないように思えました。そして気づいたのですが、私に憑いているあの見えないものが、今朝からずっとひどく静かなのです。もしかして、誕生日というのは本当に、幸運なことが起きる日なのでしょうか。\nもしそうならば、今日くらいは少し欲張ってもいいかもしれません……\n人は誕生日に願い事をするものだと知っています。一年への祈りとして。誰かに誕生日を祝ってもらえるなど、とうに望むことをやめていましたが、ひとつだけ、叶えてほしい機会があるのです。\n主君が私に信頼を委ねてくださるように、私もあなたに対して保留にすることは何もありません。ですから、どうかその願いをお伝えすることをお許しください：\n次に主君が任務をお命じになる際には、どうか私を護衛に任命し、共に行かせてください。\nいかなる時も、あなたが最も助けを必要とする瞬間に、真っ先にあなたの前に立ちはだかり、最も堅固なシールドとなれるよう、そう願っています。\nこれが、今年私が心に誓った願い事です。\n\nオジール"
  },
  Mail_149985_Name = {
    Text = "誕生日の願い事…"
  },
  Mail_149985_Sender = {
    Text = "負誓·オジール"
  },
  Mail_18019_Desc = {
    Text = "親愛なる守秘者：\nシステムが現在のアカウントに対して返金行為を検出しました。制作チームは{s1}にあなたの返金注文に基づく仮想貨幣部分を差し引きました。該当する貨幣が差し引かれた後に負の数になる場合は、正数に戻すまで正常には使用できません。\n疑問がある場合はカスタマーサポートにご連絡ください。"
  },
  Mail_18019_Name = {
    Text = "返金処理通知"
  },
  Mail_18019_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_18020_Desc = {
    Text = "こんにちは、守秘者。{s1}で獲得した報酬は、バッグがいっぱいのため、メールの添付ファイルとしてお送りします。バッグを整理してから受け取ってください"
  },
  Mail_18020_Name = {
    Text = "未受け取り報酬の補填"
  },
  Mail_18020_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_18021_Desc = {
    Text = "親愛なる守秘者：\n今期の課題記録活動は{s1}に終了します【GMT+8】。活動終了後は、今期の課題記録に関する報酬が取得できなくなりますので、活動終了前に適時、報酬の受け取りをお願いいたします。"
  },
  Mail_18021_Name = {
    Text = "課題報酬受取通知"
  },
  Mail_18021_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_18029_Desc = {
    Text = "こんにちは、守秘者様。\nこちらは、幻夢の深奥のランキング報酬になります。"
  },
  Mail_18029_Name = {
    Text = "幻夢の深奥ランキング報酬"
  },
  Mail_18029_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_18031_Desc = {
    Text = "親愛なる守秘者：\n\n道は険しく、困難な時だからこそ、私たちは一緒に進む必要があります。\n本日特別に許可されたエンフェリンサプライを同封しましたので、受け取ってください。\n銀の鍵が道を照らさんことを。\n追伸：今回の特別サプライはこれにて終了です。あなたの努力と勤勉に感謝します。\n\nミサゴ校委員会後方支援部"
  },
  Mail_18031_Name = {
    Text = "エンフェリンパス発行"
  },
  Mail_18031_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_18034_Desc = {
    Text = "こんにちは、守秘者様。幻夢の深奥累計点報酬が受け取られていませんので、メールの添付ファイルとしてお送りしました。"
  },
  Mail_18034_Name = {
    Text = "幻夢の深奥累積報酬未受領"
  },
  Mail_18034_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_18035_Desc = {
    Text = "親愛なる守秘者：\n\n前途は長く、茨が密集しています。\nこのような困難な時だからこそ、私たちは一緒に進む必要があります。\n\nこの手紙には、本日特別に特別に許可されたエンフェリン補給を同封しましたので、お受け取りください。\n\n銀の鍵が道を照らさんことを。\n追伸：特別補給は残り{s1}日です。\n調査の時間を適切に計画してください。\n\nミサゴ校委員会後方支援部"
  },
  Mail_18035_Name = {
    Text = "エンフェリンパス発行"
  },
  Mail_18035_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_20231_Desc = {
    Text = "親愛なる守秘者様、対人戦の新シーズンが始まりました。あなたのランクは{s1}から{s2}にリセットされました。新シーズンのランク報酬もリセットされ、ランクアップでより多くの栄光と報酬を獲得できます！{s3}\n{s4}"
  },
  Mail_20231_Name = {
    Text = "対人戦のシーズンメール"
  },
  Mail_20231_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_21453_Desc = {
    Text = "親愛なる守秘者様へ\n\n突然失礼します。最近、お元気でいらっしゃいますか?\nお忙しいところ申し訳ないのですが、ジェンキンたちが私のために、ささやかな誕生日パーティーを開いてくれることになりました。\nすごく、すごく悩んだのですが……やっぱり、自分でこの招待状をお届けしたくて。\n\nワークハウスにいる孤児たちは、自分の本当の誕生日を覚えていないことが多くて、サラさんは、私たちがワークハウスに来た日を、誕生日にしてくれました。\nでも、私だけは違うんです。\nサラさんが言うには、私はものすごく寒い冬の夜に、ワークハウスの玄関先に置き去りにされていたそうです。\nだから、私の一生が冷たく、寂しいものにならないように……サラさんは、暖かい日を私の誕生日に選んでくれました。\n\nだから今日は、私にとって、誰かに気にかけてもらえて、愛してもらえた、特別な日なんです。\nこの大切な日を、守秘者様とも一緒に過ごしていただけたら……というのが、私のささやかな願いです。\nもちろん、叶わなくても大丈夫です。\n守秘者様にはたくさんのお仕事があるって、アイギス、ちゃんとわかってますから。\n\nもし、この招待でご迷惑をおかけしていたら、必ず教えてくださいね。\n心から、お詫びします。\nでも、もしも……本当にお時間ができたなら、みんなのドタバタにも、ぜひ、ぜひいらしてください。\nもしかしたら、ものすごく楽しいかもしれません。\nだって、ジェンキンが準備したんですから。\n\nアイギス"
  },
  Mail_21453_Name = {
    Text = "お忙しいのに、ごめんなさい……"
  },
  Mail_21453_Sender = {
    Text = "アイギス"
  },
  Mail_21454_Desc = {
    Text = "おい\n\n生まれた日というだけで、何がそんなにめでたい？\nなぜあのように大騒ぎをする必要がある？\n\n去年の今日、ある学生が我に誕生日を聞いてきた。\n笑わせる。\n我が生まれたとき、この星にはまだ「時間」という概念すらなかった。\nその学生があまりにもしつこいから「昼夜が交差する時間」だと答えた。\nそいつがどう解釈したのかは分からん。\n\nこの手紙を書いたのは、ひとつの忠告だ。\n今夜12時を過ぎたら、我の部屋の前にある花は片づけておけ。\n匂いがきつくてたまらん！\n\nロータン"
  },
  Mail_21454_Name = {
    Text = "あの花……"
  },
  Mail_21454_Sender = {
    Text = "ロータン"
  },
  Mail_21455_Desc = {
    Text = "エリカが今日、大きなコーヒーの袋を持ってきた。\n誕生日プレゼントで、中身はあなたの今年の配給一年分だと言っていた。\n<Del:でも、いいの？あなたが自発的にしたこと？>\nもしこれがドールか誰かの悪ふざけなら、惜しいけど返すつもり。\n\nだってコーヒーだよ！少し控えるだけでも眠くて仕方がないのに、一年も飲まないなんて耐えられる？\nトゥルーのように眠りこけるに決まってる。\n彼が悪いわけじゃないけど、黒い物は夜に現れるものね……\n\nともかく、もし必要ならコーヒーは返すし、もしこのままここに置いて良いなら、<Del:それはもう>私はとても喜ぶと思うんだ。\nそうしたら、私はついにやりたかった実験ができる。\nカフェインを抽出して濃縮し、皮膚から吸収される薬にして貼り付けてずっと覚醒したままにする……ずっとね。\n\nその実験がとてもしたいウインクルより"
  },
  Mail_21455_Name = {
    Text = "コーヒー"
  },
  Mail_21455_Sender = {
    Text = "ウインクル"
  },
  Mail_21456_Desc = {
    Text = "誕生日？\n興味はないが……強いて言うなら、俺の誕生日は決して良い日じゃない。\n何百何千もの無垢な命がこの日に死んでいった——俺が「生まれ」、そしてさらに多くを殺すためだけに。\n\nだから、この日は祝うに値しない。\nだが、お前ら人間は「儀式」ってものを重んじる生き物だとは知っている。\nちょうど手元に少しお金がある——安心しろ、マス・クラブで汗を流して稼いだ金だ。\n違法な収入じゃない。\n\nこの金で、自分用に何か買いな。\n俺の誕生日祝いのつもりでさ。\n\nユウハシュ"
  },
  Mail_21456_Name = {
    Text = "誕生日……"
  },
  Mail_21456_Sender = {
    Text = "ユウハシュ"
  },
  Mail_21457_Desc = {
    Text = "守秘者へ\n\nミサゴの地には誕生日を祝う習慣があるのでしょうか？\n記憶の中のわたくしの故国では……毎年盛大な儀式が行われ、王の誕生を祝っていました。\n長い年月が経つにつれて、「誕生日」というものは、すべての人に特別な意味を持つようになったのですね。\n\n遠い昔、誕生日を迎えるたびに、同僚や親しい者たちが遠方からわざわざ、わたくしのもとへ集まってくれました。\n愛する人々に囲まれるあの感覚……\nまるで太陽に抱かれているかのような温もり……\nそれこそが、わたくしが過去を手放せずにいる理由なのかもしれません。\n\nああ……話が逸れてしまいました。\nお仕事の邪魔をしてしまったでしょうか。\n過去によく食べていたお茶菓子を少し用意しましたので、ぜひご一緒できればと思いまして。\nもしお時間が許すようでしたら、夕食後にお立ち寄りください。\n\nファロス"
  },
  Mail_21457_Name = {
    Text = "不滅の光……"
  },
  Mail_21457_Sender = {
    Text = "ファロス"
  },
  Mail_21458_Desc = {
    Text = "今日は確かに記念すべき日だ。\n偉大なる俺様、巨人の王がこの世に降臨した日なんだからな。\n海が震え、星が色を失うほどの1日だ。\n聞いたところによると、大学内じゃ贅沢は禁止されているらしい。\nだったら例年の10分の1の規模で俺様生誕の宴を開こうじゃないか——\n子豚の丸焼き10頭、タコの串焼き100本にペリシテの民謡を演奏できる楽団、ああ踊り子も1ダースくらいは欲しいな……\nなに、全部却下だと？\nじゃあ踊り子だけでいい……1ダースもいらない、4、5人いれば十分だ。\nなに、それも駄目！？\nこんな貧相な規模では俺様にふさわしくない。\n今、宣言する——宴の計画は中止だ！\n\nゴリアテ"
  },
  Mail_21458_Name = {
    Text = "宴の計画……"
  },
  Mail_21458_Sender = {
    Text = "ゴリアテ"
  },
  Mail_21459_Desc = {
    Text = "守秘者——\n\n今日はシルヴィアさんのところで記憶訓練をしているときに、彼女が私の誕生日について聞いてきたんだ。\n君も知っているだろうけど、私なんてさっき置いたレンチのことだってすぐ忘れるくらいだから、誕生日なんて覚えているわけがないよ！\nしかもそれが私しか知らないことだなんて、もはやその誕生日は消えちゃったも同然さ。\n\nでもね、サルバドル神父が言うには、具体的な日付は重要じゃなくて、大切なのは毎日何を祝うかなんだって。\nだから私は決めたんだ、今日が私の誕生日だって！\nもう一人（誰だったか忘れちゃったけど、たぶん君じゃないよね、守秘者？）と食堂の入口でパーティーを開催する約束をしたんだ。絶対来てね！\n\n絶対絶対この誕生日の日付は忘れないナウティラより\n\n一緒に送られてきたメモ：\nその子は手紙を書き終わると慌ただしく出て行って、手紙と「守秘者への贈り物」と言っていたものを机に置き忘れていったよ。\nその品物はすべて封筒に入れておいたからね。\n今夜のパーティーで会えるのを楽しみにしているよ。\n安心して。私が彼女にちゃんと今夜のことを思い出させるから。\n——シルヴィア"
  },
  Mail_21459_Name = {
    Text = "誕生日を決めたわ！"
  },
  Mail_21459_Sender = {
    Text = "ナウティラ"
  },
  Mail_21460_Desc = {
    Text = "小さな者よ： \n\n根源の海には星や月、季節の変化がありません。したがって、私の誕生日は【不明】と記録されるべきです。\nしかし今日は特別な日です。この姿は「心願」を持つある人間から受け継いだものですから。彼女は賑わいを好み、この小店を開きましたが、あちこちの調査のために誕生日はいつも私一人が傍にいるだけでした。彼女の生前の心願を叶えるため、今日、解憂商店ではキャンドルディナーを開催します。忠実なお客様はぜひお越しください。\nもちろん、解憂商店はご来店のすべての方に小さな割引を提供しますので、小さな者よ、お見逃しなく。\n\nダフォダイル"
  },
  Mail_21460_Name = {
    Text = "人間の心願"
  },
  Mail_21460_Sender = {
    Text = "ダフォダイル"
  },
  Mail_21461_Desc = {
    Text = "昔、家族から引き離されたときに、養母である執政官夫人は、私の出生を記した陶製の札を粉々に砕いて、私がデロス人であった過去そのものを打ち砕いた。本当の誕生日なんてもう語りようもないの。\nライで別れてから、私なりに考えた……私が牢獄を脱出して、復讐を始めた夜を「誕生日」とするのはどうかなと。君はどう思う？\n今さら年を取ることを祝う必要はないけど、時間の移り変わりを確かめる指標としては、悪くないかもね。"
  },
  Mail_21461_Name = {
    Text = "生まれた日"
  },
  Mail_21461_Sender = {
    Text = "ヘロット"
  },
  Mail_21462_Desc = {
    Text = "テスト、テスト。\n敬愛なる守秘者、こんにちは。この手紙を受け取ったということは、あなたの意見がエリカにとって非常に重要であり、オートマタ「エリカ」の言語モジュール機能の年次検査とメンテナンス計画に選ばれたことを意味します。今回の評価は簡単な質問形式で行われ、オートマタ「エリカ」に新たにインストールされたEA-L-1033号言語モジュールの機能を評価するもので、あまり時間を取らせませんので、緊張せずにお答えください。\n簡単な質問：\nこの手紙の要旨を理解しましたか？\n\n回答を簡単な質問の下の空白に直接記入し、手紙を封筒に戻してください。\nご協力ありがとうございます。\n\nエリカ"
  },
  Mail_21462_Name = {
    Text = "テスト、テスト"
  },
  Mail_21462_Sender = {Text = "エリカ"},
  Mail_21463_Desc = {
    Text = "守秘者：\n\nお前はこの学園で、数少ない「正気を保った人間」だ。\nお前はこの欠けた肉体を越えて、僕の本当の姿を見通している。\n\nそんなお前なら、子供たちにも説明できるはずだ。\n僕は人魚などではない。\nこの身は、いずれ海を渡り、山を越え、真なる姿へと至る存在だ。\n\n……まあ、いい。\nお前を困らせるつもりは無い。\nただ、少なくとも今日は、子供たちに僕のしっぽで遊ばせないようにしてほしい。\n\n今日という日は、少し特別な日だから。\nもし時間があるなら、お前に直接話しておきたいことがある。\n\nカエクス"
  },
  Mail_21463_Name = {
    Text = "完璧な体……"
  },
  Mail_21463_Sender = {
    Text = "カエクス"
  },
  Mail_21464_Desc = {
    Text = "守秘者へ\n\n私にとって私の誕生日とは、父が私を引き取ってくれた日。\nこれまで父はその日をとても大切にしていて、毎年盛大な舞踏会を開いてくれた——コルセットを着て踊るのは、剣を三千回振るよりも疲れるけどね。\nそれは父が「父親」として私に向けてくれる気持ち。私はその大事な愛情を、無駄にしたくない。\nでも今年は、ついに父が誕生日の過ごし方を私に任せてくれることになったわ。父の目には、私はもう守る必要のある小さな子供ではないのかもしれない。\nそれで、私と一緒に鐘楼の頂上に行かない？すこしお話をして風に当たりたいの。\n今夜は満月になるらしいわ。\n\nラモンナ"
  },
  Mail_21464_Name = {
    Text = "満月……"
  },
  Mail_21464_Sender = {
    Text = "ラモンナ"
  },
  Mail_21465_Desc = {
    Text = "親愛なる、最愛のご主人様へ：\n\nそうです、今日はカレンの@1歳の誕生日ですよ！（レディの年齢は秘密です！）\nそれを祝して、カレンは比類なき盛大なパーティーを用意しました！\n招待できる限りのお友達を呼びました！\n結局来ると約束してくれたのは、オレッタ、オジール、リリーだけですが……\n\nでも大丈夫！\n人がいればパーティーは開けるし、パーティーがあればカレンはそこにいます！\nそのために「改良版」ガマシチュー、ガーリック風味の泥炭ナメクジ、そしてカレーコウモリスープを丁寧に準備しました！\nご主人様もぜひ味わってくださいね！\n\nそしてこっそり聞きますが、ご主人様、きっとカレンへのプレゼントをご用意されていますよね？\nもちろん、キラキラ輝くものですよね？\n\n永遠にご主人様に仕える忠実なメイド\nカレンより"
  },
  Mail_21465_Name = {Text = "贈り物"},
  Mail_21465_Sender = {Text = "カレン"},
  Mail_21466_Desc = {
    Text = "親愛なる<Del:守秘者>西区のヤツへ：\nこれは<Del:招待しょ 要請かん 招待しょ 招待>まぁ要するに無料のケーキを食べに来いって話で、ついでにあたしの誕生日を祝ってくれてもいいぞ！実を言えば、お前が前にあたしの姉ちゃんを見つけてくれたのと、あたしたちをここに連れてきて、ブラウンと安心して暮らせる場所をくれたことのお礼でもある。\n（こんなメンドウなことを書いてるのは、アイギスがそうしろって言ったからだぞ。ちょっと恥ずかしいけどな。でもあたしらの間柄だと、こんなのいらないだろ、な、守秘者？）\n要するに、今晩、お前の宿舎の裏庭であたしとブラウンとアイギスが手作りした美味しいものを用意して待ってるから、一緒に分け合おうって話だ！もちろん、だいたいはアイギスが作ったんだけどな。アイギスの料理は本当に美味しくて、厨房のおばさんたちも彼女には才能があるって褒めているくらいなんだぞ。お前も来ないと、きっと後悔するからな。\n\nお前の仲間、ジェンキンとブラウンより"
  },
  Mail_21466_Name = {
    Text = "親愛なる西区のヤツへ……"
  },
  Mail_21466_Sender = {
    Text = "ジェンキン"
  },
  Mail_21467_Desc = {
    Text = "守秘者へ：\n\n人々がまだ神の国に住んでいたころから、私たちはすでにダンスで感情を表現していたの——\n歓喜に満ちた旋回、悲嘆を刻む足取り……\nある人は、ダンスの歴史は人類の歴史と同じくらい長いと言ったわ。\nダンスは私たちの栄光と衰退を見届けてきたの。\n\n私はかつて、もう踊らないと誓った。\nでも……私はダンスのために生まれてきた存在。\nだから、今日だけで構わない。\n私と一緒に踊ってくれる？\nこのひとときを共に過ごして、身体の奥深くから湧き上がる律動を感じてほしい。\n\nダンスホールで待っているわ。\n\nリッツより"
  },
  Mail_21467_Name = {
    Text = "ダンスのご招待"
  },
  Mail_21467_Sender = {Text = "リッツ"},
  Mail_21468_Desc = {
    Text = "敬愛なる守秘者へ：\n\n俺が覚醒体になる前は、誕生日はいつも戦友たちと軍の営舎の外から酒を持ち込んで、物資が積まれたテントに隠れて、配給された黒パンをかじりながらこっそり祝ったものだ。\nそして、長官に見つかる前に瓶を外の草むらへ投げ捨てるんだ。\n\nだが、このミサゴ大学は軍隊ではない。\nこの場所では思う存分楽しむことができる。\nもしよければ、うまい酒を一緒に飲んで、俺の誕生日を一緒に祝ってくれないだろうか。\n\nもしその気になったなら、今晩、月が鐘楼を越える時間に宿舎の屋上へ来てくれ。\n気付いているかどうかわからないが、あそこの眺めはミサゴ大学の中で最も素晴らしい景色なんだ。\n\nアルバより"
  },
  Mail_21468_Name = {
    Text = "美酒を分かち合おう……"
  },
  Mail_21468_Sender = {Text = "アルバ"},
  Mail_21469_Desc = {
    Text = "ビーチビーチビーチビーチ〜！\n\nあれ？お手紙って、さいしょに宛先を書かなきゃいけないんだっけ？\nもう、めんどくさーい！\n守秘者だって、冷蔵庫に貼るメモには宛先なんて書いてないじゃん！\n\n今日はね、オレッタの……えっと……何歳の誕生日だっけ？\nまあいいや、とにかくオレッタの誕生日なの！\n\nこれね、オレッタの宝物！ぜ〜んぶあげる！\nだからオレッタを海に連れてって、おねがいおねがいおねがーい！\nね、ね、これでオレッタへの誕生日プレゼントってことにしてよ、いいでしょ〜？\n\nオレッタ"
  },
  Mail_21469_Name = {
    Text = "ビーチ！"
  },
  Mail_21469_Sender = {
    Text = "オレッタ"
  },
  Mail_21470_Desc = {
    Text = "私の恩人へ\n\nかつて荒れた星にいた頃、私は姉さまといつも抱き合い、同じ植物からエネルギーを吸い取りながら、それを自分たちの誕生の印としていました。\nあの日々は決して楽ではありませんでしたが、今振り返ってみると、やはり胸に湧いてくるのは喜びと、そして温もりです。\n今日は、私たちが生まれたことを祝う記念の日。もし許されるのなら、1曲の歌と引き換えに、1本の枝をいただくことはできませんか？\n私たち姉妹の過去の象徴、そしてあなたとの未来を象徴する。\nそんな1本の枝を……\n\nティンクト"
  },
  Mail_21470_Name = {
    Text = "誕生日の歌"
  },
  Mail_21470_Sender = {
    Text = "ティンクト"
  },
  Mail_21471_Desc = {
    Text = "ミサゴ大学の守秘者、聡明なる主君へ\n\nご健勝のことと存じます。\n先日、学校の厩舎に荷車が出入りしているのを見かけ、温血種の仔馬が届けられたと知りました。\n以前、主君と調査任務に当たった折、馬に乗った経験がないとおっしゃっていたのを思い出しました。\n温血種の仔馬は気性が穏やかで、初めての乗馬には最適です。\n馬に乗り、夜明けと夕暮れを追いかける——\nそれは僕の記憶に刻まれた、最も満ち足りたひとときです。\nご都合がよろしければ、ぜひ主君とともに、この喜びを分かち合えればと思います。\n\nオジール"
  },
  Mail_21471_Name = {
    Text = "温血種の仔馬……"
  },
  Mail_21471_Sender = {
    Text = "オジール"
  },
  Mail_21472_Desc = {
    Text = "旧国の暦は、ロンディニウムの今日の習慣とは大きく異なる。\n私は第二の夏の月の第五の満星の日に生まれたのだが、今日祝うことにしたのは、実験室の責任者が測定した結果だ。\n旧国がまだ存在していた時、祭司がすべてを取り仕切っていた。盛大な祭りの後は国全体が祝福し、7日間の休日に入った。\n求めたわけではないが、喜びの浸透を阻む理由もない。\n今日はミサゴの公休日ではないし、守秘者の職務自体が規則正しい休日を提供しないだろう。\nだが、私の誕生日を理由に休暇を申請すれば、管理部も反対はしないだろう。\nゆったりとした午後を過ごそう。\n\nトゥルー"
  },
  Mail_21472_Name = {
    Text = "生誕……"
  },
  Mail_21472_Sender = {
    Text = "トゥルー"
  },
  Mail_21473_Desc = {
    Text = "守秘者：\n\nオレッタによると、誕生日は願いをかけるものらしいです。\nそして私は、実は願い事をしない人間です。\nなぜなら私の考えは常に実現するからです。\nそれは幸運ではなく、むしろ運命の導きのようなものです。\n\n先月、シレストと海に出た際、またも「偶然」に美しい化石を拾いました。\n地元の住民たちはそれを「ウミユリ」と呼んでいました。\n\nその触手はまるで風車のように水面に向かい、夏の午後の日光を楽しんでいます。\n儚くも美しい。その姿を見た時、自然とあなたの姿が浮かびました。\n\n今回もまだ願い事をしていません——\nきっとあなたも喜んでくれるでしょう？\n\nサンガー"
  },
  Mail_21473_Name = {
    Text = "ウミユリ……"
  },
  Mail_21473_Sender = {
    Text = "サンガー"
  },
  Mail_21475_Desc = {
    Text = "守秘者へ\n\nエルトンと航海していたころ、彼は毎年この日になるとテーブルいっぱいの料理を作って「なにか願いごとはあるか」と言っていたわ。\n\nここへ来る前の私は「願い」とは何かを理解していなかった。\nそして今は、自分がどんな「願い」を持っているのか、わからない……\n\n「願い」を見つけることそのものを、「願い」にしてもいいの？\n\nシレスト"
  },
  Mail_21475_Name = {
    Text = "願い……"
  },
  Mail_21475_Sender = {
    Text = "シレスト"
  },
  Mail_21476_Desc = {
    Text = "守秘者へ\n\nオレッタから聞きました。\nあなたは、誕生日に願ったことをすべて叶えてくれるのだとか……本当ですか？\nさすがに、そんなことはありませんよね。\nみんなの願いを全部叶えるなんて、あまりにも大変すぎますから。\nでも、もしも願いが叶うなら……私は、ティンクトにもっと広い舞台が与えられたらいいな、と思います。\n難しいでしょうか？\nうぅ……で、では代わりに、「これから1年間、私の食卓にセロリが並びませんように」という願いなら、お願いしてもいいでしょうか？\n\nファイント"
  },
  Mail_21476_Name = {
    Text = "願い……"
  },
  Mail_21476_Sender = {
    Text = "ファイント"
  },
  Mail_21477_Desc = {
    Text = "親愛なる守秘者へ\n\nひとつ秘密を教えてあげる。\nこの誕生日、実は偽物なの。\n本当の生まれた日は……風に乗せて、消してしまいましょうね。\n\n病気になってから、お兄様は誕生日のたびに、執事にこっそり小さなケーキを用意させてくれたわ。\n誕生日の歌もなく、お祝いの言葉もなく、まるで誕生日を祝うことが、恥ずべきことであるかのように。\n\nでも今は、何もかもが違うの。\n私は陽の光のなかを歩けるし、声を上げて歌えるし、誕生日だって祝える。\n\nほんのささやかな喜びだけれど、なんだか懐かしくて、胸が温かくなるの。\nありがとう、守秘者。\n\n(もちろん、あなたもみんなも、私にもっと乱暴に、もっともっと乱暴に接してくれたら……完璧なのだけど)\n\nレーア"
  },
  Mail_21477_Name = {
    Text = "秘密......"
  },
  Mail_21477_Sender = {Text = "レーア"},
  Mail_21478_Desc = {
    Text = "あたしのど・れ・いたち：\n\n鞭を振るわなくなってずっと長い時間が経ったわ——\n退屈な学校に囚われて、制服に閉じ込められて、パンディアの心はくすぐったくてたまらないの。まるで、いたずらな子猫に中から引っかかれているみたい。\n誰もあたしを理解してくれない。職員たちは「楽しみ」を邪魔ばかりするの——本当にひどい話よね！\n今日は特別な日だから、鞭で柔らかい肌に触れて、痛みの歌声を、もう一度聞かせて……もし暇なら、あたしとおしゃべりでもしていかない？\n\nパンディア"
  },
  Mail_21478_Name = {Text = "鞭の音"},
  Mail_21478_Sender = {
    Text = "パンディア"
  },
  Mail_21479_Desc = {
    Text = "<Big:マジックの巨匠カーシアの周年記念公演、本日限定！>\n\n長年にわたるご支援とご声援への感謝を込めて、そしてこれまで皆さまからいただいた数々の歓声へのお返しとして、マジックの巨匠カーシアは今夜8時にミサゴ大学の中庭（フィリップス像の横）にて特別周年記念公演を開催いたします！\n\n今夜、あなたが目にするのは、これまで以上に華やかなステージ、よりスリリングな演出、そして——\n何よりも重要なのは、あなた自身の目を疑ってしまうほど神秘に満ちた、絢爛豪華な魔法の数々！\n\nたとえドー……ミサゴ大学の脳が直々にご来場されたとしても、この想像を超える魔法にはきっと魅了されることでしょう。\nこれは巨匠カーシアが保証します！\n\nまたとない機会、今夜限り、しかも入場無料！\n巨匠カーシアと、今夜お会いしましょう！\n\n<Small:※公演中または公演後に精神的な倦怠感や気分の落ち込み等の症状が現れた場合、カーシアは一切の責任を負いません>\n<Small:※ミサゴ大学の脳に関するいかなる宣伝内容も、当日の実際の状況を優先とします。公演内容およびその効果に関する最終的な解釈は、すべてカーシアに帰属します>"
  },
  Mail_21479_Name = {
    Text = "マジックの巨匠カーシアの周年記念公演！"
  },
  Mail_21479_Sender = {
    Text = "カーシア"
  },
  Mail_21480_Desc = {
    Text = "お～い。\n今日はあたしの誕生日よ、贈り物は？\n何よ？用意してないの……？\nふん、そんなことだろうと思ったわ。\n\nほら、このカレンダーを持っていきなさい！\nあたしの誕生日に、命日でしょ……\nミサゴに来た記念日と、新年祭に、農神祭！\n日付をちゃんと書いたわよ。\n祭りの日は一緒に過ごすんだから、次は忘れないでよね！\n\nもしまた忘れたら……まあ、お前のことだし、どうしようもないか。ふん。\nとにかく絶対に忘れちゃだめよ。\n\nアグリッパ"
  },
  Mail_21480_Name = {
    Text = "おーい……"
  },
  Mail_21480_Sender = {
    Text = "アグリッパ"
  },
  Mail_21481_Desc = {
    Text = "守秘者へ：\n\n本来ならこの手紙を書くつもりはなかったわ。\nエリカの稼働に不具合が生じているの。\nこの手紙を書いている今も、彼女の警報が鳴り止まないわ。\n\nわたしにとって誕生日は何の意味もない、ただの日付。\n実験の成功率は他の日と変わらないし、霊性指数も日付によって変わったりしないわ。\nただ、ラモンナはこの日をわたしの「休息日」にするといってるの。\n実験室への立ち入りも制限されたわ。\n\n行くところもないから、あなたの過去の報告書を全面的に精査することに決めたわ。\n\n夕食後に資料室に来なさい。\nただし、いかなるケーキも資料室へ持ち込まないよう注意を。\n紙の資料は非常に脆いの。\n\nドール"
  },
  Mail_21481_Name = {
    Text = "夕食後……"
  },
  Mail_21481_Sender = {Text = "ドール"},
  Mail_22435_Desc = {
    Text = "親愛なる守秘者様へ：\nはじめに朝靄のほの明るい大学の中庭で詩を読むことを選んだのは、この時間帯は行き交う人が少なく、詩の世界にいっそう没入できると思ったからでした。\nしかしその後、私は次第に、夜明け前のかすかな空の色、きらきらと透き通る露、そして澄んでやわらかな鳥のさえずりをも愛するようになりました。\n\n思いがけなかったのは、私をひそかに見守ってくれていた先生や学生方がたくさんおられて、私の知らぬところで詩を愛する仲間の会まで作っていたことです。\n本日は私の誕生日で、ちょうど同好会の水仙がつぼみをほころばせようとしています。\nれをきっかけに、彼らは詩の鑑賞会を開き、中庭で景色を愛でながら一緒に詩を読むつもりだそうです。\n\nこの情景の中、どうかあなた様も来て、共に味わってくださればと願っております。 \n\nニムフィーア"
  },
  Mail_22435_Name = {
    Text = "詩の朗読会の招待"
  },
  Mail_22435_Sender = {
    Text = "ニムフィーア"
  },
  Mail_23897_Desc = {
    Text = "敬愛なる守秘者：\n\nV1.0.21の更新では以下を調整しました。\n・「調査」高難度、「意識潜行」戦闘ステージの通常と高難度\n・「闇の境界」の各界域の輪番隙間ⅠⅣの各ステージの初回クリア報酬\n詳細は「V1.0.21オンラインメンテナンス告知」をご覧ください。\n\n以前の調査および挑戦のクリア記録に基づき、調整後の報酬を一度にお送りします。詳しくは添付ファイルをご参照ください。"
  },
  Mail_23897_Name = {
    Text = "V1.0.21調整補償"
  },
  Mail_23897_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_24199_Desc = {
    Text = "敬愛なる守秘者：\n        V1.0.24の更新で、V1.0.16で一時閉鎖された「調査」第5章を再開しました。公平を期すため、調整前後の報酬の変化と各守秘者の調査記録に基づき、相応の補償を行います。あなたの補償は添付ファイルに送付されました。"
  },
  Mail_24199_Name = {
