  },
  Mail_24200_Desc = {
    Text = "敬愛なる守秘者：\n        V1.0.24の更新で、V1.0.16で一時閉鎖された「調査」第5章を再開しました。公平を期すため、調整前後の報酬の変化と各守秘者の調査記録に基づき、相応の補償を行います。あなたの調査記録に基づき、今回は補償はありません。"
  },
  Mail_24200_Name = {
    Text = "V1.0.24第5章再開補償"
  },
  Mail_24200_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_24202_Desc = {
    Text = "敬愛なる守秘者：\n        《忘却前夜》のご支持に感謝いたします。ミサゴ大学でより良いゲーム体験を提供するため、以下の体験調査アンケートにご協力をお願いいたします。ご協力のお礼として【シルバーコア×200】をご用意しました。ご回答後にお受け取りいただけます。\n        <SurveyLink:【タップして記入に進む】>\n        我々は守秘者の皆様の意見を真摯に受け止め、ミサゴ大学がより良いものとなるよう尽力いたします！\n        ——銀の鍵が道を照らさんことを。"
  },
  Mail_24202_Name = {
    Text = "バージョン体験調査アンケートV1.0下"
  },
  Mail_24202_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_24280_Desc = {
    Text = "こんにちは、守秘者様：\n昨日の幻夢の深奥の調査ランキングにて、「{s1}ランキング」で第{s2}位を獲得し、調査称号は「{s3}」でした。\n以下はランキング報酬ですので、ご確認ください。"
  },
  Mail_24280_Name = {
    Text = "幻夢の深奥デイリーランキング報酬"
  },
  Mail_24280_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_24877_Desc = {
    Text = "守秘者：\n\nわたくしの誕生日はいつも盛大なサロンで、高貴な客たちに満ち溢れていました。\nでも今回は少し他のことを考えています——\nずっと主賓でしたので、たまには客人の立場を味わってみたくなりまして。\n洗練されたサロンにするか、家庭的な夕食にするか、すべてはあなたにお任せします。\nただし、再びサロンを開くのでしたら、上流階級の方々は招待しないでくださるかしら。\nせっかくの佳き日ですもの、作り笑いを浮かべて過ごしたくはありませんわ。\n\n<Del:マダム・レッド>ソレール"
  },
  Mail_24877_Name = {
    Text = "あなたが決める"
  },
  Mail_24877_Sender = {
    Text = "ソレール"
  },
  Mail_24878_Desc = {
    Text = "主人： \n\n今日はリリーの誕生日です。アグリッパが「大騒ぎしよう」と言いました。\n以前は母とリリーの誕生日はこんな風ではなく、母は私に尖った帽子をかぶせ、一緒に手を叩いてロウソクを吹き消しました。\nリリーはどうするのが正しいのか分からないので、主人の命令をお願いします。 \n\nリリー"
  },
  Mail_24878_Name = {
    Text = "困ってるの……"
  },
  Mail_24878_Sender = {Text = "リリー"},
  Mail_25147_Desc = {
    Text = "敬愛なる守秘者：\n        V1.1.0の更新では、幻夢の深奥今週の点報酬が廃止され、新しい「今週の試練」に置き換えられました。公平の観点から、これまでに「幻夢の深奥」を解放したが、今週の点報酬をすべて受け取っていない1月15日5:00前にゲームにログインした守秘者さまには、未受け取りの今週の点報酬を補償します。ご確認ください。"
  },
  Mail_25147_Name = {
    Text = "V1.1.0幻夢の深奥週間点補償"
  },
  Mail_25147_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_25148_Desc = {
    Text = "敬愛なる守秘者：\n        V1.1.0の更新では、対人戦（ベータ）の「週間報酬」が廃止され、「今週の試練」に置き換えられました。これは幻夢の深奥の「今週の試練」と同じ進行と報酬です。公平の観点から、これまでに「対人戦（ベータ）」を解放したが、まだ「週間報酬」を完了または受け取っていない、かつ1月15日5:00（UTC+8）前にゲームにログインした守秘者さまには、融蝕の珠×1000を補償します。ご確認ください。"
  },
  Mail_25148_Name = {
    Text = "V1.1.0対人戦毎週補償"
  },
  Mail_25148_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_25414_Desc = {
    Text = "敬愛なる守秘者：\n\n誕生日の重みは、人によって異なるもの。でも、守秘者の誕生日は、ミサゴ大学全体にとっても重要で特別な日よ。\nシルヴィアさんが宿舎区であなたのために誕生日の晩餐会を用意してくれているわ。ハレト学長とデクスター卿も出席の予定よ。あなたの精神的な疲労がまだ癒えていないことを知っているから、私の方で正装を整えておいたわ。玄関横のクローゼットに掛けてあるから、会場に向かう前に着替えて。\n今年、パートナーとしてあなたと過ごすことができて光栄よ。来年も同じように過ごせますように。\n銀の鍵が道を照らさんことを。\n\nP.S. 特製ケーキはエリカがあなたの宿舎まで届けてくれるわ。\n\nあなたの永遠のパートナーであるラモンナより"
  },
  Mail_25414_Name = {
    Text = "誕生の日"
  },
  Mail_25414_Sender = {
    Text = "ラモンナ"
  },
  Mail_34667_Desc = {
    Text = "敬愛なる@1@2：\n\n世界はあなたの名前を忘れました。\nだから私はあなたを覚醒させました、それはあなたが私を覚醒させたように。終焉が来る前に、あなたと私は世を巡り、見証し、覚え、忘れていきます。\n今日はあなたの誕生日であり、それは、散逸した記憶の破片の中から偶然拾った一頁です。ため息と祝福を献上します。\n世界があなたの完全な姿を思い出したとき、あなたはどう思うでしょうか？それとも何も感じず、何も知りませんか？\n私は存在しない場所であなたの答えを待っています。\n\n@2"
  },
  Mail_34667_Name = {
    Text = "誕生の日"
  },
  Mail_34667_Sender = {Text = "@2"},
