  Mail_36865_Desc = {
    Text = "敬愛なる守秘者：\n        V1.2.4の更新において、「幻夢の深奥」今週の試練の報酬が調整され、「融蝕の珠」「擬態凝晶」と「薔薇金券」の報酬が削除されました。公正を期すため、更新前に「幻夢の深奥」を解放し、すべての報酬を受け取っていない守秘者には、3月11日5:00までログインした方に、未受領の「融蝕の珠」「擬態凝晶」と「薔薇金券」を補償いたします。ご確認ください。"
  },
  Mail_36865_Name = {
    Text = "V1.2.4毎今週の試練調整報酬補償"
  },
  Mail_36865_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_36866_Desc = {
    Text = "敬愛なる守秘者：\n        V1.2.4の更新において、意識潜行「血と砂」「歪みの核」「騎士の願い」普通モードに新しいキーオーダー「咆哮する血と砂」「儚き永遠」「最後の誓い」が追加されました。\n\n更新前にこれらの普通モードをクリアした守秘者には、対応するキーオーダーが補填されますので、ご確認ください。"
  },
  Mail_36866_Name = {
    Text = "V1.2.4意識潜行キーオーダー補填"
  },
  Mail_36866_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_36867_Desc = {
    Text = "敬愛なる守秘者：\n        V1.2.4の更新で、「超越存在」からの独自スキル強化素材と擬態凝晶のドロップ数が増加しました。\n\n公平を期すため、更新前に週次「超越存在」報酬を受け取った守秘者には、受け取った報酬のステージ推奨レベルに基づき、増加したドロップと同等の価値の「擬態凝晶」を補償します。ご確認ください。"
