  },
  Mail_39548_Desc = {
    Text = "親愛なる守秘者様：\n\n永遠の命にとって、誕生日を祝うことは必要ないように思えます。無限の時間の流れと比べて、あなたたち人間が忘れられないとか素晴らしいと呼ぶ記憶は、少し…取るに足らないものです。\nしかし、あなたたちはこれらの「取るに足らない」ことを記念するために無数の祝日や祭りを発明しました。もちろん、これも人間が私の興味を引く理由の一つです。あなたたちは本当に可愛らしいです。\nでも、あなたとの出会いはこれらの「取るに足らない」瞬間には含まれません。なぜなら、あなたは他の人とは違うからです…そしてこの「違い」が未来にどんな嵐を巻き起こすのか、私はとても楽しみにしています。\nさて、私のおしゃべりを許してください…今日は私の誕生日なので、「誕生日の権利」を行使させてください。\nあなたにしてほしいことは、しーっ…焦らないで、答えは私の寝室にあります。今夜の真夜中に一人で来てください。\n\nワンダ"
  },
  Mail_39548_Name = {
    Text = "誕生日の権利"
  },
  Mail_39548_Sender = {Text = "ワンダ"},
  Mail_39549_Desc = {
    Text = "今日はわたくし、マーフィー様の誕生日よ——誕生日には、やっぱりパーティーとお祝いが必要よね！\n管理部の連中もなかなかやるじゃない。でもあいつら、芝居が下手すぎよ、もうバレバレ——わたくし見ちゃったの。覚醒学部の倉庫にケーキの飾りを運んでいるのを。\nあのね……その職員たちを罰したりしないわよね？か、彼らは本当にすごく頑張ってたの。ただサプライズを隠しきれなかっただけで……\nここまでにしておくわ。誰か、わたくしを呼んでいるみたい——あいつら、バカみたいな安っぽい色紙の飾りでわたくしを飾ったりするのかしら。\nあ、それと、ケーキを切るときは、お前もいるのよね？\n\nマーフィー"
  },
  Mail_39549_Name = {
    Text = "誕生日パーティー……"
  },
  Mail_39549_Sender = {
    Text = "マーフィー"
  },
  Mail_43571_Desc = {
    Text = "敬愛なる守秘者：\n        V1.2.10の更新において、「霧都紀行」イベントの以下の項目に報酬「シルバーコア」×1000が追加されました。\n・【調査メインストーリー第1章「東区の秘め事」高難度】\n・【調査メインストーリー第2章「蝋人形の名において」高難度】\n\n更新前にこれらの報酬を受け取った守秘者には、対応するシルバーコアが補填されますので、ご確認ください。"
  },
  Mail_43571_Name = {
