  Mail_44571_Desc = {
    Text = "敬愛なる守秘者：\n「霊魂の牧人」イベントは4月18日15:00に終了します。イベント終了後、対応するイベント入口は閉鎖されます。聖堂の道、聖堂チャリティ会場など、期限切れのチャリティ券は自動的に消失します。イベント終了前に聖堂チャリティ会場で商品を購入することを忘れないでください。"
