    Text = "幻夢の深奥代理ランキング報酬"
  },
  Mail_44690_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_44831_Desc = {
    Text = "敬愛なる守秘者：\n        V1.3.0の更新において、特務記録「雨の町に潜む影」「薔薇の讃歌」「物語の魔法」普通モードに新しいキーオーダー「灰霧の正体」「薔薇の勝利」「真夏の夜の夢」が追加されました。更新前にこれらの普通モードをクリアした守秘者には、対応するキーオーダーを補填いたしますので、ご確認ください。"
  },
  Mail_44831_Name = {
    Text = "V1.3.0特務記録キーオーダー補填"
  },
  Mail_44831_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_44836_Desc = {
    Text = "敬愛なる守秘者：\n        V1.3.0の更新において、「幻夢の深奥」今週の試練1勝、3勝の報酬として「代理証明」×1が追加されました。\n\n更新前にこれらの報酬を受け取った守秘者には、対応する「代理証明」を補填しますので、ご確認ください。"
  },
  Mail_44836_Name = {
    Text = "V1.3.0今週の試練報酬補填"
  },
  Mail_44836_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_44837_Desc = {
    Text = "敬愛する蒼白の使者へ\n\n今日、子供たちが花束と菓子を持ってきてくれました。\nそれで思い出したのですが、洪積暦より100余年前の今日、私は父なる神の恩賜を受け、この世に生を受けました。\nどれほど遠い昔のことでしょう。\n幼少期の記憶はすでに霞んでしまいましたが、ボンドス教会に漂っていた香の薫りだけは今も脳裏を漂い、消えることがありません。\n今でも教会は残っているかもしれませんが、香の配合はもう当時のものとは違うでしょう。\n\nすみません、感傷に浸るために手紙を書いたわけではありません。\n子供たちが持ってきてくれた菓子でお茶の席を設けました。\nぜひ来て、ご一緒していただけませんか——\n私の誕生日を祝うためではなく、命あることを祝うために、そして存在していてほしいと願う、あらゆる日々を祝うために。\n\nあなたの誕生日はいつですか？\nぜひお茶を片手にお聞かせいただければ。\n\nサルバドル"
  },
  Mail_44837_Name = {
    Text = "蒼白の使者……"
  },
  Mail_44837_Sender = {
    Text = "サルバドル"
  },
  Mail_44843_Desc = {
    Text = "敬愛なる守秘者：\n        V1.3.0の更新において、「核心課題」特権：幻夢の深奥と対人戦（ベータ）での守秘者経験値倍増を削除しました。謝罪の意を込めて、現在の学期課題の終了まで、本期の「核心課題」を購入いただいた守秘者には1日「守秘者経験値」×240を補償いたします。ご確認ください。"
  },
  Mail_44843_Name = {
    Text = "V1.3.0核心課題報酬補填"
  },
  Mail_44843_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_47305_Desc = {
    Text = "敬愛なる守秘者：\n昨日の幻夢の深奥にて、最高難易度「{s1}」をクリアしました。\n昨日の対人戦にて「{s2}」の称号を獲得しました。\n対人戦での勝利はありませんでした。\n以上の成績に基づき、以下の「融蝕の珠」を獲得しました。\nお受け取りください。"
