  },
  Mail_47307_Desc = {
    Text = "敬愛なる守秘者：\n昨日の幻夢の深奥にて、あなたは「{s1}」の称号を獲得しました。\n昨日の対人戦で、あなたは「{s2}」の称号を獲得し、対人戦勝利を収めました。\n\n以上の挑戦成績を総合し、以下の追加報酬を獲得しましたので、ご確認ください。"
