  },
  Mail_47308_Desc = {
    Text = "敬愛なる守秘者：\n昨日の幻夢の深奥にて、最高難易度「{s1}」をクリアしました。\n昨日の対人戦にて「{s2}」の称号を獲得し、勝利しました。\n\n以上の成績に基づき、以下の「融蝕の珠」を獲得しました。\nお受け取りください。"
  },
  Mail_47308_Name = {
    Text = "深奥対人戦　「融蝕の珠」報酬"
  },
  Mail_47308_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_48005_Desc = {
    Text = "親愛なる守秘者様：\n\n突然のお手紙、私の拙い筆跡でご機嫌を損ねないことを願います。書くのが得意ではなくて……\nこの手紙を書くのは、今日が私の誕生日のようだからです。そのために少しクッキーを焼きましたので、ぜひお試しください。\n正直、この日付が正しいかはわかりません。融蝕感染後、私の存在の痕跡が少しずつ消えていきます。ドールさんが、皆に忘れられるのを見つめるのはどんな感じかを尋ねたことがあります。\n説明が難しい…まるで真っ暗な中、輝く川の縁に立っているようなものです。人々は川の向こう側で話し、お互いに忙しく、私の前を通り過ぎていきます。私は彼らを見つめることしかできず、一言も発することができません。\nそれはとても孤独な感覚です。でも幸運にも、あなたはその中に含まれていません。\n少なくとも、あなたは私の物語を覚えていますよね？\n\nまた、クッキー12枚を同封しました。\n\nメイソン"
  },
  Mail_48005_Name = {
    Text = "失礼します"
  },
  Mail_48145_Desc = {
    Text = "敬愛なる守秘者：\n「多重治療」イベントは終了しました。残りのイベント通貨「記憶パズル」を「人格解析」の無制限交換レートに基づき回収いたしましたので、ご確認ください。"
