  Mail_48914_Desc = {
    Text = "敬愛なる守秘者：\n        《忘却前夜》のご支持に感謝いたします。ミサゴ大学でより良いゲーム体験を提供するため、以下の体験調査アンケートにご協力をお願いいたします。ご協力のお礼として【シルバーコア×200】をご用意しました。ご回答後にお受け取りいただけます。アンケート締切は10月28日9:00です。ぜひお早めにご記入ください。\n        <SurveyLink:【タップして記入に進む】>\n        我々は守秘者の皆様の意見を真摯に受け止め、ミサゴ大学がより良いものとなるよう尽力いたします！\n         ——銀の鍵が道を照らさんことを。"
