  },
  Mail_50344_Desc = {
    Text = "小さな苗木：\n\n風が君の香りを運んできた、初めて会った時よりも甘く感じる。\n君は私の愛の中で育ち、その愛で成熟した…………蜂と蜜のように。\n今日は特別な日、会いに来てくれるかい？\n君の言う通り、長い間おとなしく待っていたよ…………そろそろご褒美をくれてもいいんじゃない？\n\nタイス"
