  Mail_51777_Desc = {
    Text = "敬愛なる守秘者：\n「物語の魔法・復刻」イベントは終了しました。\n\n残りの「揺蕩う閃き」をそれぞれ「薔薇金券×25」と交換しましたので、ご確認ください。"
