  },
  Mail_53149_Desc = {
    Text = "余生をあの方に捧げることを決めました……愚かな行いの贖罪として。\n浅薄な身の「誕生日」は取るに足りません。\n今日も過去も未来も変わらず、礼拝堂に向かいます。\nしかし、もし今日礼拝堂を離れるように望まれるなら、ミサゴの客として、主人の意志に逆らうことはありません。\nもし、私の祈りを見届けたいなら、いつでも歓迎します……恐れ多くも、心からお待ちしております。\n\nミリアム"
  },
