    Text = "ミサゴ校委員会"
  },
  Mail_56101_Desc = {
    Text = "守秘者さんへ\n\n今朝早く、早春の鳥のさえずりの中で、一輪の薔薇がほころびました。\nそれは本来、まだ蕾のままであるはずの春の枝でしたが、聖人の日、そして、わたくしが生まれたこの日に、季節違いの花として咲いたのです。\nわたくしはシディのことを思い出しました。\n毎年、誕生日のこの日になると、シディの街はいつも賑やかでした。\n花の開く音や、頬を赤らめるような情熱的な甘い言葉が、そこかしこに溢れていました。\nしかし、わたくしはもう長いあいだ、それらに触れる機会を失っていたのです……今日、この瞬間までは。\n守秘者さん、あなたは「偶然」を信じますか？\n思うに、偶然とはひとつの言語であり、薔薇とはその修辞のように思えます。\n今日、ミサゴ大学の入り組んだ庭園の中で、この薔薇は咲き誇り、その花弁は惜しげもなく開かれて……まるで、心を奪う詩のようです。\nだから、今日……一緒にこの薔薇の開花を見に来ていただけませんか？\nわたくしも、そして花も、あなたのお越しを心よりお待ちしています。\n\nオルラ"
  },
  Mail_56101_Name = {
    Text = "バラが春に咲く"
  },
  Mail_56101_Sender = {Text = "オルラ"},
  Mail_57328_Desc = {
    Text = "敬愛なる守秘者：\n「星辰の正位置」イベントは終了しました。\n\n残りの「無識の胚」、「無欲の胚」および「無我の胚」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_57328_Name = {
    Text = "胚胎回収"
  },
  Mail_57328_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_57414_Desc = {
    Text = "敬愛なる守秘者：\n「名探偵マニュアル」イベントは終了しました。\n\n残りの「勝負チップ」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_57414_Name = {
