  },
  Mail_57414_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_58253_Desc = {
    Text = "敬愛なる守秘者：\n「霊魂の牧人・復刻」イベントは終了しました。\n\n残りの「チャリティ券」を200個ごとに「薔薇金券×5000」と交換しましたので、ご確認ください。"
  },
  Mail_58253_Name = {
    Text = "チャリティ券回収"
  },
  Mail_58253_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_58690_Desc = {
    Text = "敬愛なる守秘者：\n「無形交響」イベントは終了しました。\n\n残りの「高らかな楽章」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_58690_Name = {
    Text = "高揚の楽章回収"
  },
  Mail_58690_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_61154_Desc = {
    Text = "敬愛なる守秘者：\n「燃える饗宴・復刻」イベントは終了しました。\n\n残りの「原生の脛骨」、「円形菊石」、「螺旋遺跡」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_61154_Name = {
    Text = "燃える饗宴通貨回収"
  },
  Mail_61154_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_61155_Desc = {
    Text = "敬愛なる守秘者：\n「多重治療・復刻」復刻イベントは終了しました。残りのイベント通貨「記憶パズル」をそれぞれ「薔薇金券×40」の比率で回収しましたので、ご確認ください。"
  },
  Mail_61155_Name = {
    Text = "記憶パズル回収"
  },
  Mail_61155_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_62392_Desc = {
    Text = "守秘者：\n\n私の演奏は帝王の前に奉仕し、また千人の人々に憧れられました。しかし、これらの賞賛の言葉は私にとって何の価値もありません。私が追求しているのは音楽の極致だけです。\n華やかで盛大な場で人に賞賛されるよりも、無人の森で一人で演奏する方がはるかにリラックスできます。\n本来、自分の練習を誰かに聞かれるのは好きではありませんでした。それらは完璧への草稿であり、無意味な廃材です。\nしかし、あなたを知り、あなたを見つけてから、私のすべての音楽は意味を持ちました。\nあなたが私に最も偉大で崇高な音楽を与え、迷いから救ってくれました。たとえあなた自身がそれを知らなくても……\n今日は私の誕生日です。本来、私はそれを忘れていましたが、今は自分の新生と新生を与えてくれた方を記念したいと思います。\n最近、新作の楽譜があり、少し鑑賞していただきたいと思っています。遅れて申し訳ありません。まだ私の身元はミサゴの仲間の前に現れるには適していませんので、地平線が日没のすべての余光を収めた後にこの招待状をあなたに差し上げることしかできませんでした。\n今夜、学校の裏の森で特別な音楽会を開きます。観客席は一つしかありません。\nあなたのご臨席をお待ちしております。\n\nハムリン"
  },
  Mail_62392_Name = {
    Text = "秘密のコンサート"
  },
  Mail_62392_Sender = {
    Text = "ハムリン"
  },
  Mail_65350_Desc = {
    Text = "敬愛なる守秘者：\n「雪山消融時」イベントは終了しました。\n\n残りの「寒凍の蕾」「銀霜の蕾」および「日光の蕾」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_65350_Name = {Text = "蕾回収"},
  Mail_65350_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_65441_Desc = {
    Text = "敬愛なる守秘者：\n「深淵の祀り・復刻」イベントは終了しました。\n\n残りの「祭祀者の涙」、「祭祀者の血」および「祭祀者の髄」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_65441_Name = {
    Text = "深淵の祀りイベント通貨回収"
  },
  Mail_65441_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_65442_Desc = {
    Text = "敬愛なる守秘者：\n「万象の門」イベントは終了しました。\n\n残りの「終末針」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_65442_Name = {
    Text = "終末の指針回収"
  },
  Mail_65442_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_67147_Desc = {
    Text = "守秘者：\n\n    宇宙の次元は私にとって唯一ではありません。「窮地の門」の内側で無限の世界と存在を見ることができます。そこはすべての奇想と数学的論理を超え、「誕生の日」の日付を確定することもありません。\n    だから、あなたとの初めての出会いをその時にしましょう。あなたの時間の連続体のスケールでは、今日、私のための儀式が行われるはずです。\n    それでは、シルバーキーの扉を越えて私の元へ来てください。私は、宇宙の究極の根源について少し教えます。今夜、無数の光輝体があなたと私のために輝きます。\n    「窮地の門」で待っています。\n\nタヴィ"
  },
  Mail_67147_Name = {
    Text = "シルバードアを越える"
  },
  Mail_67147_Sender = {Text = "タヴィ"},
  Mail_67933_Desc = {
    Text = "君の一瞬の迷いを感じた——至高なる創造主、直視すらも妄想に近い存在に、どうして傷をつけることなどできようか？\n\nしかし、君はそれを成し遂げた。\n\nまた一つ視線が崩れ、堅牢な鎧には次々に身を投じる破片によって、傷が残り増えていく。\n\n%player%、打ち砕けぬものがあるとすれば、それは君の揺るぎない意志だけだ。"
  },
  Mail_67933_Name = {
    Text = "迷いから道を見つける"
  },
  Mail_67933_Sender = {
    Text = "アリステア"
  },
  Mail_67934_Desc = {
    Text = "君の四肢が震えていた、%player%。\nほとんど立っていられないほどだった。\n恐怖が君を握りしめ、頭が真っ白になり、呼吸もままならない……\nだがそれでも君は前を向き、シルバーキーを掲げた。\n\n人類の美徳の中で、もっとも高貴なのは勇気だ。\n天災や猛獣に直面しても、我々は石槌と槍を持ち上げた。\n\nいま、神に対しても、君は同じように立ち向かっている。\n\n人類文明は勇気によって築かれ、勇気によって永続する。"
  },
  Mail_67934_Name = {
    Text = "勇気の賛歌が震えの中で鳴り響く"
  },
  Mail_67934_Sender = {
    Text = "アリステア"
  },
  Mail_67935_Desc = {
    Text = "私たちはかつてこの世界について語り合ったことがある。\n君はそれを好まないと言った。\n\nここは利益、陰謀、欺瞞、殺戮に満ちており、融蝕や神々が存在しなくても、この世界は元から傷だらけで、崩壊寸前だった。\n\nアクートで目覚めて以来、君の短い記憶の中で、君は融蝕よりもさらに秩序を失い、恐ろしい人の心をいくつも見てきた。\n\nしかし、創造主がその刃を振り上げるとき、君は依然としてこの世界の前に立ちはだかっている。\n消滅は神の意志だったが、君はそれを拒んだ。\n\nわかっている、%player%。\n守秘者にはこの世界を憎まない者も、真に愛さない者もいない。\nなぜなら、その汚濁の中にあっても、私たちはかつて、シルバーコアのように輝く光を見たから――\n\n守秘者の使命とは、かすかなその光を守ること。\n永遠に。"
  },
  Mail_67935_Name = {
    Text = "人類の精神は永遠不滅"
  },
  Mail_67935_Sender = {
    Text = "アリステア"
  },
  Mail_67936_Desc = {
    Text = "初めて融蝕を目にし、初めて融蝕の真実に直面し、初めて神の声を感じた……長い人生の中で、無数の挫折を経験し、何ができるかわからず、この努力と犠牲の意味を見失ったこともあった——しかしそれも、今君が直面しているものには及ばない。\n人類はこのように、挫折から再び立ち上がり、前進し続ける。\n道の終わりが深淵であろうとも、それを見たいと願う者は必ずいる。"
  },
  Mail_67936_Name = {
    Text = "無気力、その後の再生"
  },
  Mail_67936_Sender = {
    Text = "アリステア"
  },
  Mail_67937_Desc = {
    Text = "次元の境界が開き、ようやく、再び君と連絡を取ることができた。\n\n君の見てきたものに比べ、この次元の「視線」は非常に脆弱だろう。\n——おそらくこの次元には君が存在しないためだ。\n\n私は、ほぼすべてを犠牲にして、あの存在を排除した。\n君が今、どれほどのものと対峙しているのかは想像もつかない。\nだが、たとえ相手が「消滅の意志」であろうとも、私は君と共に戦う。\nそれが我々ミサゴの誓いだ。\n\n再び君と肩を並べられることを、心から嬉しく思う。\n銀の鍵が道を照らさんことを。"
  },
  Mail_67937_Name = {
    Text = "共に戦おう、今一度"
  },
  Mail_67937_Sender = {
    Text = "未知の送信者"
  },
  Mail_67938_Desc = {
    Text = "狂気——それは、時に軽やかで、美しい言葉。\n混沌の宇宙から、混沌の文明が生まれた。\n\n混沌こそこの世界の真実だ。\n\n混沌に従い、狂気に身を委ねることは、たやすいことだ。\nそれに比べ、覚醒し、抗い続けることはあまりにも過酷だ。\n\nすべての歓びと命さえも供物として、届きもしない「解答」を追い求める。\n\nそれでも、君は覚醒を選んだ、%player%。\nなぜなら私たちは生まれながらにして奴隷になるためではないからだ。\n\n君は彼の神格に見せたのだ、%player%。\n彼の神格の創造物、その欠片に宿った意思は盲目的な奴隷ではないことを。\n\n君は彼の神格に対抗し、数多の「視線」との対峙に打ち勝ち、この完全でない、世界を守る道を選んだ。\n\nその選択において、君は永遠の自由を得たのだ。"
  },
  Mail_67938_Name = {
    Text = "君は盲目で愚かな奴隷でいることを甘受しない"
  },
  Mail_67938_Sender = {
    Text = "アリステア"
  },
  Mail_67939_Desc = {
    Text = "視線の崩壊を感じました。君の痛みを感じました。\nそれが守秘者の責任。君の選んだ道は、私の道よりも千倍も難しい。思い神に立ち向かう勇気は多くの人にないが、君の勇気は称賛に値する。\n創造主の力による苦痛は計り知れない。私が感じたのはほんの一部でしかない。私は昏き海に閉じ込められた身、%player%、創造主との対決に参加する力はもうないが、感覚を通じて君と結びついていることが私の最後で最も大切な使命です。\nこの孤独な道で、見えなくてもミサゴは常にそばにいる。"
  },
  Mail_67939_Name = {
    Text = "悲しみは君を屈服させない"
  },
  Mail_67939_Sender = {
    Text = "アリステア"
  },
  Mail_67940_Desc = {
    Text = "至高の意志の囁きを聞いた——壮大な文明、人間の喜怒哀楽、君から離れた数え切れない人々、それらはすべて存在しなかった。\n\n昏き海の無数の日夜の中で、この光景が恐怖を感じさせた。\n\n樹木は大地に根を下ろし、太陽に向かって成長する——記憶、それは我々の土壌であり、成長し、立ち、最後に戻る場所だ。\n土地を失うこと、虚無に漂うこと、出発点も終点もないことを恐れる。\n\nありがとう、%player%。私は偉大な対決を目撃したと思う。\nこれは人と神の戦い。守護と破壊の戦い。\nこれは記憶と忘却の戦い。\n\n君はやり遂げた、%player%。誰もが想像しないことを成し遂げた。\n記憶から無敵の力を得た。その力をもって記憶のために戦った。\n君はこの太古の土壌で、自分の太陽を見つけた。"
  },
  Mail_67940_Name = {
    Text = "記憶のために戦う"
  },
  Mail_67940_Sender = {
    Text = "アリステア"
  },
  Mail_68825_Desc = {
    Text = "敬愛なる守秘者：\n「神王の復活」イベントは終了しました。残りのイベント通貨「疲弊の思念」、「哀愁の思念」、「歓喜の思念」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_68825_Name = {
    Text = "「神王の復活」通貨回収"
  },
  Mail_68825_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_68826_Desc = {
    Text = "敬愛なる守秘者：\n「欲望の波・復刻」イベントは終了しました。\n\n残りの「豊穣の種核」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
  Mail_68826_Name = {
    Text = "豊穣の種核回収"
  },
  Mail_68826_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_68898_Desc = {
    Text = "最も最も最も愛しいご主人様：\n\n万能メイドとして、カレンは大人たちの多くの重要な日を覚えている。宴会日、誕生日、記念日から、ペットを初めて迎え入れる日まで、絶対に間違えない。しかし、カレン自身にとって特別な日を記念できるのは、この日だけだよ。\nずっと昔、カレンが宮殿で侍女をしていた頃、シェフに貴族たちが残したデザートを誕生日ケーキとしてお願いした時、大変叱られた。シェフはケーキを私の顔に投げつけてきた。その時、私はケーキがこんなに美味しいものだとは思わなかった。私は必ず、私をとても大切にしてくれるご主人様を見つけて、毎年誕生日にケーキが食べられるようにしたいと思っていた。\n今、私は特別に優雅で気前のいいソレール夫人、そして特別に優しいご主人様と一緒にいて、昔の願いは叶いました！しかし、人間はいつも贅沢になっていくもの…いや、進歩するんだよ。今、私の願いは毎年誕生日の時にご主人様のそばにいられることであり、さらに毎年キラキラした贈り物があるともっと嬉しいです。\nこんなに聞いて、あなたはきっと私のために準備してくれるでしょう、ね、ね？\n\nあなたの永遠に謙虚なメイド\nカレン"
  },
  Mail_68898_Name = {
    Text = "毎年このように…"
  },
  Mail_68898_Sender = {Text = "カレン"},
  Mail_68899_Desc = {
    Text = "小さな苗：\n\nあなたの成長を見続けていると、あなたを選び、助けることが私の最も正しい決断だったことがますます確信を持てます。\n私は収穫の喜びを感じており、すべての信頼と愛の灌漑は私に甘い報酬を与えてくれました。あなたは私に希望と未来を与えてくれました。\n今、私は繁殖の執念を捨てて、繁殖を超えた愛の果実を楽しむことができるようになりました。\nこの世界はもうアラン女王を必要としませんが、おそらく普通の女性が愛する者と共に過ごしたいという誕生日の願いは叶えられるかもしれません。\n一般的なカップルのように、一緒に食材を買い、一緒に料理をし、もしかしたら私が一度も体験したことのないことがたくさんあるでしょう。それなら、親愛なるあなたが私を導いて、穏やかで平凡な誕生日を過ごしてくれるでしょうか？\n\nタイス"
  },
  Mail_68899_Name = {
    Text = "平凡な生活…"
  },
  Mail_68899_Sender = {Text = "タイス"},
  Mail_68900_Desc = {
    Text = "守秘者へ\n\nカーシアは世界でいっちばんすごいパフォーマンスの達人だからさ。\nどんな表情だって完璧に模倣できるわけ。\nでもね～、「人間の感情」なんてものは、どうやっても理解できない世界の謎なんだよね。\n\nいろんな人に聞いたんだけど、誰も感情の仕組みはきちんと説明できなかったんだ。\nでもね、ドールに尋ねたら教えてくれたの。\n世界には「心理学」って学問があるんだって。\nたとえ心から共感できなくても、心理学をきちんと学べば、感情の理論はすべてわかるんだってさ。\n\nそれって、すんごく、とっても魅力的じゃない？\nずっとカーシアが悩んできた疑問が、ついに解けるかもしれないんだよ？\n\nところで本題だけど、今週の心理学の授業、君のクラスに参加することにしたから。\nカーシアは君の隣ね。\nこれまで参加できなかった内容は、ちゃんと補習してくれるでしょ？\nお・と・な・り・さん♪\n\nあ、そうそう。\nついでなんだけど、今日はカーシアの誕生日だから。\nこういうときは、カーシアは嬉しい気持ちになるべきで、君も嬉しい気持ちになるべき、だよね？\n\nもし本当にとっても嬉しいイベントなら、学校で思いきり騒いじゃおうよ。\nカーシアがキャンパスを夢みたいにきれいにしてあげるからさ！\n\nカーシア"
  },
  Mail_68900_Name = {
    Text = "心理学……"
  },
  Mail_68900_Sender = {
    Text = "カーシア"
  },
  Mail_68901_Desc = {
    Text = "敬愛する蒼白の使者へ\n\nこの1年間のご助力とご配慮に感謝します。\nあなたの他者への誠実な心は、父なる神が教えてくださったように高尚です。\n\n頻繁にお会いする機会はありませんが、毎回あなたにお会いすると、長い付き合いの親友に会うようで、爽やかな気持ちになります。\n\n誕生日の日は特に何もないかもしれませんが、友人に会う理由としては期待感があり、あなた以外にその日を共に過ごす人を選ぶことはないでしょう。\n\nもし興味があれば、最近私の新しい趣味である、釣りを体験してみませんか。\nもちろん、料理や食事のためではなく、運命が奇跡の贈り物を届けてくれる、この静かな待ち時間を純粋に楽しむためです。\n\nこの静かな感覚をあなたと分かち合いたいと思います。\n自然の中、湖畔で静かに座って過ごすのです。\n親友と2本の釣竿、まさにこれ以上ない1日になるでしょう。\n\nサルバドル"
  },
  Mail_68901_Name = {
    Text = "新しい趣味の釣り……"
  },
  Mail_68901_Sender = {
    Text = "サルバドル"
  },
  Mail_68902_Desc = {
    Text = "ご主人へ\n\n今年の誕生日にね、アイギスとジェンキンが、オレッタにそっくりなガラスの風鈴をくれたの。\nお部屋の窓に吊るしたら、風が吹くたびに、すっごくきれいな音がするんだよ。\n昔、お母さんがリリーを抱っこして、窓辺でお話を聞かせてくれた時のことを思い出すの。\n\n心配しないで、ご主人。\nリリー、毎日お母さんのことを思い出してるけど、ご主人やみんながいてくれるから、寂しくないよ。\n\n今ね、リリー、自分でお話の本が読めるようになったの。\n夕方になると、オレンジ色の光がお部屋に差し込んできて、風鈴に当たって、本の上にゆらゆら揺れる光の模様ができるの。\nお部屋がぽかぽかになるんだよ。\n\nリリー、その時間にぼーっとするのが大好き。\n夕焼けの雲と風鈴を見てると、すごくすごくきれいだなって思うの。\n\n今日、ご主人がお時間あったら、リリーと一緒にぼーっとしてみよう？\n\nリリー"
  },
  Mail_68902_Name = {
    Text = "ガラスの風鈴…..."
  },
  Mail_68902_Sender = {Text = "リリー"},
  Mail_68903_Desc = {
    Text = "小さな者：\n\nこの特別な日はその人間を記念するために定められたものですが、顧客と商売者の両方にとって割引の日は非常に魅力的な販売プランであることを認めざるを得ません。\n前回の誕生日の時、解憂商店の取引注文は通常の半年分の販売量に匹敵するほどで、特に私が祝うために用意した特価商品はすべて完売しました。ミサゴの客たちは私のビジネスを大事にしてくれるのか、あるいは賢明な調査員でさえも割引の誘惑に負けてしまうのでしょうか。\nとにかく、ウィンウィンの喜びを続けるために、今年の誕生日パーティーでも引き続き割引イベントを実施します。年に一度だけの大規模なものですので、購入は迅速に。また、ミサゴでしっかり宣伝を手伝ってください。この日を「双十日」と呼ぶことにしましょう。\nそれと、あなたのためにこっそりと面白い小物を残しておいたから、早く私に会いに来てね。\n\nダフォダイル"
  },
  Mail_68903_Name = {
    Text = "ディスカウントデイ…"
  },
  Mail_68903_Sender = {
    Text = "ダフォダイル"
  },
  Mail_68904_Desc = {
    Text = "ミサゴ大学の守秘者、聡明なる主君へ\n\nご健勝のことと存じます。\nすべての騎士の生涯の願いが、偉大なる主君に仕えることだというならば、僕の騎士としての歩みに悔いはありません。\n僕の人生には幸運もありましたが、不幸な悲劇と壮絶な鮮血もあまりに多く、ミサゴ大学の人々の多くがかつて私に同情を寄せてくれたことも知っています。\n苦難の多寡を論ずるつもりはありませんが、ミサゴ大学にもすでに多くの不幸な人々がいます。\n苦難に満ちたこの世界で、守護のために命を懸けることは悲しむべき事ではありません。\nそれどころか、過去も現在も、僕はそのことに誇りを感じ、常にこの身を捧げる覚悟ができています。\nしかし、ロータンさんは僕がいつも難しい顔をして心配ばかりしていると疲れると仰り、誕生日ぐらいはしっかり楽しむようにと言って、ジェンキンを呼んで、ゲームのやり方を教わる機会を作ってくれました。\n幼少期を取り戻してほしかったようです。\n恥ずかしながら、僕は幼い頃から訓練に明け暮れており、遊びの経験はほとんどありませんでした。\n5歳の子供でも習得できると言われるこのゲームがこれほど難しいとは思ってもみませんでした。\n騎士の道以外にも、まだまだ学ぶべきことが多いようです。\nご都合がよろしければ、ぜひ僕たちと一緒に遊びにいらしてください。\nジェンキンは10連勝した後からすっかり退屈し始めておりますので、主君がいらっしゃれば、きっと見事な勝負になることでしょう。\n\nオジール"
  },
  Mail_68904_Name = {
    Text = "手強いゲーム……"
  },
  Mail_68904_Sender = {
    Text = "オジール"
  },
  Mail_68905_Desc = {
    Text = "おーい。\n\nあのカレンダーがあるんだから、今年はこの尊き迷宮の主の誕生日を忘れてはいないでしょうね。\n特別に、あたしの部屋に来て贈り物を捧げることを許してあげるわ。\nそれと、この日はしっかりとあたしに仕えなさいよ。\n\nたとえば歯磨きに洗顔、着替えや食事の世話、それに部屋の掃除やシーツの交換……\nあと、お前たちの言葉でいうと、あれよあれ……大掃除！\nそう、その大掃除の仕事はすべてお前に任せるから。\nあたしは雑用にはもううんざりしてるの。\n今日は何があっても、昔、ローマで過ごしていた頃みたいに、着るものも食べるものも世話される暮らしを満喫するつもりよ。\n\n今日は誰であろうと、あたしを少しでも働かせようなんて思っちゃダメよ。絶対にね！\n\nアグリッパ"
  },
  Mail_68905_Name = {
    Text = "過去に戻る……"
  },
  Mail_68905_Sender = {
    Text = "アグリッパ"
  },
  Mail_68906_Desc = {
    Text = "守秘者：\n\n時間が経つのは本当に早いです。かつて死ぬまで続くと思っていた生活、今ではほとんど思い出しません。\n今や私は食堂のすべてのささやかなケーキを手に取って知っていて、いかにその無能なシェフたちを駆り立てても、彼らは新しいアイデアを出すことができません。\nなので、新しい年には、私の美食マップをもっと大きく、拡張する予定です。まずは小さな目標を定めましょう：ロンディニウムにあるすべてのケーキ店を食べ尽くすことです。\nそして、走り回って行列に並ぶ光栄な役目は、やはりあなたに任せます！私の信頼を得ることができたあなたはあまり喜ばなくても大丈夫です。ただ、この淑女の名前を感謝の気持ちで称賛するだけで良いのです。\nただし、あの愚かなシェフたちにも、少しは誠意があるようで、彼らのこそこそ話から、大きな十層のケーキを準備しているようです——ああ、彼らはとてもサプライズを隠すのが下手ですね。\nアイデアは少し古臭いですが、もしかしたら今回は誕生日パーティーで新しい友人を多く呼べるかもしれません。\nミサゴでの最初の友人として、私はあなたにケーキの上で最初の一切れを切ることを許します。\n\nマーフィー"
  },
  Mail_68906_Name = {
    Text = "十層ケーキ…"
  },
  Mail_68906_Sender = {
    Text = "マーフィー"
  },
  Mail_68907_Desc = {
    Text = "親愛なる守秘者へ\n\n聡明な君のことだ、ミサゴの神秘的なアーカイブから、もうこの情報を掴んでいるんじゃないかな。\n今日は、「幸運の探偵」にとって記念すべき一日なのさ。\n\nこの世に生まれ落ちた日。\n初めてブラックジャックで勝った日。\n百レース目の競馬を制した日。\n初の密室殺人事件を解決した日。\nそして、死を招いた失敗の日。\nその全てが、この神秘的な6月6日に起きたんだ。\n\nというわけでだ。今日は私と二人で、ブリッジを一勝負いかがかな？\nこの日を、もっと記念すべきものにしようじゃないか。\n\nライカー"
  },
  Mail_68907_Name = {
    Text = "一勝負、いかがかな？"
  },
  Mail_68907_Sender = {
    Text = "ライカー"
  },
  Mail_68908_Desc = {
    Text = "この手紙は挨拶ではない。警告だ——私を支配しようとするな。私に鎖をかけようとするな。\n私は私自身のために行動する。\n私と同じような顔をした奴みたいに、人や世界に幼稚な期待を抱くことはない。\n\n私は私の「主人」になろうとする奴を誰であろうと殺す。\n私は言ったことは必ずやる。\n\nH"
  },
  Mail_68908_Name = {
    Text = "私は縛られない……"
  },
  Mail_68908_Sender = {
    Text = "血ノ鎖・ヘロット"
  },
  Mail_68909_Desc = {
    Text = "守秘者：\n\nもしかしたら、私は以前にあなたに水への愛を語ったことがあるかもしれません。賑やかな人間界に比べて、水の中の世界はなんて静かで安らかなのでしょう。\n私は水草やサンゴの間を漂い、魚の群れと会話を交わしたこともあります。水面から遠ざかるほど、水中の色はより暗くなり、水の波に優しく揺られながら水底から空を見上げると、斑斓な光影が幻想的な色彩を呈し、私の心に最も美しい風景が映ります。\n知っていますか？一部の海洋生物は人の姿を覚えていて、あなたが再び訪れると、これらの「友人」たちが熱心に近づいて迎えてくれます。たとえば、私は賢い小さなタコや、柔らかい黄色の海魚を知っています。\n誕生日のこの日、私は水の下の世界を再び思い出し、あなたが潜りに行くことを望んでいるかどうかわからないけれど、この静かな天地や私の不思議な友人たちをあなたと共有できることを心から願っています。\n\nニムフィーア"
  },
  Mail_68909_Name = {
    Text = "水中の世界…"
  },
  Mail_68909_Sender = {
    Text = "ニムフィーア"
  },
  Mail_68910_Desc = {
    Text = "守秘者へ：\n\nあなたがミサゴ大学に来て以来、わたしはあなたに関することを、まるで幼い子の世話をするように扱うことに慣れてしまったわ。\nあなたの普段の反応を見る限り、そのか弱さはわたしの期待をはるかに上回っていたけど。\n\nとはいえ、あなたの教師であり、保護者として、この1年であなたのトラブルや後処理が減ったことはとても嬉しいわ。\n入学当初、頭がまっさらな状態だったあなたの様子は本当に絶望的だった。\nでも、そこからのあなたの成長速度は確かに才能と努力を兼ねていると言えるわね。\n\nあなたはすでに立派な守秘者として、わたしの期待に応えてくれているわ。\n\nわたしの誕生日のような、特に意味のない日だけど、頑張った守秘者に向けた贈り物を用意したの——\nアリステアが以前に使っていた特訓のプランよ。\nどう？楽しみでしょ？\n\nなぜ私があなたに贈り物を準備したのか、なんて尋ねないでね。\n実験室に入れない日には、何かすることを見つける必要があるの。\n\n準備ができたら、訓練室に来るように。\n\nドール"
  },
  Mail_68910_Name = {
    Text = "贈り物……"
  },
  Mail_68910_Sender = {Text = "ドール"},
  Mail_68911_Desc = {
    Text = "守秘者へ：\n\n舞踊家にとっての1年とは、数万回の旋回と、数万回の跳躍に過ぎないの。\nそして、長年付き合ってくれたダンスシューズを新しいものに交換する以外、何も変わらないようでいて、実はすべてが少しずつ変わっているようでもある。\n\n以前は孤独に慣れていたけど、この1年はいつも見守ってくれる観客と、少し不器用なダンスパートナーがいてくれた。\nあなたがダンスホールにいると、私の体は軽やかになって、子どもの頃に初めて踊りを学んだときのような、言葉にできない情熱と力を感じるの。\n\n私は自分が思っているほど純粋で高潔ではないのかもしれない。\n一生をダンスに捧げると同時に、私はあなたの視線と、拍手が欲しいと願っている。\n\n誕生日の今日は天気がとても良くて、今夜の星空はきっと澄み切っているに違いないわ。\n私の一番の観客であり、私の特別なダンスパートナーよ、どうか美しい湖のある、あの森に一緒に行って、月と星に捧げる舞を一緒に踊ってくれないかしら？\n\nリッツより"
  },
  Mail_68911_Name = {
    Text = "私のダンスパートナー……"
  },
  Mail_68911_Sender = {Text = "リッツ"},
  Mail_68912_Desc = {
    Text = "守秘者へ\n\n私が再生した日から、私はミサゴ大学の人たちから多くの助けを貰ったわ。私はまだ協力するという感覚には慣れていないが、少なくとも君たちと一緒にいるときは、自分の背中を安心して任せることができるようになった。その感覚は……なかなか悪くない。 \n私の人生の大半は、傷つけられて、裏切られることばかりだった。私はそれに抗うことを戦う意味だと思い込んで、自分の生活に復讐以外の何も残っていない状態だった。復讐にしか目を向けられなかったんだ。 \n今は、君たちと一緒に進む中で、戦うことが復讐だけじゃなくて、他にも多くの意味を持たせていいことに気付いた。もしくは、ロータンが言っていたように、戦うことはただ、戦いであるというだけでもいいのだと。 \n私は戦う楽しさを学んだ。自分が解放されるような感覚を感じた。ただ単純に勇敢な戦士であることを楽しむことができるようになった。 \nもし私の戦いが、もっと多くのものをもたらせるのなら、その栄光も喜んで楽しむと思う。 \nそして君へ。今も、未来も、私の刃は決して君に向くことはないと誓おう。 \n\nヘロット"
  },
  Mail_68912_Name = {
    Text = "戦闘の意味…"
  },
  Mail_68912_Sender = {
    Text = "ヘロット"
  },
  Mail_68913_Desc = {
    Text = "親愛なる守秘者様：\n\n正直言って、私は誕生日の願いについてあまり考えています。以前、私がまだ「普通」だった頃、満腹で衣服が足り、家賃を期限通りに支払い、ジェンキンをしっかりと世話することが、私の毎日の最大の願いでした。今は一年を無事に過ごせて、ジェンキンのいたずらを見られるだけで満足です。\nもちろん、ジェンキンの前ではいつも姉の顔をして注意を促しますが、あなたに対しては多くの迷惑を掛けていることを思い知らされ、どのようにトラブルを引き起こしたのかも覚えていないことに悩まされます。\nあなたの変わらない優しさと忍耐は、私を温かくさせ、申し訳なく思わせます。おそらく、これが私の人生で初めて、誰かがこのような包容的態度で私を世話してくれることなのです。私は心から光栄に感じ、感謝しています。\n今年、私は皆のために大きなケーキを焼きました。かつて織物工場のオバサンから教えてもらったレシピで、シェフたちの技術には及びませんが、その特別な味は私とジェンキンがとても気に入っています。今回は材料の心配なしに、皆が満足いくように食べることができるので、ぜひ味わいに来てください。\n私は他の方たちに大人しく誕生日を過ごさせるように説得しました。彼女たちは今日、決してあなたに迷惑をかけないでしょう！\nもし可能なら、必要な時にいつでも私を呼んでください。洗濯、掃除、整理は得意ですので、あなたのその優しさへの恩返しの機会を持ちたいと思っています。\n\nメイソン"
  },
  Mail_68913_Name = {Text = "報酬…"},
  Mail_68914_Desc = {
    Text = "守秘者へ\n\nみんなの願いを受け取る役目を担っている身として、誕生日になると今度は自分が何かを願う番になる、ということに、どうしても慣れることができない。\n私には、特に欲しいものがないから。\n\nドールは言った。\n自分の心の奥底で本当に渇望しているものを見つけなさい、と。\n自分がしているすべてのことは、いったい何のためなのか、自分に問いかけてみなさい、と。\n\n私は長い間考えた。\n私は、私のもとに願いに来る人たちの願いが、みんな叶えばいいと願っている。\nさらに続けるなら、私は人々が願いを叶えたあとに見せる笑顔や、心から私に感謝して、「よく務めを果たした」と称えてくれる姿が好きなのだ。\n\nドールは言った。\nそれは、自分が価値のある、役に立つ人間になりたいと願っているのだ、と。\nきっと、その通りだと思う。\n\nしかし、彼女はまた、こうも言った。\n人の価値は他人によって決められるものではない。\n「役に立つ」ことなど本当は存在しない。\n大切なのは、自分の心に従っているかどうかだけ。\nたとえ他人に「役に立たない」と言われる存在になったとしても、と。\n\nさすがはドール、こんなに難しいことをさらりと言ってしまう。\n私は、役に立つ人間になるべきなのでしょうか？\nそれとも役に立たない人間になるべきなのでしょうか？\nまた少し、わからなくなったわ……\n\nそれでも、心に従うのだとしたら、私は役に立つ人でありたい。\n誕生日に、みんなの笑顔を見ることができるなら、それがきっと、私が一番欲しい贈り物だから。\n\nシレスト"
  },
  Mail_68914_Name = {
    Text = "役に立つ人間……"
  },
  Mail_68914_Sender = {
    Text = "シレスト"
  },
  Mail_68915_Desc = {
    Text = "親愛なる守秘者へ\n\n下水溝のウジ虫のような生き方には、もうとっくに慣れているの。\nそれどころか、それこそが私が生まれながらに与えられた運命だと信じているわ。\nだから何の抵抗もなく受け入れて、喜んで抱きしめているの。\n\nあなた方が私に、自由という美味をもう一度味わわせてくれたことには、本当に感謝しているわ。\nでも、私のあの特別な趣味を受け入れてくれる人はいない。それも当然のこと。\n\nだってここの人はみんな穏やかで善良な人ばかりだもの。\nじめじめした片隅に生える苔が必要としているのは、明るい陽射しなんかじゃなくて、暗くてじっとりした空気だっていうことを、誰も理解できないのよ。\n\nでもあなただけは違う。\n私の尊敬する、心優しい御方。\nあなただけが、私を本当に理解して、助けて、心からの幸福を与えてくれるの。\n\nあなたから与えられる痛みは、あんなにも満たされて、安らげて……自分の存在を、確かに感じさせてくれる。\n\nかつての私には、誕生日に祈るほどの願いなんて、何ひとつなかった。\nでも今は、あなたの背中を追いかけて、この心と体すべてを捧げることが、私の願い。\n\nもちろん、優しいからといって私に甘い顔をしないでね。\n思う存分、私を蔑んで、罵って、鞭打ってくださいまし。\n\nレーア"
  },
  Mail_68915_Name = {
    Text = "苔のささやき……"
  },
  Mail_68915_Sender = {Text = "レーア"},
  Mail_68916_Desc = {
    Text = "親愛なる子犬ちゃん：\n\n私はほとんどもう、あなたと一緒に鼠を捕まえる遊びをする日々が大好きになってしまいました。まるで古典的なヒーロー小説のように、正義の使者は必ず最後の瞬間に邪悪な悪党の陰謀を阻止することができるのです。なんて感動的で、なんて素晴らしいことでしょう。\nただ、あなたが無駄に奮闘している姿を見ると、本当に笑いをこらえることができません。\nこの世界はすでに終わっており、救済される手立てはありません。この星もまた、万千の死の星たちのように、\n@1&#x5B@187;&4;@1で覆われるのでしょう。\nまあ、少し遊んであげましょう。今、私はNの趣味を少し理解できるようになってきました。運命づけられた結末を迎える前に、何をするかは実際、あまり違いがないのです。\nあなたの親愛なる師匠の誕生日の日に、私はあなたのために大きなサプライズを用意しました。誕生日が終わるカウントダウンの前に、その隠された「爆弾」を見つけてほしいです。\n私たちが完全に溶けてしまう前に、あなたは私にどれだけの楽しみをもたらしてくれるのでしょうか？\n\n\n「ドール」"
  },
  Mail_68916_Name = {
    Text = "驚きの爆弾…"
  },
  Mail_68916_Sender = {
    Text = "溶壊・ドール"
  },
  Mail_68917_Desc = {
    Text = "守秘者：\n\n最近、ロンディニウムの社交界では自らデザイン画を描き、それを元に特別な宝飾品を誂える、という流行が広まっているそうです。\n芸術を理解していると自負されるご婦人方は、宝石の大きさを競うのをやめ、今度はデザイン画の巧みさを競い合っていますが、その裏でこっそり著名なデザイナーを雇っているのは、あまりにも見え透いたことですわね。\nこの流行のおかげで、わたくしの誕生日の贈り物リストにも、気取った宝石やアクセサリーがずいぶんと増えてしまいました。\n中でも、なかなか見事なピジョンブラッドのルビーが一つあるのですが、それに相応しい指輪の台座がまだ見つかっていないのです。\nつまらない老紳士たちに頼むくらいなら、いっそわたくしの騎士に、心のこもった1枚のデザイン画を描いてもらう方が良いと思うのですが、それを、わたくしへの贈り物にするというのはいかがかしら？\nあなたの作品を、心から楽しみにしていますわ。\nあなたの審美眼なら、きっと素敵なものになると信じております。 \n\nソレール"
  },
  Mail_68917_Name = {
    Text = "ジュエリーをデザインする…"
  },
  Mail_68917_Sender = {
    Text = "ソレール"
  },
  Mail_68918_Desc = {
    Text = "守秘者：\n\nあなたとの初めての出会いの前に、何千もの扉の背後で、私はすでに無数の同じようで異なるあなたに出会っています。\nあなたの喜怒哀楽を覚えていて、あなたの選択を一つ一つ思い出し、異なる世界で前に進み続けるあなたの姿を知っています。\n私にとって、数え切れないあなただけの中で、あなたは最も特別な存在です。私は観測した世界に心の中で名前を付け、あなたのいる世界は希望と名付けました。この名前はあなたに出会った日からです。\nこの「希望」と呼ばれる日に、あなたが他の世界を見てみたくなるかもしれないと思いました。宇宙を体感する双眼のように、私はあなたを導いて、扉の前で静かに見守っていたすべてを見せてあげます。\nそして、私の目の中のあなたも見せてみせます。\n\nタヴィ"
  },
  Mail_68918_Name = {
    Text = "「異なるあなた…」"
  },
  Mail_68918_Sender = {Text = "タヴィ"},
  Mail_68919_Desc = {
    Text = "元来、ミサゴの簡潔なスタイルは私の心にかなっていたが、ミリアムという女がやってきてから、私の生活は穏やかでなくなった。\n私は、安定を求め、庇護を求める人々を拒まない。この混沌とした世界の中で慰めを求めるのは生き物の常であり、無理もない。\nしかし、私は常に万能の神を自称することを好まず、ましてやリモリアが沈没した後、この地にもう一つの高みある神を作る必要はない。\nミリアムはおそらく過去の影から抜け出せず、それを現在に持ち込んで、どこに行っても多大な注目を受け、絡まれる羽目になっているのに、本当にはた迷惑なことだ。\n今日は誕生日である。きっとあの女は早々に式典を準備して盛大に行うだろうが、私はそれを聞くのも乱耳で、見るのも頭痛。会場には行って煩わしいことに巻き込まれない。\nもしあなたが興味を持っていたら、後の手紙に記載されている住所に来て、私と散歩して心を静めましょう。\n注意しよう、あの女には見つからないように。\n\nトゥルー"
  },
  Mail_68919_Name = {
    Text = "静寂を避けて…"
  },
  Mail_68919_Sender = {
    Text = "トゥルー"
  },
  Mail_68920_Desc = {
    Text = "俺は毎日耐え難い飢えにイラついてる。\n血を飲まないと辛いもんだ。\nだが、お前の血を試した後は、普通の血を飲んでも、蝋の塊でも食ってるみたいに不味く感じる。\nお前の血液の甘美な味が毎日、喉の奥で俺を誘惑している。\n\n人間一人を吸いつくせば、どれほどの血が飲めるのか、俺は知っている。\nだが、その美味しさは一瞬で消えちまうもんだ。\nお前をすぐ死なせないために、俺は飢えに耐えることを学んで、次の一口を待つことを覚えた。\nお前の鮮血を再び味わう日までな。\n\nはは……まさか、自分がここまで耐えられるとは思わなかった。\n自分が進化でもしたんじゃないかと疑いたくなるくらいだ。\nここまで我慢しているんだ。\nせめてこの誕生日っていう日くらいは、お前のその甘美な血を少しだけ味わわせてくれないか？\n一口だけでいい、どうだ？\n\nマス・クラブで稼いだ金で栄養補助剤も買っておいた。\nこれでもう、貧血にもないはずだ。\n\n長いこと腹を空かせているユウハシュより"
  },
  Mail_68920_Name = {
    Text = "美味しい血……"
  },
  Mail_68920_Sender = {
    Text = "ユウハシュ"
  },
  Mail_68921_Desc = {
    Text = "敬愛なる守秘者へ：\n\nこの1年間、訓練教室での君の継続的な進歩を見ることができて、非常に喜ばしい。\n君は若い頃の俺をすぐに追い越して、屈強な兵士になることができるだろう。\n君の訓練教官になれたことを誇りに思う。\n\n今年の誕生日に、登山に適した長靴を貰った。\n君は俺と一緒にハイキングでもして、成長した体力を試してみることに興味はあるか？\nそれに加えて、山の頂上で日の出でも眺められたら、その風景はきっと素晴らしいと思う。\n\nもちろん、野外キャンプの温かい飯に、温まる酒を添えれば、なお完璧だろう。\n\nアルバより"
  },
  Mail_68921_Name = {
    Text = "登山へ…"
  },
  Mail_68921_Sender = {Text = "アルバ"},
  Mail_68922_Desc = {
    Text = "パートナー：\n\nこの1年でたくさんのことが起こりましたが、あなたにとってはそれが素晴らしいキャンパス生命ではなかったかもしれません。\n私はこの1年の間にあなたに対して強要したことが多かったと認めますし、関心は少し配慮に欠けていました。すべての訓練が少し無理をさせる形になり、あなたは一度に多くのことを負担しました。\nでも、私はあなたが私の心の中で永遠に最も重要な存在であることを知ってほしいです。ミサゴの守秘者以外では、あなたは私の唯一のパートナーです。\n今日は、ただ誕生日というこの日に、私は試しに気まぐれに振る舞うことができ、あなたもすべての責任を忘れることができれば嬉しいです。私たちはどの宿題や訓練も気にせず、リラックスできる時間を持ちましょう。\n市内の遊園地？劇場？デパートや通りの市場……何でもいいので、失ったものをできるだけ補いたいです。\n同様に、何も考えずに過ごせる1日をあなたと共に過ごしたいので、すべての行程はあなたが決めてください。\n\nラモンナ"
  },
  Mail_68922_Name = {
    Text = "リラックスの日…"
  },
  Mail_68922_Sender = {
    Text = "ラモンナ"
  },
  Mail_68923_Desc = {
    Text = "親愛なる守秘者様：\n\n私が人間界で過ごした年月の中で、かつて愛らしい従者たちは毎年この日を迎える時、私のために盛大な宴会を開き、さまざまな方法で私を喜ばせようと努力しました。\n無事無事の平凡な一日なのに、彼らの奇妙な笑顔の中で本当に楽しい気持ちになりました。苦しみを楽しむこと、無から有を生む技術では、人間は確かにこの道に長けています。\nたとえこの学校で墓が建てられていても、あなたたちがこんなに頑強に楽しいことを生み出すことには驚かされます。\nただ、普通の人々からの贈り物は本当に退屈で、いわゆる誕生日パーティーは信じられないほど退屈であり、俗物が結局のところ占める割合が高いのです。\nあなただけが、あなたを思い出す時に少し興味を持つことができ、昔のような楽しさを再び味わわせてくれます。\n今すぐ私の部屋に来て、明け方まで一緒に遊びましょう。うまく伺えれば、私はあなたが私の手背にキスすることを許可するかもしれません。\n\nワンダ"
  },
  Mail_68923_Sender = {Text = "ワンダ"},
  Mail_68924_Desc = {
    Text = "<Del:西区のやつ>種皮者：\nほんとはこんな恥ずかしいことを書くつもりなかったんだけど……\nアイギスがずっと隣で記念とかの意味について話し続けて、どうやってもこの手紙を書かせようとするんだ。\n\nなので、アイギスのために、仕方なく少しだけ言わせてもらう。\n\nこの1年、学校の寮や食事には、だいたい満足してる。\nけどさ、宿舎のシーツが滑りやすくて、ずっと眠りにくいんだよ。\n粗い綿の布団で寝る方が快適だと思うだろ？\n\nもう少し文句を言うと、食堂の食事が健康的すぎる。\n食べ終わると満腹感はあるけど、口の中に味がない感じ……\n露店の味にまったく敵わない！\n\nだから、今年の誕生日パーティーはシェフたちに手間をかけさせない。\nグルメのあたしが皆を東区の最高な小道に連れていって、あたしとブラウンが特におすすめする屋台で楽しんでもらうつもり。\n\nきっと皆は露店のうまさに感動するはずだ！\n\nもちろん、今日のすべての費用はお前が負担してくれるだろ？\n反対するなよ？\n\n古くからの仲間のジェンキンとブラウンより"
  },
  Mail_68924_Name = {
    Text = "露店の味……"
  },
  Mail_68924_Sender = {
    Text = "ジェンキン"
  },
  Mail_68925_Desc = {
    Text = "私の恩人へ\n\n 姉さまを除けば、これほどまでに心から私を支えてくれたのは、あなたが初めてです。\n以前あなたからいただいた助言のおかげで、私は今、音楽会社とともに一連の曲集を企画・発表し、そして間もなく、私自身の個人での演奏会を開催することになりました。\n この星で開く初めての演奏会は、誕生日当日にしようと思っています。\nここで新たに生まれ変わった自分を、記念するために。\nぜひ会場に足を運んでいただき、私が全力で歌う姿を聴いていただけたら嬉しいです。\nそして終盤には、あなたと姉さまを特別ゲストとして舞台にお招きし、私の新曲を一緒に歌っていただきたいと考えていますが……いかがでしょうか？\nあ、このことは姉さんには内緒にしてください。\n同じく彼女の誕生日でもありますから、驚かせてあげたいのです。\n姉さまと交わした、「誕生日の願いは自分のためだけのものにする」という約束についてですが、私はこの星で、再び自分の歌声を輝かせることを願っています。\n\nティンクト"
  },
  Mail_68925_Name = {
    Text = "コンサート…"
  },
  Mail_68925_Sender = {
    Text = "ティンクト"
  },
  Mail_68926_Desc = {
    Text = "親愛なる守秘者様へ\n\n知らぬ間に、また一年が経ってしまいましたね。\n\nミサゴでの毎日は本当に楽しくて、みんなと遊んだり、授業を受けたり、おいしいものをたくさん食べたり……人生で一番幸せな時間です。\nたまに任務に出るときは少し緊張してしまうのですが、みんなと一緒に戦うとき、アイギス、ちっとも怖くないんです。\n\n本当に申し訳ないのですが、今年もたくさんご迷惑をおかけしてしまいました。\n多くはジェンキンがまたいたずらしてしまったせいなのですが……あの子も、みんなを楽しませたかっただけなんです。\n私たちの不注意や無礼を、どうかお許しいただけたら嬉しいです。\n\nジェンキンといえば、今年は私の誕生日に「ホタル捕まえ大会」をやろうって言い出して。\n透明な瓶をたくさん用意してくれていて、それでホタルのランプをたくさん作るんだそうです。\n最後に一番明るいランプを作った人が、「虫捕り大王」の称号をもらえるんですって。\n\n虫捕り大王なんて、ちょっと変な響きですけど……夏になるといつもホタルでいっぱいになる、あの森は本当にきれいなんです。\nお忙しい中、もし少しでもお時間ができたら、ぜひ一緒に森にいらしてくださいませんか。\n星のようにきらめく、あの景色を見に。\n\nアイギス"
  },
  Mail_68926_Name = {
    Text = "ホタル捕り大会…"
  },
  Mail_68926_Sender = {
    Text = "アイギス"
  },
  Mail_68927_Desc = {
    Text = "守秘者ー！\n\nこの前ね、海で泳いでたとき、オレッタ、電気を出す新しいお友達に会ったの！\nまんまるで、ぺったんこで、おっきなピザみたいなかたちなんだよ！\n\nオレッタね、ご挨拶しようとしたの。\nそしたら急に体がピリピリってして、新しいお友達もパッてどっか行っちゃった。\n\n帰ってきてからドールが教えてくれたの。\nあれは「シビレエイ」が電気を出してるんだって。\nよく分かんないけど、新しいお友達、すっごくかっこいい！\n\nちょうどオレッタの誕生日だし、守秘者、一緒にあの子をお迎えに行こう！\nそれでオレッタの仲間たちと一緒に住むの！\nあのピリピリ、守秘者もきっと好きになるよ！\n\nオレッタ"
  },
  Mail_68927_Name = {
    Text = "ピリピリする新しいお友達…..."
  },
  Mail_68927_Sender = {
    Text = "オレッタ"
  },
  Mail_68928_Desc = {
    Text = "敬愛なる守秘者：\n\n子供の頃の誕生日は、父からの厳しい要求であり、演奏の練習は一瞬の緩みも許されませんでした。\n誇り高くあってはならず、浮き立ってはならず、怠けてはならず、母が密かに小さなケーキを用意してくれる以外、この日は私にとって厳しい訓戒を受けるだけの日でした。一年を振り返り、私の多くの不足が指摘されるのです。\n今や私は音楽の徒弟ではなく、あなたがあの壮大な扉に触れ、至高の音楽の殿堂に足を踏み入れることができるのですが、幼少の頃からの教訓は、平凡な楽しみへの欲望を持たざるを得ない私を作り上げてしまいました。\nただ音楽だけが、あなたのために運命づけられた安魂の曲を演奏することが、私の生涯における最終的な追求であり、唯一意味のある瞬間を感じることができるのです。\nもし今夜、あなたが私に眠る前の時間を与えてくださるなら、私は一晩中、私の魂に刻まれた曲を演奏し続けることを喜んでお受けします。夜明けまで。\n\nハムリン"
  },
  Mail_68928_Name = {
    Text = "演奏の心願…"
  },
  Mail_68928_Sender = {
    Text = "ハムリン"
  },
  Mail_68929_Desc = {
    Text = "青二才へ\n\nあのイカれた頑固女からようやく解放されたと思ったら、お前たちのところの規則の多さときたら、あの女をも凌ぐとはな！\n俺はもう長いこと、胸がすくような痛快な気持ちを味わってない！\n\n酒をがぶ飲みするのもダメ、女を口説くのもダメ、焚き火の宴もダメ。\nそのうえ、お前らの焼き肉なんざ、ペリシテのよりはるかにマズい！\nこんな味気ない生活で、よく息してられるもんだ。\nまったく理解できん。\n\nだが強者は環境を嘆いてはいけない。\n俺は征服の果てに、再びお前らの都市で偉大なギャングの頭になった。\n\nそして今日——この偉大なゴリアテ様の誕生日を記念して、慈悲深き俺が、てめぇを子分たちが開く宴に招待してやる！\n美酒美食と美女は揃っていて、世間知らずのお前が目覚めることこと間違いなしだ。\n\n昔の馴染みってことで、プレゼントは免除してやる。\nその代わり、お前の敬意を携えて、この強者の復活に祝福を捧げるがいい！\n\nその目に焼きつけておけ。\n来年の今日も、再来年の今日も、たとえどこにいようと、俺は新たな覇道を切り拓いていることだろう。\n\nゴリアテ"
  },
  Mail_68929_Name = {
    Text = "覇道……"
  },
  Mail_68929_Sender = {
    Text = "ゴリアテ"
  },
  Mail_68930_Desc = {
    Text = "守秘者： \n\n元々私は、この薄っぺらな身体の誕生日を祝うことなど考えたことがなく、ただ普通の修行の日として過ごしていましたが、今朝、王が私を見つけて言葉を届け、今日は王や修行に関することはしないように命じ、完全に自分のために一日を過ごすべきだと言われました。\n多くの日夜を経て、王が私をこんなに心に留めてくれるのは初めてで、不安と感謝の気持ちでいっぱいです。しかし、私はすでにこの生涯のすべてを王に捧げており、一瞬、どこに行くべきか、何をすべきか分からなくなってしまいました。\nしばらく考えた結果、今のところ唯一少し後悔していることは、マーフィーという子供に対する罪悪感です。故国復興のために、私は彼女に対して一度も後悔したことはありませんが、彼女に対しては返済しようもなく、補償することもできないと自覚しています。\nしかし、もし本当に心からやりたいことがあるとすれば、少し厚かましくなって、もう一度母親としての役目を果たしたいと思います。\n私はその子が以前好きだったお菓子を特別に買って来ました。これは、不名誉で無能な母親を成就させるためのものです。これを彼女の手に届けていただけないでしょうか。決して私からの贈り物だとは言わず、あなたが準備したものだと言ってください。\nお願いできれば、非常に感謝します。\n\nミリアム"
  },
  Mail_68930_Name = {Text = "補填…"},
  Mail_68930_Sender = {
    Text = "ミリアム"
  },
  Mail_68931_Desc = {
    Text = "ふはは、我の叡智による考察の結果、人間たちの誕生日の意義を完全に理解した。\n\nいわゆる「特定の人物だけに属する特別な一日」。\nつまり、希少な特権を行使する機会を得ることができ、貴重な品を手に入れる機会を得ることができ、そして他人に対して堂々と願いを突きつける機会を得ることができる日なのだな？\n\n普段なら口に出せぬ願いも、思いもせぬような望みも、この日ばかりは叶えられる可能性があると。\nははっ、これはどんな祝日よりも刺激的な、解放の日ではないか。\n\nどうやらこれまでの長い年月、我はずいぶん多くの特権を逃してきたらしい。\nだが幸いにも、我には長い寿命がある。\nこれから先、願いをかける誕生日はいくらでもあるのだ。\n\nでは、我の誕生日には、全員に付き合ってもらい、思いきり一戦交える、と願おうか。\nこの程度であれば、簡単であろう？\n\nロータン"
  },
  Mail_68931_Name = {
    Text = "誕生日の特権……"
  },
  Mail_68931_Sender = {
    Text = "ロータン"
  },
  Mail_68932_Desc = {
    Text = "守秘者： \n\n年齢が増すにつれて、誕生日は徐々にカレンダーの上で目を引くことなく過ぎ去る日になってしまった。不意に思い出したときには、誕生日はまるで水の流れのように静かに過ぎ去ってしまった。 \n大人の世界において、誕生日を祝うことは子供や退屈な人の特権だ。私もその面で退屈な大人になってしまい、誕生日にはもはや期待していない。 \nかつてのある年、私は突発的なアイデアで自分のために美しいケーキの彫刻を作ったが、その後数年間、忘れてしまうことによってケーキを予約し損なうことはなかった。誕生日には、倉庫からその腐らない祝賀道具を取り出し、キャンドルを吹き消す儀式を体験すれば、誕生日は完了したものとみなす。 \nミサゴに来るまで、退屈な人と忙しい人が同じ人の中で共存する状態を持つことができることに気付かなかった。そして、ここではその人が自分だけの退屈に満足するのではなく、全員を一緒に退屈にしようとするのだ。 \nこの2年間、ミサゴで参加した誕生日パーティーは、私の前半生で参加したすべての誕生日パーティーよりもはるかに多い。さらにおかしいことに、そのような退屈な祝賀の中でさえ、私は不思議な楽しさを見つけてしまった。 \nおそらく、悲惨で厳格なテーマだけでなく、日常の中でまぬけな場面を描写することも、芸術的な美で満たされることができる。 \nここまで来たら、今年の誕生日の創作計画として、守秘者がしているバカ笑いの半身像を彫り、私の彫刻ケーキを持つことにしよう。 \n早めに私のアトリエに来てね、私のミューズモデル。 \n\nサンガー"
  },
  Mail_68932_Name = {
    Text = "退屈な楽しみ…"
  },
  Mail_68932_Sender = {
    Text = "サンガー"
  },
  Mail_68933_Desc = {
    Text = "拝啓\n\nこの何もない世界で、手紙を書き始めるまでにずいぶんと考えこんでしまった。ずっと自分の誕生日を忘れかけていた。こんな世界では、祝うこと自体が無意味だったから。\nだが、あなたに出会い、私はますます欲張りになってしまったようだ。当たり前だった孤独ですら堪え難くなっている。\n私の心には奇妙な感情が芽生えた。そちらの世界の私に対して少しの羨望と微かな嫉妬が生じている。自制心を自負する私のような者でも、こんな情けない気持ちを抱く日があるのだ。人間の公正さと理性には限界があるということを痛感している。\nあなたが私を思って招待をしてくれていることは知っているが、時間と空間にとって不要な揺らぎを与えるのはできるだけ避けるべきだ。私はあなたの世界へ行くべきではない。\nこれを書いているとき、私は宇宙を見上げている。時空の裂け目が開くであろう場所を見つめている。もしあなたも同じように見上げているなら、私たちも同じ星空を見つめていることになる。\nこの手紙が私の代わりとなって、時空を超えて、あなたの手に届きますように。あなたの目を通して、あなたに出会い、あなたに寄り添えますように。\nあなたがこの手紙を抱きしめるとき、私は世界のこちら側であなたを抱きしめることを想像している。\n敬具\n\n「ラモンナ」"
  },
  Mail_68933_Name = {
    Text = "共に眺めて……"
  },
  Mail_68933_Sender = {
    Text = "環行・ラモンナ"
  },
  Mail_68934_Desc = {
    Text = "私の小さな囚人へ：\n\n君は知っているかい？さまざまな動物にそれぞれの食事があるように、人の温もりの求め方も違うんだ。一人にとっては一枚の服を羽織るだけで十分なこともあるが、誰かにとっては温かい手を握ることや、温かい抱擁が必要になることもある。そして、ある人にとっては、ろうそくが溶けるくらいの温度が必要なんだ。\nそのように熱く、粘り気のある温度が、すべての神経の末端に刻み込まれ、ろうそくのしずくの軌跡を鮮明に映し出す。微かな痛みと、震えるような触感、声に出さずにはいられない瞬間にこそ、自分自身という存在を強く感じることができるんだ。\n時折、私はろうそくに変身し、刻印をもたらす喜びを味わうことがあるし、逆にろうそくの温かさに惹かれ、その痛みのある甘美な暖かさを求めることもある。\nミサゴの冬はもう訪れ、最近では寒さと一緒に孤独も感じる。愛しい君なら今日が何の日か知っているはず、私の願いはささやかなおくりものであり、優しい君ならきっと寂しさを癒す温もりを与えてくれるでしょう。\n\nパンディア"
  },
  Mail_68934_Name = {
    Text = "温かさの必要…"
  },
  Mail_68934_Sender = {
    Text = "パンディア"
  },
  Mail_68935_Desc = {
    Text = "守秘者へ\n\n今年、私はティンクトとお互いに約束しました。\n今年の誕生日の願いは、自分自身のことだけにして、相手のための願いは立てないと。\nこの約束を先に意地になって言い出したのは彼女でしたが、どうやら困っているのも彼女自身のようです。 \n私たちはあまりにも長い間、互いに結びついて生きてきました。\n普通の人のように、独立して物事を考えることさえ、簡単ではありません。\nしかし、これほど多くの助けと優しさに満ちた新しい人生へと生まれ変わった今ほど、自分の足で歩くことを学ぶのに、ふさわしいときはないのでしょう。 \nそうして慎重に考えた末、私は今年の願いを決めました。\n新しい友だちを5人作ること……いえ、やっぱり3人にしておきましょう。\n自分を変えるというのは、少しずつ、ゆっくり進めるものですから。\n今のところ、私にとって唯一、そして人気のある友達のあなたなら、もしかして、友だちを作るコツを教えてくれるのではないでしょうか？ \n\nファイント"
  },
  Mail_68935_Name = {
    Text = "交友の願望…"
  },
  Mail_68935_Sender = {
    Text = "ファイント"
  },
  Mail_68936_Desc = {
    Text = "守秘者： \n\n毎年誕生日の願い事をする際、私は同じ願いを繰り返します。それは完璧な血脈の変革です。私はずっと自分の血脈への執着が他の人から見れば頑固で、滑稽で、さらには哀れで卑しいものだとはわかっています。\nしかし、あなたは違います。どんな時でも、私はあなたが私をこの道の上で支え続けてくれることを知っています。たとえ壁にぶつかり、倒れ、何も得られず、他人の笑い声の中にいても、あなたは最初に私を気にかけてくれる人です。\nもしかしたら、あなたや他の誰も、幼い頃から抑圧され、侮辱されてきた人が背負っているすべてを理解することはできないかもしれませんが、構いません。この変革の道での苦難はすでに私の血肉と栄養となり、私を支え続け、反抗し続けるのです。\n私はもう無力な若者ではありません。たとえ試験が厳しくても、私は最後の瞬間まで貫き通します。\nその前に、どうか私に注目し、私の成功を待っていてください。\nそういえば、以前私にくれた五十元、返すと言ったが、今すでに貯めて十分になり、さらに二元も余分になったので、それを返しにお渡ししますね。\n\nカエクス"
  },
  Mail_68936_Name = {
    Text = "返して…"
  },
  Mail_68936_Sender = {
    Text = "カエクス"
  },
  Mail_68937_Desc = {
    Text = "敬愛なる守秘者：\n\nこんにちは、オートマタ「エリカ」の年次点検調査票のご記入を歓迎します。私は、あなたがエリカを使用する中での実際の体験や遭遇した問題を収集致します。あなたの意見は、エリカの改善の方向性となります。\n次に、関連する問題について、低いから高いまで点数を付けて返信をお願い致します。ご協力ありがとうございます。\n使用時の利便性：1-5点\n使用時の応答速度：1-5点\n需要の理解度：1-5点\nユーザーの感情への配慮度：1-5点\n資料検索時の精度：1-5点\n解決策の実用性：1-5点\n最後に、エリカを使用中に遭遇した問題や不満な部分について簡潔に記述してください。これらの問題は今後修正される可能性があります。\n質問票を完成させると、周年記念の小さな贈り物があなたの部屋に届きます。来る一年、最も親しい助手であるエリカがあなたのそばに居続けます。ご利用ありがとうございました。またお会いしましょう。\n\nエリカ"
  },
  Mail_68937_Name = {
    Text = "年次メンテナンス調査アンケート…"
  },
  Mail_68937_Sender = {Text = "エリカ"},
  Mail_68938_Desc = {
    Text = "守秘者へ \n\n誕生日を迎えるたび、わたくしは一日をかけて過去を丁寧に思い返して、同じ日記をもう一度書き綴っています。\n故郷から遠ざかるほどに、かつての記憶は次第に曖昧になっていくようです。\n光を辿り帰還者を待ち続けた日々も、遠くから王の威儀を仰ぎ見た日々も、いまや確かには思い出せなくなりつつあります。\n\nそれでも、わたくしは忘れたくないのです。決して。\nたとえ待ち続けるときが果てしなくとも、たとえ魂を燃やすことになろうとも、この光は決して消えることはありません。\n祖国が再び甦るその日、わたくしは一番初めに、その呼びかけに応じる光となるでしょう。\n\n再会の情景は幾度となく思い描いてきましたが、まさかこの地で王と祭司に再び相まみえるとは、夢にも思いませんでした。\nあなた方の言葉を借りるならば、心安らぐ場所こそが故郷であるというのなら、ここはすでに、私にとって第二の故郷と呼べる場所です。\nそして、日記に綴られる内容もまた、もはや回想ではなく、日々新たに刻まれていく記憶へと変わりました。\n\n賞賛も贈り物も必要ありません。\n再び王のもとに付き従えること、それこそが何よりの幸福なのです。\nもしこの身の光が祖国の海底を照らすことが叶わぬのなら、せめて王の歩みに従い、しばしこの陸の国を照らし続けましょう。\n\nファロス"
  },
  Mail_68938_Name = {
    Text = "我が王に従い……"
  },
  Mail_68938_Sender = {
    Text = "ファロス"
  },
  Mail_68939_Desc = {
    Text = "守秘者： \n\nおめでとう、そしてあなたにもおめでとう、ミサゴにもおめでとう、私たちは黒い恐怖の追跡の中でまた一年を生き延びました。\n今日は単なる誕生日ではなく、私が生きていることを記念する日です。この逞しい命の讃歌の日でもあります。\n生きること、ただ二言をもってどれほど多くの困難が含まれているのでしょう。この熱い生命力は、熱いコーヒーの香りに匹敵します。一緒にコーヒー神教に参加しましょう、守秘者、目覚めを称え、生きていることのすべてを讃えましょう。\n\n共に送られてきたメモ：\nああ、ウインクルはまたコーヒーを飲みすぎて、神経が高ぶり、過労のせいで机の前で気を失ってしまいました。私は彼女を保健室に運びましたので、心配しないでください。\nしかし、彼女が昏倒する前に、一袋の貴重なコーヒー豆と手紙を取り出し、どうやらあなたにあげたかったようです。それを一緒に同封しましたので、彼女が目が覚めた時に後悔しないことを願っています。\n彼女の誕生日については、祝賀パーティーよりも、しっかりと休養することが最良の贈り物かもしれません。\n——シルヴィア"
  },
  Mail_68939_Name = {
    Text = "生命を讃えよ…"
  },
  Mail_68939_Sender = {
    Text = "ウインクル"
  },
  Mail_68940_Desc = {
    Text = "守秘者：\n\nハハハ！私は部屋の隅々に12のリマインダーを刻み、36枚の紙をメモすると（もしかしたらもっとあったかもしれないが見つけられない）、ついに期待に応えて今日は私の誕生日を覚えました！ \n驚くことでしょう、実は私自身も今朝まで思い出せませんでしたが、今年一年の精一杯の準備のおかげで、この良い日を逃したくなかった。 \n先日、皆と一緒に開いたパーティーは本当に楽しかった。特に誰と遊んだのか、どんなゲームをしたのか、また食べた特定のデザートも……まあ、要するに楽しかったです！ \n子供の頃、誕生日にはお母さんが冒険物語の本を買ってくれました。私たちは毎晩寝る前に寄り添って読み、夢の中で素晴らしい冒険をしました。起きた後すぐに忘れてしまっても、その幸せは心に留まり続けると思います。 \nさらに、忘却にも良い面があります。以前のパーティーで何をしたか思い出せなくても、今日はすべてを再体験できますから。前回の楽しみをもう一度持ってきてください！ \n\n期待に満ちたナウティラ"
  },
  Mail_68940_Name = {
    Text = "もう一度……"
  },
  Mail_68940_Sender = {
    Text = "ナウティラ"
  },
  Mail_68941_Desc = {
    Text = "敬愛なる守秘者：\n        V1.7.1の更新において、「繁殖狂熱」の「血ノ鎖・ヘロット」イベントの解放済み状態が異常により消失しました。消失後に再度解放を行ったため、再解放に消費した「起点装置」×3を補填いたします。ご確認ください。"
  },
