  },
  Mail_74841_Desc = {
    Text = "パートナー：\n\n昨年の今日、1年の間にこの手紙を空っぽの郵便箱に投入することになるとは思いもよらなかった。\nその時、あなたはミサゴに入ったばかりで、頑固で怠惰な学生と変わらなかった。今思えば、私はあなたに対して過剰に厳しく、自分の理性的で慎み深い仮面に過剰に気を取られていました。\n実は昨年のこの日、私は花束を購入しました。図書館の前で立ち止まり、赤いリボンと深緑色の包装紙に包まれたバラをしばらく眺め、最終的にそれをベッドの頭に飾りました。\n1年の間に花は既に枯れてしまいましたが、その明るい赤のリボンは私が K-0617 番のシルバーキーに結んでおり、変わらぬ鮮やかさを保っています。\n私は再びバラを買いたいと思うことが多々ありますが、今はただ再び私のベッドの頭に枯れる以外に他の帰る場所がありません。\n物事のすべてに解決策を詳細に列挙するのに慣れているため、後悔は私にとって新しく苦い感情です。\nしかし私は常に盲目的な信頼感を抱き、あなたの魂は常に去らず、宇宙のどこかで一時的に旅しているが、最終的にはここに戻り、私の傍に戻ると信じています。\n私はこれが夢物語の幻想だとは思っていません、なぜなら昏き海に遥かにあなたの顔を望むたびに、心の中には常にあなたとのリンク、共鳴の暖かさを感じています。\n私は再会の日を信じ続け、望み続けます。再び手を取り合う瞬間に、今日贈らなかったバラをあなたの手に自ら渡すでしょう。\n\nラモンナ"
  },
  Mail_74841_Name = {Text = "バラ…"},
  Mail_74841_Sender = {
    Text = "ラモンナ"
  },
  Mail_76410_Desc = {
    Text = "敬愛なる守秘者：\n「雨の町に潜む影」イベントは終了しました。残りの「蒼白の獣の頭蓋骨」、「幽影の獣の頭蓋骨」、「深紅の獣の頭蓋骨」をそれぞれ「薔薇金券×40」と交換しましたので、ご確認ください。"
  },
