  },
  Mail_78792_Desc = {
    Text = "敬愛なる守秘者：\n「雪山消融時・復刻」イベントは終了しました。残りのイベント通貨「寒凍の蕾」「銀霜の蕾」および「日光の蕾」をそれぞれ「薔薇金券×40」の比率で回収しましたので、ご確認ください。"
  },
  Mail_78792_Name = {Text = "蕾回収"},
  Mail_78792_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_79390_Desc = {
    Text = "敬愛なる守秘者：\n        《忘却前夜》のご支持に感謝いたします。ミサゴ大学でより良いゲーム体験を提供するため、以下の体験調査アンケートにご協力をお願いいたします。ご協力のお礼として【シルバーコア×200】をご用意しました。ご回答後にお受け取りいただけます。アンケート締切は 3月17日9:00です。ぜひお早めにご記入ください。\n        <SurveyLink:【タップして記入に進む】>\n        我々は守秘者の皆様の意見を真摯に受け止め、ミサゴ大学がより良いものとなるよう尽力いたします！\n         ——銀の鍵が道を照らさんことを。"
  },
  Mail_79390_Name = {
    Text = "バージョン体験調査アンケートV2.1.0"
  },
  Mail_79390_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_79646_Desc = {
    Text = "敬愛なる守秘者：\n「記憶の奥に埋もれて」イベントは終了しました。残りの「診断レポート」をそれぞれ「薔薇金券」× 40として交換しますので、守秘者の方はお忘れなくご確認ください。"
  },
  Mail_79646_Name = {
    Text = "記憶の下に埋もれた通貨の回収"
  },
  Mail_79646_Sender = {
    Text = "ミサゴ校委員会"
  },
  Mail_80091_Desc = {
    Text = "守秘者：\n\nこの手紙を開くと、私があなたの心に埋め込んだ暗示が発動したことを意味します。\nハハ、心配しないで。こののは私の誕生日パーティーをスムーズに進行させるためのささいな催眠で、あなたに何の影響も与えません。\nこれから、あなたは心からショッピングに行きたいという衝動を感じるでしょう。それに従って街に出て、煌びやかなショーウィンドウから私の心に最も合った贈り物を選び、私の手に渡してください。\n今、あなたの疑問を理解していますし、その合理性にも同意しますが、誕生日の人には特権があるのではないでしょうか？私がこうするのは、あなたにこの特別な日を忘れてほしくないからです。だって、あなたは私が心から思っているゲストですから。\n最後に、あなたの訪問を心待ちにしています——贈り物を忘れないでください。\n\nクレメンタイン"
  },
  Mail_80091_Name = {
    Text = "「自ら」選んだ贈り物"
  },
  Mail_80091_Sender = {
    Text = "クレメンタイン"
  },
  Mail_81288_Desc = {
    Text = "尊敬なる守秘者様：\n        『忘却前夜』へのご支援とご評価、誠にありがとうございます。ミサゴ大学でのゲーム体験をより良いものにするため、以下の体験調査アンケートにご協力いただけますようお願い申し上げます。ご協力いただいたお礼として、「シルバーコア」× 200を準備しております。アンケートを完了することで受け取れます。アンケートの締切は4月14日9:00ですので、タイムリーにご記入いただけますようご注意ください。\n        <SurveyLink:[クリックして記入する]>\n        私たちは全ての守秘者様のご意見を真摯に受け止めます。皆様のフィードバックがミサゴ大学をますます良くすることでしょう！\n        ——銀の鍵が前路を導きますように。"
  },
  Mail_81288_Name = {
    Text = "バージョン体験調査アンケートV2.2.0"
  },
  Mail_81288_Sender = {
    Text = "ミサゴ校務室"
  },
  Mail_81326_Desc = {
    Text = "恩人：\n\n今日、私とポリュクスにとっては、一年で唯一の祭りです。教会にいた頃、私たちは過度に自我の意識に集中することを許されず、すべての価値は灯を携える者に侍奉するという永遠の事業にしか存在しませんでした。そのような信仰の前では、他のどんな祝祭も意味のない虚妄です。\nしかし、毎年誕生日を迎えると、私はポリュクスとこっそりと祝います。侍従に隠れて、できるだけ小さな贈り物を用意し、その日をひそかに待ち望むのです。\n誕生日の祝福の時間は往々にして深夜です——それは一日のうち唯一の自由な時間なのです。ポリュクスは器用な手とアイデアで、彼の贈り物は常に私を超えており、ある時は落ち葉を集めて花を編んだこともありました。\n私は驚きを準備するのは得意ではありません。ポリュクスはいつも私の表情が平常通りにすべてを裏切ると言いますが、私が持っているものはあなたにとってさらに貧弱で退屈に見えるかもしれません。しかし今日は、あなたに喜びを分かち合うための絶好の方法を思いつきました。\n夜に窓が3回ノックされる音を聞いたら、どうか怖がらないでください。窓を開けて、雲と夜風の触感をあなたに体験させます。\n\nカストル"
  },
  Mail_81326_Name = {
    Text = "夜の探検..."
  },
  Mail_81326_Sender = {
    Text = "カストル"
  },
  Mail_84142_Desc = {
    Text = "守秘者：\n\n会合前に、この手紙を書きました。正式に「誕生日航海」への招待と紹介をさせていただきます。\n今回の航海の第一の目的地はテムズ川です。私たちは貨物船を改造した移動レストランに乗り込み、舟を漕ぎながら缶詰の蜜漬けパイナップルとラム酒を楽しむ予定です。これは船員の誕生日に特別に提供される美味しいものですので、気に入っていただけると嬉しいです。\n今回の航海の第二の目的地は港の展望台です。ご安心ください、私は気球協会に観測の許可を申請しました。気球が空高く飛び上がり、ロンドンの航路全体を見下ろす時、私たちは一緒にケーキを切り分け、祝います。\n以前は、航海条件が限られていたため、いわゆる誕生日ケーキは大工がオークとキャラメルで作った模型に過ぎなかったので、ケーキの味を知りませんでした。今回はあなたと共に味わえることができるので、食べ物の素晴らしさだけでなく、もっと多くのものを得られると思っています。\n第三の目的地、あるいは第三の段階は、カスタム星図です。海図に自分の誕生時の天体の位置をマークしました。もしよろしければ、あなたの位置もマークさせていただきたいです。このユニークな航海星図は、最も大切に保管すべき贈り物になるでしょう。\n実は、この手紙を書いている時、ためらいがありました。これらの行為は間違いなく普通の範囲を超えていますが、今日は特別な日であり、あなたは私にとって特別な人ですので、常識を破る価値があります。\nですので、ぜひお断りせず、時間通りにお越しください。\n\nコーパサント"
  },
  Mail_84142_Name = {
    Text = "「航海」招待"
  },
  Mail_84142_Sender = {
    Text = "コーパサント"
  },
  Mail_84355_Desc = {
    Text = "敬愛なる守秘者様：\n「暴雨の中で揺れ動く」イベントは終了しました。現在、守秘者様が残っているイベント通貨「信号旗」を各々「薔薇金券」× 40 として回収しますので、記載の確認をお願いいたします。"
