    Text = "ミサゴ校委員会"
  },
  Mail_94503_Desc = {
    Text = "私の灯火:\n\n私がカストールとここに来て以来、あなたの私たちへの気遣いは新しい生命を授けてくれたかのようで、私たちために精心準備したバースデーケーキに感謝しています。ケーキに描かれた2羽の鳥を蝶々と勘違いしてしまい申し訳ないですが、私たちは本当にこの贈り物が気に入りました。これは他の人から初めて受け取った誕生日の贈り物なのです。\n私たちはコレット学長から学校のプレゼントのグリーティングカードを受け取りました。白い封筒に豪華な金色の印章が貼られており、中には素晴らしい祝福の言葉が綴られていました。ここは本当に暖かい場所で、私たちの人生でかつてない幸福な瞬間です。\nどうか私たちとカストールと一緒に誕生日を祝うために来てください。これは私たちが子供の頃から続けてきた儀式で、私たちの恩人として、私たちはあなたに交換の贈り物を準備しています。それはカストールの落とした羽で編んだ冠です。\nこの粗雑な冠をあなたに献上し、私たちの敬意のしるしとし、私の余生を持ってあなたに従い、この学校の偉大なビジョンを実現するために、真の罪と暗闇を消去することを誓います。\n久しぶりにこれをやりましたが、カストールは私の手芸が子供のころほどではないと言って笑っていました。どうぞこれを嫌がらないでください。\n\nポリュクス"
  },
  Mail_94503_Name = {
    Text = "羽根の冠……"
  },
  Mail_94503_Sender = {
    Text = "ポリュクス"
  },
  Mail_95382_Desc = {
    Text = "可愛い小さな存在：\n\n小さな存在、今日は私が降り立った日だ。\n燃え続ける大火球としてではなく、ケティグラと呼ばれる女の子の誕生日だ。\n生前の習慣に従って、この日は盛大な晩餐会を開き、自由に美酒や焼肉を楽しむ。 \nもちろん、雰囲気を気にせず私の歳を一つ増やしてからかう小馬鹿もいるので、私は彼らの頭に拳を見舞った。 \n今、この宴会には新たな機能が追加され、過去の時間を懐かしむためのものである。 \n今年はさらに一つのイベントを加える、それは——私たちの小さな存在を狩ることだ！ \n知っているかい、私はもうあなたを私の宴会に捕まえるのが待ちきれなくて、あなたの恥ずかしげな表情、半分酔ったような瞳、内から漂う甘い香りで、今年の私の誕生日の晩餐会を飾りたい、それが私の生まれて以来得た最良の誕生日プレゼントになるよ！ \n今から逃走計画を準備するには遅すぎる、なぜならあなたがこの手紙を見たとき…………私はすでにあなたの門前に来ているのだから。 \n怖がらないで、小さな存在、すべてが正常であれば、あなたはここで最良の物語を聞き、最も美味しい食事を味わうだけだ。 \nもちろん、捕まる小さな獣が何かの事故に遭うのも普通だろう。 \nおとなしく私について来て、小さな存在、今晩あなたの素晴らしい時間は私と一緒に過ごす運命なのだ。 \n\nケティグラ"
  },
