  Mail_96323_Desc = {
    Text = "守秘者殿下：\n\n生者が誕生日を祝うのは、余命の中で意味を拾い上げるためです。しかし私はこの夜を借りて、死の香りをさらに豊かに煮立てています。\nもはや苦しむことのない、執着を持たない亡者たちは、生前のすべての汚れが洗い流され、その悔恨は細かい塩のように火の通りがちょうど良いときに血線の間に溶け込み、湿度のある温かい香りを形成します。彼らの骨格は低く裂ける音を立て、皮膚から染み出る脂は薄荷のように上品で、魂の奥深くの未完の言葉が煮込まれるうちにゆっくりと漏れ出し、繊細で甘美な余韻を残します。私はすでにあなたが静かなものに変わる姿を幻想し始めました——皮膚が炉火の前で引き締まりぎしぎし音を立て、骨肉の間から蒸発する感情、あなたの純粋な魂が徐々に食べ尽くされる甘美な感触…………\nしかしあなたは違います。\nあなたは今なお輝いていて、跳ねており、他の亡者には到底比類のない香りを持っています。それは心を奪われるものです。あなたは私が待つ価値のある熟成であり、私はこの待つことが永遠よりも長く続くことを願っています。\nこの無限に繰り返される年輪の中で、あなたの出現は私の誕生日に意味を与えました。ただ素晴らしい食事のためではなく、あなたが今も躍動している命のためです。\n\nドゥルセイン"
